static double wall_seconds() {
    using clock = std::chrono::steady_clock;
    return std::chrono::duration<double>(clock::now().time_since_epoch()).count();
}

static py::object tuple_from_sequence_object(const py::object& value);

static void add_long_attr(py::object obj, const char* name, long long amount) {
    long long current = 0;
    try {
        current = py::cast<long long>(py::getattr(obj, name, py::int_(0)));
    } catch (const py::error_already_set&) {
        PyErr_Clear();
    } catch (const py::cast_error&) {
    }
    py::setattr(obj, name, py::int_(current + amount));
}

static std::string py_handle_identity(py::handle obj) {
    return std::to_string(reinterpret_cast<std::uintptr_t>(obj.ptr()));
}

struct Block {
    const cdouble* data;
    ssize_t rows;
    ssize_t cols;
    ssize_t row_stride;
    ssize_t col_stride;
    ssize_t in_start;
    ssize_t out_start;
};

struct SparseBlock {
    const long long* rows;
    const long long* cols;
    const cdouble* values;
    ssize_t nnz;
    ssize_t in_start;
    ssize_t out_start;
};

static double norm2(const std::vector<cdouble>& v) {
    double s = 0.0;
    for (const auto& x : v) {
        s += std::norm(x);
    }
    return std::sqrt(s);
}

static cdouble dotc(const std::vector<cdouble>& a, const std::vector<cdouble>& b) {
    cdouble s = 0.0;
    const ssize_t n = static_cast<ssize_t>(a.size());
    for (ssize_t i = 0; i < n; ++i) {
        s += std::conj(a[i]) * b[i];
    }
    return s;
}

static void axpy(std::vector<cdouble>& y, cdouble a, const std::vector<cdouble>& x) {
    const ssize_t n = static_cast<ssize_t>(y.size());
    for (ssize_t i = 0; i < n; ++i) {
        y[i] += a * x[i];
    }
}

static std::vector<cdouble> matvec_blocks(
    const std::vector<Block>& blocks,
    const std::vector<cdouble>& x,
    ssize_t dim
) {
    std::vector<cdouble> out(static_cast<size_t>(dim), cdouble(0.0, 0.0));
    for (const auto& block : blocks) {
        for (ssize_t row = 0; row < block.rows; ++row) {
            cdouble total = 0.0;
            const cdouble* row_ptr = block.data + row * block.row_stride;
            for (ssize_t col = 0; col < block.cols; ++col) {
                total += row_ptr[col * block.col_stride] * x[static_cast<size_t>(block.in_start + col)];
            }
            out[static_cast<size_t>(block.out_start + row)] += total;
        }
    }
    return out;
}

static py::tuple lapack_svd(py::object matrix_obj) {
#ifndef __APPLE__
    throw std::runtime_error("lapack_svd is only enabled on macOS Accelerate builds");
#else
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> matrix =
        py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(matrix_obj);
    if (!matrix) {
        throw std::runtime_error("lapack_svd expects a dense matrix");
    }
    if (matrix.ndim() != 2) {
        throw std::runtime_error("lapack_svd expects a rank-2 matrix");
    }
    const int m = static_cast<int>(matrix.shape(0));
    const int n = static_cast<int>(matrix.shape(1));
    const int k = std::min(m, n);
    py::array_t<cdouble> u_out({m, k});
    py::array_t<double> s_out({k});
    py::array_t<cdouble> vt_out({k, n});
    if (m == 0 || n == 0) {
        return py::make_tuple(u_out, s_out, vt_out);
    }
    const int lda = std::max(1, m);
    const int ldu = std::max(1, m);
    const int ldvt = std::max(1, k);
    std::vector<cdouble> a(static_cast<size_t>(lda) * static_cast<size_t>(n));
    auto mat = matrix.unchecked<2>();
    for (int row = 0; row < m; ++row) {
        for (int col = 0; col < n; ++col) {
            a[static_cast<size_t>(row) + static_cast<size_t>(col) * static_cast<size_t>(lda)] =
                mat(row, col);
        }
    }
    std::vector<double> s(static_cast<size_t>(k));
    std::vector<cdouble> u(static_cast<size_t>(ldu) * static_cast<size_t>(k));
    std::vector<cdouble> vt(static_cast<size_t>(ldvt) * static_cast<size_t>(n));
    std::vector<double> rwork(static_cast<size_t>(std::max(1, 5 * k)));
    char jobu = 'S';
    char jobvt = 'S';
    int m_arg = m;
    int n_arg = n;
    int lda_arg = lda;
    int ldu_arg = ldu;
    int ldvt_arg = ldvt;
    int info = 0;
    int lwork = -1;
    cdouble work_query;
    zgesvd_(
        &jobu,
        &jobvt,
        &m_arg,
        &n_arg,
        a.data(),
        &lda_arg,
        s.data(),
        u.data(),
        &ldu_arg,
        vt.data(),
        &ldvt_arg,
        &work_query,
        &lwork,
        rwork.data(),
        &info
    );
    if (info != 0) {
        throw std::runtime_error("zgesvd workspace query failed");
    }
    lwork = std::max(1, static_cast<int>(std::real(work_query)));
    std::vector<cdouble> work(static_cast<size_t>(lwork));
    zgesvd_(
        &jobu,
        &jobvt,
        &m_arg,
        &n_arg,
        a.data(),
        &lda_arg,
        s.data(),
        u.data(),
        &ldu_arg,
        vt.data(),
        &ldvt_arg,
        work.data(),
        &lwork,
        rwork.data(),
        &info
    );
    if (info != 0) {
        throw std::runtime_error("zgesvd failed to converge");
    }
    auto u_view = u_out.mutable_unchecked<2>();
    auto s_view = s_out.mutable_unchecked<1>();
    auto vt_view = vt_out.mutable_unchecked<2>();
    for (int col = 0; col < k; ++col) {
        s_view(col) = s[static_cast<size_t>(col)];
        for (int row = 0; row < m; ++row) {
            u_view(row, col) =
                u[static_cast<size_t>(row) + static_cast<size_t>(col) * static_cast<size_t>(ldu)];
        }
    }
    for (int col = 0; col < n; ++col) {
        for (int row = 0; row < k; ++row) {
            vt_view(row, col) =
                vt[static_cast<size_t>(row) + static_cast<size_t>(col) * static_cast<size_t>(ldvt)];
        }
    }
    return py::make_tuple(u_out, s_out, vt_out);
#endif
}

static py::tuple lapack_qr(py::object matrix_obj) {
#ifndef __APPLE__
    throw std::runtime_error("lapack_qr is only enabled on macOS Accelerate builds");
#else
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> matrix =
        py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(matrix_obj);
    if (!matrix) {
        throw std::runtime_error("lapack_qr expects a dense matrix");
    }
    if (matrix.ndim() != 2) {
        throw std::runtime_error("lapack_qr expects a rank-2 matrix");
    }
    const int m = static_cast<int>(matrix.shape(0));
    const int n = static_cast<int>(matrix.shape(1));
    const int k = std::min(m, n);
    py::array_t<cdouble> q_out({m, k});
    py::array_t<cdouble> r_out({k, n});
    if (m == 0 || n == 0 || k == 0) {
        return py::make_tuple(q_out, r_out);
    }

    const int lda = std::max(1, m);
    std::vector<cdouble> a(static_cast<size_t>(lda) * static_cast<size_t>(n));
    auto mat = matrix.unchecked<2>();
    for (int row = 0; row < m; ++row) {
        for (int col = 0; col < n; ++col) {
            a[static_cast<size_t>(row) + static_cast<size_t>(col) * static_cast<size_t>(lda)] =
                mat(row, col);
        }
    }

    std::vector<cdouble> tau(static_cast<size_t>(k));
    int m_arg = m;
    int n_arg = n;
    int lda_arg = lda;
    int info = 0;
    int lwork = -1;
    cdouble work_query;
    zgeqrf_(
        &m_arg,
        &n_arg,
        a.data(),
        &lda_arg,
        tau.data(),
        &work_query,
        &lwork,
        &info
    );
    if (info != 0) {
        throw std::runtime_error("zgeqrf workspace query failed with info=" + std::to_string(info));
    }
    lwork = std::max(1, static_cast<int>(std::real(work_query)));
    std::vector<cdouble> work(static_cast<size_t>(lwork));
    zgeqrf_(
        &m_arg,
        &n_arg,
        a.data(),
        &lda_arg,
        tau.data(),
        work.data(),
        &lwork,
        &info
    );
    if (info != 0) {
        throw std::runtime_error("zgeqrf failed with info=" + std::to_string(info));
    }

    auto r = r_out.mutable_unchecked<2>();
    for (int row = 0; row < k; ++row) {
        for (int col = 0; col < n; ++col) {
            r(row, col) = (row <= col)
                ? a[static_cast<size_t>(row) + static_cast<size_t>(col) * static_cast<size_t>(lda)]
                : cdouble(0.0, 0.0);
        }
    }

    int q_m = m;
    int q_n = k;
    int q_k = k;
    lwork = -1;
    zungqr_(
        &q_m,
        &q_n,
        &q_k,
        a.data(),
        &lda_arg,
        tau.data(),
        &work_query,
        &lwork,
        &info
    );
    if (info != 0) {
        throw std::runtime_error("zungqr workspace query failed with info=" + std::to_string(info));
    }
    lwork = std::max(1, static_cast<int>(std::real(work_query)));
    work.assign(static_cast<size_t>(lwork), cdouble(0.0, 0.0));
    zungqr_(
        &q_m,
        &q_n,
        &q_k,
        a.data(),
        &lda_arg,
        tau.data(),
        work.data(),
        &lwork,
        &info
    );
    if (info != 0) {
        throw std::runtime_error("zungqr failed with info=" + std::to_string(info));
    }

    auto q = q_out.mutable_unchecked<2>();
    for (int row = 0; row < m; ++row) {
        for (int col = 0; col < k; ++col) {
            q(row, col) =
                a[static_cast<size_t>(row) + static_cast<size_t>(col) * static_cast<size_t>(lda)];
        }
    }
    return py::make_tuple(q_out, r_out);
#endif
}

struct HermitianEigenResult {
    ssize_t n = 0;
    std::vector<double> values_desc;
    std::vector<cdouble> vectors_desc;

    cdouble vector(ssize_t row, ssize_t col) const {
        return vectors_desc[
            static_cast<size_t>(row * n + col)
        ];
    }
};

static void normalize_eigenvector_phase(std::vector<cdouble>& vec) {
    ssize_t best = 0;
    double best_abs = 0.0;
    for (ssize_t idx = 0; idx < static_cast<ssize_t>(vec.size()); ++idx) {
        const double mag = std::abs(vec[static_cast<size_t>(idx)]);
        if (mag > best_abs) {
            best_abs = mag;
            best = idx;
        }
    }
    if (best_abs <= 0.0) {
        return;
    }
    const cdouble pivot = vec[static_cast<size_t>(best)];
    const cdouble phase = std::conj(pivot) / best_abs;
    for (cdouble& value : vec) {
        value *= phase;
    }
}

static HermitianEigenResult lapack_hermitian_eigh_descending(py::object matrix_obj) {
#ifndef __APPLE__
    throw std::runtime_error("Hermitian Gram eigensolver is only enabled on macOS Accelerate builds");
#else
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> matrix =
        py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(matrix_obj);
    if (!matrix) {
        throw std::runtime_error("Hermitian eigensolver expects a dense matrix");
    }
    if (matrix.ndim() != 2 || matrix.shape(0) != matrix.shape(1)) {
        throw std::runtime_error("Hermitian eigensolver expects a square rank-2 matrix");
    }
    const int n = static_cast<int>(matrix.shape(0));
    HermitianEigenResult result;
    result.n = static_cast<ssize_t>(n);
    result.values_desc.assign(static_cast<size_t>(n), 0.0);
    result.vectors_desc.assign(
        static_cast<size_t>(n) * static_cast<size_t>(n),
        cdouble(0.0, 0.0)
    );
    if (n == 0) {
        return result;
    }

    const int lda = std::max(1, n);
    std::vector<cdouble> a(static_cast<size_t>(lda) * static_cast<size_t>(n));
    auto mat = matrix.unchecked<2>();
    for (int row = 0; row < n; ++row) {
        for (int col = 0; col < n; ++col) {
            a[static_cast<size_t>(row) + static_cast<size_t>(col) * static_cast<size_t>(lda)] =
                mat(row, col);
        }
    }
    std::vector<double> w(static_cast<size_t>(n));
    std::vector<double> rwork(static_cast<size_t>(std::max(1, 3 * n - 2)));
    char jobz = 'V';
    char uplo = 'U';
    int n_arg = n;
    int lda_arg = lda;
    int info = 0;
    int lwork = -1;
    cdouble work_query;
    zheev_(
        &jobz,
        &uplo,
        &n_arg,
        a.data(),
        &lda_arg,
        w.data(),
        &work_query,
        &lwork,
        rwork.data(),
        &info
    );
    if (info != 0) {
        throw std::runtime_error("zheev workspace query failed");
    }
    lwork = std::max(1, static_cast<int>(std::real(work_query)));
    std::vector<cdouble> work(static_cast<size_t>(lwork));
    zheev_(
        &jobz,
        &uplo,
        &n_arg,
        a.data(),
        &lda_arg,
        w.data(),
        work.data(),
        &lwork,
        rwork.data(),
        &info
    );
    if (info != 0) {
        throw std::runtime_error("zheev failed to converge");
    }

    for (int out_col = 0; out_col < n; ++out_col) {
        const int in_col = n - 1 - out_col;
        result.values_desc[static_cast<size_t>(out_col)] =
            w[static_cast<size_t>(in_col)];
        std::vector<cdouble> vec(static_cast<size_t>(n));
        for (int row = 0; row < n; ++row) {
            vec[static_cast<size_t>(row)] =
                a[static_cast<size_t>(row) + static_cast<size_t>(in_col) * static_cast<size_t>(lda)];
        }
        normalize_eigenvector_phase(vec);
        for (int row = 0; row < n; ++row) {
            result.vectors_desc[
                static_cast<size_t>(row) * static_cast<size_t>(n)
                + static_cast<size_t>(out_col)
            ] = vec[static_cast<size_t>(row)];
        }
    }
    return result;
#endif
}

