    void install_compact_plan(
        const std::string& key,
        py::object py_plan,
        py::array_t<long long, py::array::c_style | py::array::forcecast> py_routes,
        ssize_t dim,
        ssize_t layout_blocks
    ) {
        if (dim <= 0) {
            throw std::runtime_error("MovingEnvironment compact plan dimension must be positive");
        }
        CppCompactPlan* plan = py::cast<CppCompactPlan*>(py_plan);
        if (plan == nullptr) {
            throw std::runtime_error("MovingEnvironment expected a CompactPlan object");
        }
        if (plan->dim != dim) {
            throw std::runtime_error("MovingEnvironment compact plan dimension mismatch");
        }
        auto it = compact_records.find(key);
        if (it == compact_records.end()) {
            CompactRecord record;
            record.owner = py_plan;
            record.plan = plan;
            record.diagonal_routes = py_routes;
            record.dim = dim;
            record.layout_blocks = layout_blocks;
            record.diagonal_valid = false;
            compact_records.emplace(key, std::move(record));
        } else {
            CompactRecord& record = it->second;
            if (record.plan != plan || record.dim != dim || record.layout_blocks != layout_blocks) {
                ++compact_plan_replacements;
            }
            record.owner = py_plan;
            record.plan = plan;
            record.diagonal_routes = py_routes;
            record.dim = dim;
            record.layout_blocks = layout_blocks;
            record.diagonal_valid = false;
        }
        ++compact_plan_installs;
    }

    void invalidate_diagonal(const std::string& key) {
        CompactRecord& record = record_for(key);
        record.diagonal_valid = false;
    }

    py::array_t<cdouble> matvec(
        const std::string& key,
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_vec
    ) {
        CompactRecord& record = record_for(key);
        ++compact_plan_matvec_calls;
        return record.plan->matvec(py_vec);
    }

    py::array_t<cdouble> diagonal(const std::string& key) {
        CompactRecord& record = record_for(key);
        if (record.diagonal_valid) {
            ++compact_plan_diagonal_cache_hits;
            return array_from_vector(record.diagonal_cache);
        }
        py::array_t<cdouble> py_diag = record.plan->diagonal_from_routes(
            record.diagonal_routes
        );
        auto diag = py_diag.unchecked<1>();
        if (diag.shape(0) != record.dim) {
            throw std::runtime_error("MovingEnvironment diagonal dimension mismatch");
        }
        record.diagonal_cache.resize(static_cast<size_t>(record.dim));
        for (ssize_t i = 0; i < record.dim; ++i) {
            record.diagonal_cache[static_cast<size_t>(i)] = diag(i);
        }
        record.diagonal_valid = true;
        ++compact_plan_diagonal_calls;
        return array_from_vector(record.diagonal_cache);
    }

    py::dict davidson(
        const std::string& key,
        py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_v0,
        double tol,
        int max_iter,
        int restart_dim,
        bool accept_unconverged
    ) {
        CompactRecord& record = record_for(key);
        ensure_diagonal(record);
        auto v0 = py_v0.unchecked<1>();
        if (v0.shape(0) != record.dim) {
            throw std::runtime_error("MovingEnvironment Davidson vector dimension mismatch");
        }
        std::vector<cdouble> v(static_cast<size_t>(record.dim));
        for (ssize_t i = 0; i < record.dim; ++i) {
            v[static_cast<size_t>(i)] = v0(i);
        }
        const bool reused = record.davidson_workspace.initialized;
        py::dict out = ::davidson(
            record.dim,
            record.diagonal_cache,
            std::move(v),
            tol,
            max_iter,
            restart_dim,
            accept_unconverged,
            record.davidson_workspace,
            [&record](const std::vector<cdouble>& x) {
                return record.plan->matvec_vector(x);
            }
        );
        ++compact_plan_davidson_calls;
        if (reused) {
            ++compact_plan_davidson_workspace_reuses;
        }
        return out;
    }

