    static std::string grouped_table_key_from_bond_hint(py::object bond_hint) {
        if (bond_hint.is_none()) {
            return "grouped-table-bond:None";
        }
        try {
            const ssize_t bond = py::cast<ssize_t>(bond_hint);
            return "grouped-table-bond:" + std::to_string(static_cast<long long>(bond));
        } catch (const py::cast_error&) {
            return "grouped-table-bond:" + py::str(bond_hint).cast<std::string>();
        }
    }

    static void update_layout_hash(uint64_t& hash, const std::string& text) {
        for (unsigned char ch : text) {
            hash ^= static_cast<uint64_t>(ch);
            hash *= 1099511628211ULL;
        }
    }

    static void update_layout_hash_int(uint64_t& hash, ssize_t value) {
        update_layout_hash(hash, std::to_string(static_cast<long long>(value)));
        update_layout_hash(hash, "|");
    }

    static std::string grouped_table_layout_signature(py::object layout) {
        py::sequence rows = layout.cast<py::sequence>();
        uint64_t hash = 1469598103934665603ULL;
        ssize_t flat_dim = 0;
        const ssize_t n_rows = static_cast<ssize_t>(py::len(rows));
        update_layout_hash_int(hash, n_rows);
        for (ssize_t row = 0; row < n_rows; ++row) {
            py::tuple item = tuple_from_sequence_object(
                py::reinterpret_borrow<py::object>(rows[row])
            ).cast<py::tuple>();
            if (py::len(item) < 2) {
                throw std::runtime_error("flat layout rows must be (key, shape)");
            }
            update_layout_hash(
                hash,
                py::repr(py::reinterpret_borrow<py::object>(item[0])).cast<std::string>()
            );
            update_layout_hash(hash, "#");
            py::tuple shape = tuple_from_sequence_object(
                py::reinterpret_borrow<py::object>(item[1])
            ).cast<py::tuple>();
            ssize_t block = 1;
            update_layout_hash_int(hash, static_cast<ssize_t>(py::len(shape)));
            for (ssize_t axis = 0; axis < static_cast<ssize_t>(py::len(shape)); ++axis) {
                const ssize_t dim = py::cast<ssize_t>(shape[axis]);
                if (dim < 0) {
                    throw std::runtime_error("flat layout dimensions must be nonnegative");
                }
                block *= dim;
                update_layout_hash_int(hash, dim);
            }
            flat_dim += block;
            update_layout_hash(hash, ";");
        }
        return std::to_string(static_cast<long long>(n_rows))
            + ":"
            + std::to_string(static_cast<long long>(flat_dim))
            + ":"
            + std::to_string(hash);
    }

    static py::object grouped_table_hint_from_layout(
        py::object bond_hint,
        py::object layout
    ) {
        std::string bond_text;
        if (bond_hint.is_none()) {
            bond_text = "None";
        } else {
            bond_text = py::str(bond_hint).cast<std::string>();
        }
        return py::str(
            bond_text + "|layout=" + grouped_table_layout_signature(layout)
        );
    }

