    py::tuple environment_advance(
        const std::string& key,
        const std::string& direction,
        py::object W,
        py::object A,
        py::object env,
        py::object B,
        const std::string& signature = ""
    );

    static std::string tensor_key_signature_text(py::object tensor) {
        std::vector<std::string> keys;
        try {
            py::dict data = py::reinterpret_borrow<py::dict>(tensor.attr("data"));
            keys.reserve(static_cast<size_t>(py::len(data)));
            for (auto item : data) {
                keys.push_back(
                    py::repr(py::reinterpret_borrow<py::object>(item.first))
                        .cast<std::string>()
                );
            }
        } catch (...) {
            return "object@" + py_handle_identity(tensor);
        }
        std::sort(keys.begin(), keys.end());
        std::string out = std::to_string(keys.size()) + "[";
        for (const auto& key : keys) {
            out += std::to_string(key.size()) + ":" + key + ";";
        }
        out += "]";
        return out;
    }

    static std::string environment_advance_signature(
        const std::string& direction,
        py::object W,
        py::object A,
        py::object env,
        py::object B
    ) {
        return direction
            + "|W=" + tensor_key_signature_text(W)
            + "|A=" + tensor_key_signature_text(A)
            + "|E=" + tensor_key_signature_text(env)
            + "|B=" + tensor_key_signature_text(B);
    }

    static std::string environment_advance_auto_key(
        const std::string& direction,
        const std::string& stack_key
    ) {
        return "environment-plan-auto:" + direction + ":" + stack_key;
    }

    py::tuple environment_advance_auto(
        const std::string& stack_key,
        const std::string& direction,
        py::object W,
        py::object A,
        py::object env,
        py::object B
    ) {
        return environment_advance(
            environment_advance_auto_key(direction, stack_key),
            direction,
            W,
            A,
            env,
            B,
            environment_advance_signature(direction, W, A, env, B)
        );
    }

