    void install_direct_family_payload(
        const std::string& key,
        py::object payload
    ) {
        auto it = direct_family_payload_records.find(key);
        if (it == direct_family_payload_records.end()) {
            direct_family_payload_records.emplace(key, std::move(payload));
        } else {
            it->second = std::move(payload);
            ++direct_family_payload_replacements;
        }
        ++direct_family_payload_installs;
    }

    py::object direct_family_payload(const std::string& key) {
        auto it = direct_family_payload_records.find(key);
        if (it == direct_family_payload_records.end()) {
            ++direct_family_payload_misses;
            return py::none();
        }
        ++direct_family_payload_hits;
        return it->second;
    }

    static bool direct_family_payload_piece_empty(const py::object& piece) {
        if (piece.is_none()) {
            return true;
        }
        try {
            return static_cast<ssize_t>(py::len(piece)) == 0;
        } catch (const py::error_already_set&) {
            PyErr_Clear();
            return false;
        } catch (const std::exception&) {
            return false;
        }
    }

    static bool is_composite_direct_family_payload_piece(py::handle obj) {
        if (!obj || obj.is_none()) {
            return false;
        }
        if (
            PyObject_HasAttrString(
                obj.ptr(),
                "_pyqed_composite_direct_family_entries"
            ) != 1
        ) {
            return false;
        }
        try {
            return py::cast<bool>(
                py::reinterpret_borrow<py::object>(obj).attr(
                    "_pyqed_composite_direct_family_entries"
                )
            );
        } catch (const py::error_already_set&) {
            PyErr_Clear();
            return false;
        } catch (const py::cast_error&) {
            return false;
        }
    }

    static py::object composite_direct_family_payload_piece(py::object entries) {
        if (is_composite_direct_family_payload_piece(entries)) {
            return entries;
        }
        if (PyObject_HasAttrString(entries.ptr(), "entries") == 1) {
            py::object nested = entries.attr("entries");
            if (is_composite_direct_family_payload_piece(nested)) {
                return nested;
            }
        }
        return py::none();
    }

    static bool is_packed_direct_family_payload_piece(py::handle obj) {
        if (!obj || obj.is_none()) {
            return false;
        }
        if (
            PyObject_HasAttrString(
                obj.ptr(),
                "_pyqed_packed_direct_family_entries"
            ) != 1
        ) {
            return false;
        }
        try {
            return py::cast<bool>(
                py::reinterpret_borrow<py::object>(obj).attr(
                    "_pyqed_packed_direct_family_entries"
                )
            );
        } catch (const py::error_already_set&) {
            PyErr_Clear();
            return false;
        } catch (const py::cast_error&) {
            return false;
        }
    }

    static py::object packed_direct_family_payload_piece(py::object entries) {
        if (is_packed_direct_family_payload_piece(entries)) {
            return entries;
        }
        if (PyObject_HasAttrString(entries.ptr(), "entries") == 1) {
            py::object nested = entries.attr("entries");
            if (is_packed_direct_family_payload_piece(nested)) {
                return nested;
            }
        }
        return py::none();
    }

    py::object merge_direct_family_payload_piece(
        py::object old,
        py::object piece,
        py::object composite_cls,
        py::object packed_cls
    ) {
        if (old.is_none()) {
            return piece;
        }
        if (piece.is_none()) {
            return old;
        }
        py::object old_packed = packed_direct_family_payload_piece(old);
        py::object piece_packed = packed_direct_family_payload_piece(piece);
        if (!old_packed.is_none() && !piece_packed.is_none()) {
            old_packed.attr("extend")(piece_packed);
            return old;
        }
        if (!old_packed.is_none()) {
            try {
                old_packed.attr("extend")(piece);
                return old;
            } catch (const py::error_already_set&) {
                PyErr_Clear();
            }
        }
        if (!piece_packed.is_none() && !packed_cls.is_none()) {
            try {
                py::object merged = packed_cls();
                merged.attr("extend")(old);
                merged.attr("extend")(piece_packed);
                return merged;
            } catch (const py::error_already_set&) {
                PyErr_Clear();
            }
        }
        py::object composite =
            composite_direct_family_payload_piece(old);
        if (!composite.is_none()) {
            composite.attr("append")(piece);
            return old;
        }
        if (!composite_cls.is_none()) {
            py::tuple parts(2);
            parts[0] = old;
            parts[1] = piece;
            return composite_cls(parts);
        }
        py::list merged;
        py::sequence old_seq = old.cast<py::sequence>();
        py::sequence piece_seq = piece.cast<py::sequence>();
        for (auto item : old_seq) {
            merged.append(py::reinterpret_borrow<py::object>(item));
        }
        for (auto item : piece_seq) {
            merged.append(py::reinterpret_borrow<py::object>(item));
        }
        return py::tuple(merged);
    }

    py::dict assemble_direct_family_payload(
        const std::string& key,
        py::sequence family_names,
        py::sequence pieces,
        py::object composite_cls = py::none(),
        py::object packed_cls = py::none(),
        bool install = true
    ) {
        ++direct_family_payload_assembler_calls;
        const double start = wall_seconds();
        py::dict out;
        try {
            const ssize_t n = static_cast<ssize_t>(py::len(family_names));
            if (static_cast<ssize_t>(py::len(pieces)) != n) {
                throw std::runtime_error(
                    "direct-family payload assembler family/piece length mismatch"
                );
            }
            long long nonempty = 0;
            long long merges = 0;
            long long empty = 0;
            for (ssize_t idx = 0; idx < n; ++idx) {
                py::object piece = py::reinterpret_borrow<py::object>(
                    pieces[idx]
                );
                if (direct_family_payload_piece_empty(piece)) {
                    ++empty;
                    continue;
                }
                py::str family = py::str(family_names[idx]);
                if (out.contains(family)) {
                    py::object old = py::reinterpret_borrow<py::object>(
                        out[family]
                    );
                    out[family] = merge_direct_family_payload_piece(
                        old,
                        piece,
                        composite_cls,
                        packed_cls
                    );
                    ++merges;
                } else {
                    out[family] = piece;
                }
                ++nonempty;
            }
            if (install && !key.empty()) {
                install_direct_family_payload(key, out);
            }
            ++direct_family_payload_assembler_builds;
            direct_family_payload_assembler_families +=
                static_cast<long long>(py::len(out));
            direct_family_payload_assembler_pieces += nonempty;
            direct_family_payload_assembler_merges += merges;
            direct_family_payload_assembler_empty_pieces += empty;
            const double elapsed = wall_seconds() - start;
            direct_family_payload_assembler_seconds += elapsed;
            direct_family_payload_assembler_last_seconds = elapsed;
            direct_family_payload_assembler_last_error.clear();
            return out;
        } catch (const py::error_already_set& exc) {
            ++direct_family_payload_assembler_failures;
            const double elapsed = wall_seconds() - start;
            direct_family_payload_assembler_seconds += elapsed;
            direct_family_payload_assembler_last_seconds = elapsed;
            direct_family_payload_assembler_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++direct_family_payload_assembler_failures;
            const double elapsed = wall_seconds() - start;
            direct_family_payload_assembler_seconds += elapsed;
            direct_family_payload_assembler_last_seconds = elapsed;
            direct_family_payload_assembler_last_error = exc.what();
            throw;
        }
    }

    py::dict build_direct_family_payload_from_piece_builders(
        const std::string& key,
        py::sequence initial_family_names,
        py::sequence initial_pieces,
        py::sequence builder_family_names,
        py::sequence builders,
        py::object composite_cls = py::none(),
        py::object packed_cls = py::none(),
        bool install = true
    ) {
        ++direct_family_piece_builder_plan_calls;
        const double start = wall_seconds();
        try {
            const ssize_t n_initial =
                static_cast<ssize_t>(py::len(initial_family_names));
            if (static_cast<ssize_t>(py::len(initial_pieces)) != n_initial) {
                throw std::runtime_error(
                    "direct-family piece plan initial family/piece length mismatch"
                );
            }
            const ssize_t n_builders =
                static_cast<ssize_t>(py::len(builder_family_names));
            if (static_cast<ssize_t>(py::len(builders)) != n_builders) {
                throw std::runtime_error(
                    "direct-family piece plan family/builder length mismatch"
                );
            }
            py::list families;
            py::list pieces;
            for (ssize_t idx = 0; idx < n_initial; ++idx) {
                families.append(initial_family_names[idx]);
                pieces.append(initial_pieces[idx]);
            }
            long long built = 0;
            long long nonempty = 0;
            long long empty = 0;
            long long entries = 0;
            for (ssize_t idx = 0; idx < n_builders; ++idx) {
                py::object builder = py::reinterpret_borrow<py::object>(
                    builders[idx]
                );
                if (builder.is_none() || !PyCallable_Check(builder.ptr())) {
                    throw std::runtime_error(
                        "direct-family piece builder must be callable"
                    );
                }
                py::object piece = builder();
                families.append(builder_family_names[idx]);
                pieces.append(piece);
                ++built;
                if (direct_family_payload_piece_empty(piece)) {
                    ++empty;
                    continue;
                }
                ++nonempty;
                entries += direct_family_payload_entry_count(piece);
            }
            py::dict payload = assemble_direct_family_payload(
                key,
                families,
                pieces,
                composite_cls,
                packed_cls,
                install
            );
            ++direct_family_piece_builder_plan_builds;
            direct_family_piece_builder_plan_families += built;
            direct_family_piece_builder_plan_pieces += nonempty;
            direct_family_piece_builder_plan_entries += entries;
            direct_family_piece_builder_plan_empty_pieces += empty;
            const double elapsed = wall_seconds() - start;
            direct_family_piece_builder_plan_seconds += elapsed;
            direct_family_piece_builder_plan_last_seconds = elapsed;
            direct_family_piece_builder_plan_last_error.clear();
            return payload;
        } catch (const py::error_already_set& exc) {
            ++direct_family_piece_builder_plan_failures;
            const double elapsed = wall_seconds() - start;
            direct_family_piece_builder_plan_seconds += elapsed;
            direct_family_piece_builder_plan_last_seconds = elapsed;
            direct_family_piece_builder_plan_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++direct_family_piece_builder_plan_failures;
            const double elapsed = wall_seconds() - start;
            direct_family_piece_builder_plan_seconds += elapsed;
            direct_family_piece_builder_plan_last_seconds = elapsed;
            direct_family_piece_builder_plan_last_error = exc.what();
            throw;
        }
    }

    py::dict build_direct_family_payload_from_phased_piece_builders(
        const std::string& key,
        py::sequence first_family_names,
        py::sequence first_builders,
        py::object second_builder_factory,
        py::object composite_cls = py::none(),
        py::object packed_cls = py::none(),
        bool install = true
    ) {
        ++direct_family_piece_builder_plan_calls;
        const double start = wall_seconds();
        try {
            const ssize_t n_first =
                static_cast<ssize_t>(py::len(first_family_names));
            if (static_cast<ssize_t>(py::len(first_builders)) != n_first) {
                throw std::runtime_error(
                    "direct-family phased piece plan family/builder length mismatch"
                );
            }
            py::list families;
            py::list pieces;
            long long built = 0;
            long long nonempty = 0;
            long long empty = 0;
            long long entries = 0;
            auto run_builder = [&](py::object family, py::object builder) {
                if (builder.is_none() || !PyCallable_Check(builder.ptr())) {
                    throw std::runtime_error(
                        "direct-family phased piece builder must be callable"
                    );
                }
                py::object piece = builder();
                families.append(family);
                pieces.append(piece);
                ++built;
                if (direct_family_payload_piece_empty(piece)) {
                    ++empty;
                    return;
                }
                ++nonempty;
                entries += direct_family_payload_entry_count(piece);
            };
            for (ssize_t idx = 0; idx < n_first; ++idx) {
                run_builder(
                    py::reinterpret_borrow<py::object>(first_family_names[idx]),
                    py::reinterpret_borrow<py::object>(first_builders[idx])
                );
            }
            if (
                !second_builder_factory.is_none() &&
                PyCallable_Check(second_builder_factory.ptr())
            ) {
                py::object second = second_builder_factory();
                if (!second.is_none()) {
                    if (static_cast<ssize_t>(py::len(second)) < 2) {
                        throw std::runtime_error(
                            "direct-family phased piece factory must return "
                            "(family_names, builders)"
                        );
                    }
                    py::sequence second_seq = second.cast<py::sequence>();
                    py::sequence second_names =
                        second_seq[0].cast<py::sequence>();
                    py::sequence second_builders =
                        second_seq[1].cast<py::sequence>();
                    const ssize_t n_second =
                        static_cast<ssize_t>(py::len(second_names));
                    if (
                        static_cast<ssize_t>(py::len(second_builders))
                        != n_second
                    ) {
                        throw std::runtime_error(
                            "direct-family phased contextual family/builder "
                            "length mismatch"
                        );
                    }
                    for (ssize_t idx = 0; idx < n_second; ++idx) {
                        run_builder(
                            py::reinterpret_borrow<py::object>(second_names[idx]),
                            py::reinterpret_borrow<py::object>(
                                second_builders[idx]
                            )
                        );
                    }
                }
            }
            py::dict payload = assemble_direct_family_payload(
                key,
                families,
                pieces,
                composite_cls,
                packed_cls,
                install
            );
            ++direct_family_piece_builder_plan_builds;
            direct_family_piece_builder_plan_families += built;
            direct_family_piece_builder_plan_pieces += nonempty;
            direct_family_piece_builder_plan_entries += entries;
            direct_family_piece_builder_plan_empty_pieces += empty;
            const double elapsed = wall_seconds() - start;
            direct_family_piece_builder_plan_seconds += elapsed;
            direct_family_piece_builder_plan_last_seconds = elapsed;
            direct_family_piece_builder_plan_last_error.clear();
            return payload;
        } catch (const py::error_already_set& exc) {
            ++direct_family_piece_builder_plan_failures;
            const double elapsed = wall_seconds() - start;
            direct_family_piece_builder_plan_seconds += elapsed;
            direct_family_piece_builder_plan_last_seconds = elapsed;
            direct_family_piece_builder_plan_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++direct_family_piece_builder_plan_failures;
            const double elapsed = wall_seconds() - start;
            direct_family_piece_builder_plan_seconds += elapsed;
            direct_family_piece_builder_plan_last_seconds = elapsed;
            direct_family_piece_builder_plan_last_error = exc.what();
            throw;
        }
    }

    void install_direct_family_phased_piece_plan(
        const std::string& key,
        py::object first_family_names,
        py::object first_builders,
        py::object second_builder_factory,
        py::object composite_cls = py::none(),
        py::object packed_cls = py::none()
    ) {
        DirectFamilyPhasedPiecePlanRecord record;
        record.first_family_names = std::move(first_family_names);
        record.first_builders = std::move(first_builders);
        record.second_builder_factory = std::move(second_builder_factory);
        record.composite_cls = std::move(composite_cls);
        record.packed_cls = std::move(packed_cls);
        auto it = direct_family_phased_piece_plan_records.find(key);
        if (it == direct_family_phased_piece_plan_records.end()) {
            direct_family_phased_piece_plan_records.emplace(key, std::move(record));
        } else {
            it->second = std::move(record);
            ++direct_family_phased_piece_plan_replacements;
        }
        ++direct_family_phased_piece_plan_installs;
        direct_family_phased_piece_plan_last_error.clear();
    }

    py::object prepare_direct_family_payload_from_phased_piece_plan(
        const std::string& payload_key,
        const std::string& plan_key,
        bool force = false,
        bool install = true
    ) {
        ++direct_family_phased_piece_plan_prepare_calls;
        if (install && !payload_key.empty() && !force) {
            auto payload_it = direct_family_payload_records.find(payload_key);
            if (payload_it != direct_family_payload_records.end()) {
                ++direct_family_phased_piece_plan_cache_hits;
                ++direct_family_payload_hits;
                direct_family_phased_piece_plan_last_error.clear();
                return payload_it->second;
            }
        }
        auto plan_it = direct_family_phased_piece_plan_records.find(plan_key);
        if (plan_it == direct_family_phased_piece_plan_records.end()) {
            ++direct_family_phased_piece_plan_misses;
            ++direct_family_phased_piece_plan_failures;
            direct_family_phased_piece_plan_last_error =
                "MovingEnvironment phased direct-family piece plan is absent";
            throw std::runtime_error(direct_family_phased_piece_plan_last_error);
        }
        try {
            DirectFamilyPhasedPiecePlanRecord& record = plan_it->second;
            py::dict payload = build_direct_family_payload_from_phased_piece_builders(
                payload_key,
                record.first_family_names.cast<py::sequence>(),
                record.first_builders.cast<py::sequence>(),
                record.second_builder_factory,
                record.composite_cls,
                record.packed_cls,
                install && !payload_key.empty()
            );
            direct_family_phased_piece_plan_last_error.clear();
            return payload;
        } catch (const py::error_already_set& exc) {
            ++direct_family_phased_piece_plan_failures;
            direct_family_phased_piece_plan_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++direct_family_phased_piece_plan_failures;
            direct_family_phased_piece_plan_last_error = exc.what();
            throw;
        }
    }

    py::dict build_direct_family_payload_from_phased_family_plan(
        const std::string& key,
        py::sequence first_family_names,
        py::sequence first_builders,
        py::object family_plan_factory,
        py::object composite_cls = py::none(),
        py::object packed_cls = py::none(),
        bool install = true
    ) {
        ++direct_family_piece_builder_plan_calls;
        ++direct_family_phased_family_plan_dispatch_calls;
        const double start = wall_seconds();
        try {
            const ssize_t n_first =
                static_cast<ssize_t>(py::len(first_family_names));
            if (static_cast<ssize_t>(py::len(first_builders)) != n_first) {
                throw std::runtime_error(
                    "direct-family phased family plan first family/builder "
                    "length mismatch"
                );
            }
            py::list families;
            py::list pieces;
            long long built = 0;
            long long nonempty = 0;
            long long empty = 0;
            long long entries = 0;
            long long dispatch_families = 0;
            long long dispatch_nonempty = 0;
            long long dispatch_empty = 0;
            long long dispatch_entries = 0;
            auto run_piece = [&](py::object family, py::object piece) {
                families.append(family);
                pieces.append(piece);
                ++built;
                if (direct_family_payload_piece_empty(piece)) {
                    ++empty;
                    return;
                }
                const long long n_entries = direct_family_payload_entry_count(piece);
                ++nonempty;
                entries += n_entries;
            };
            auto run_builder = [&](py::object family, py::object builder) {
                if (builder.is_none() || !PyCallable_Check(builder.ptr())) {
                    throw std::runtime_error(
                        "direct-family phased family first builder must be callable"
                    );
                }
                run_piece(family, builder());
            };
            for (ssize_t idx = 0; idx < n_first; ++idx) {
                run_builder(
                    py::reinterpret_borrow<py::object>(first_family_names[idx]),
                    py::reinterpret_borrow<py::object>(first_builders[idx])
                );
            }
            if (
                !family_plan_factory.is_none() &&
                PyCallable_Check(family_plan_factory.ptr())
            ) {
                py::object plan = family_plan_factory();
                if (!plan.is_none()) {
                    py::object names_obj = py::none();
                    py::object dispatcher = py::none();
                    bool dispatcher_callable = false;
                    bool builder_sequence = false;
                    py::sequence family_names;
                    py::sequence family_builders;
                    if (
                        PyObject_HasAttrString(plan.ptr(), "family_names") == 1 &&
                        PyObject_HasAttrString(plan.ptr(), "build_piece") == 1
                    ) {
                        names_obj = plan.attr("family_names");
                        if (PyCallable_Check(names_obj.ptr())) {
                            names_obj = names_obj();
                        }
                        dispatcher = plan.attr("build_piece");
                        dispatcher_callable = PyCallable_Check(dispatcher.ptr());
                    } else {
                        if (static_cast<ssize_t>(py::len(plan)) < 2) {
                            throw std::runtime_error(
                                "direct-family phased family plan must return "
                                "(family_names, family_builder)"
                            );
                        }
                        py::sequence plan_seq = plan.cast<py::sequence>();
                        names_obj = py::reinterpret_borrow<py::object>(plan_seq[0]);
                        dispatcher =
                            py::reinterpret_borrow<py::object>(plan_seq[1]);
                        dispatcher_callable = PyCallable_Check(dispatcher.ptr());
                    }
                    family_names = names_obj.cast<py::sequence>();
                    const ssize_t n_families =
                        static_cast<ssize_t>(py::len(family_names));
                    if (!dispatcher_callable) {
                        family_builders = dispatcher.cast<py::sequence>();
                        if (
                            static_cast<ssize_t>(py::len(family_builders))
                            != n_families
                        ) {
                            throw std::runtime_error(
                                "direct-family phased family plan builder "
                                "sequence length mismatch"
                            );
                        }
                        builder_sequence = true;
                    }
                    for (ssize_t idx = 0; idx < n_families; ++idx) {
                        py::object family = py::reinterpret_borrow<py::object>(
                            family_names[idx]
                        );
                        py::object piece = py::none();
                        if (dispatcher_callable) {
                            piece = dispatcher(family);
                        } else if (builder_sequence) {
                            py::object builder = py::reinterpret_borrow<py::object>(
                                family_builders[idx]
                            );
                            if (
                                builder.is_none() ||
                                !PyCallable_Check(builder.ptr())
                            ) {
                                throw std::runtime_error(
                                    "direct-family phased family builder "
                                    "sequence item must be callable"
                                );
                            }
                            piece = builder();
                        }
                        const bool is_empty =
                            direct_family_payload_piece_empty(piece);
                        const long long n_entries =
                            is_empty ? 0 : direct_family_payload_entry_count(piece);
                        run_piece(family, piece);
                        ++dispatch_families;
                        if (is_empty) {
                            ++dispatch_empty;
                        } else {
                            ++dispatch_nonempty;
                            dispatch_entries += n_entries;
                        }
                    }
                }
            }
            py::dict payload = assemble_direct_family_payload(
                key,
                families,
                pieces,
                composite_cls,
                packed_cls,
                install
            );
            ++direct_family_piece_builder_plan_builds;
            direct_family_piece_builder_plan_families += built;
            direct_family_piece_builder_plan_pieces += nonempty;
            direct_family_piece_builder_plan_entries += entries;
            direct_family_piece_builder_plan_empty_pieces += empty;
            direct_family_phased_family_plan_dispatch_families +=
                dispatch_families;
            direct_family_phased_family_plan_dispatch_pieces +=
                dispatch_nonempty;
            direct_family_phased_family_plan_dispatch_entries +=
                dispatch_entries;
            direct_family_phased_family_plan_dispatch_empty_pieces +=
                dispatch_empty;
            const double elapsed = wall_seconds() - start;
            direct_family_piece_builder_plan_seconds += elapsed;
            direct_family_piece_builder_plan_last_seconds = elapsed;
            direct_family_piece_builder_plan_last_error.clear();
            direct_family_phased_family_plan_last_error.clear();
            return payload;
        } catch (const py::error_already_set& exc) {
            ++direct_family_piece_builder_plan_failures;
            ++direct_family_phased_family_plan_failures;
            const double elapsed = wall_seconds() - start;
            direct_family_piece_builder_plan_seconds += elapsed;
            direct_family_piece_builder_plan_last_seconds = elapsed;
            direct_family_piece_builder_plan_last_error = exc.what();
            direct_family_phased_family_plan_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++direct_family_piece_builder_plan_failures;
            ++direct_family_phased_family_plan_failures;
            const double elapsed = wall_seconds() - start;
            direct_family_piece_builder_plan_seconds += elapsed;
            direct_family_piece_builder_plan_last_seconds = elapsed;
            direct_family_piece_builder_plan_last_error = exc.what();
            direct_family_phased_family_plan_last_error = exc.what();
            throw;
        }
    }

    void install_direct_family_phased_family_plan(
        const std::string& key,
        py::object first_family_names,
        py::object first_builders,
        py::object family_plan_factory,
        py::object composite_cls = py::none(),
        py::object packed_cls = py::none()
    ) {
        DirectFamilyPhasedFamilyPlanRecord record;
        record.first_family_names = std::move(first_family_names);
        record.first_builders = std::move(first_builders);
        record.family_plan_factory = std::move(family_plan_factory);
        record.composite_cls = std::move(composite_cls);
        record.packed_cls = std::move(packed_cls);
        auto it = direct_family_phased_family_plan_records.find(key);
        if (it == direct_family_phased_family_plan_records.end()) {
            direct_family_phased_family_plan_records.emplace(
                key,
                std::move(record)
            );
        } else {
            it->second = std::move(record);
            ++direct_family_phased_family_plan_replacements;
        }
        ++direct_family_phased_family_plan_installs;
        direct_family_phased_family_plan_last_error.clear();
    }

    py::object prepare_direct_family_payload_from_phased_family_plan(
        const std::string& payload_key,
        const std::string& plan_key,
        bool force = false,
        bool install = true
    ) {
        ++direct_family_phased_family_plan_prepare_calls;
        if (install && !payload_key.empty() && !force) {
            auto payload_it = direct_family_payload_records.find(payload_key);
            if (payload_it != direct_family_payload_records.end()) {
                ++direct_family_phased_family_plan_cache_hits;
                ++direct_family_payload_hits;
                direct_family_phased_family_plan_last_error.clear();
                return payload_it->second;
            }
        }
        auto plan_it = direct_family_phased_family_plan_records.find(plan_key);
        if (plan_it == direct_family_phased_family_plan_records.end()) {
            ++direct_family_phased_family_plan_misses;
            ++direct_family_phased_family_plan_failures;
            direct_family_phased_family_plan_last_error =
                "MovingEnvironment phased direct-family family plan is absent";
            throw std::runtime_error(direct_family_phased_family_plan_last_error);
        }
        try {
            DirectFamilyPhasedFamilyPlanRecord& record = plan_it->second;
            py::dict payload = build_direct_family_payload_from_phased_family_plan(
                payload_key,
                record.first_family_names.cast<py::sequence>(),
                record.first_builders.cast<py::sequence>(),
                record.family_plan_factory,
                record.composite_cls,
                record.packed_cls,
                install && !payload_key.empty()
            );
            direct_family_phased_family_plan_last_error.clear();
            return payload;
        } catch (const py::error_already_set& exc) {
            ++direct_family_phased_family_plan_failures;
            direct_family_phased_family_plan_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++direct_family_phased_family_plan_failures;
            direct_family_phased_family_plan_last_error = exc.what();
            throw;
        }
    }

    py::dict build_direct_family_payload_from_two_phase_dispatch_plans(
        const std::string& key,
        py::object first_plan_factory,
        py::object second_plan_factory,
        py::object composite_cls = py::none(),
        py::object packed_cls = py::none(),
        bool install = true
    ) {
        ++direct_family_piece_builder_plan_calls;
        ++direct_family_two_phase_dispatch_plan_dispatch_calls;
        const double start = wall_seconds();
        try {
            py::list families;
            py::list pieces;
            long long built = 0;
            long long nonempty = 0;
            long long empty = 0;
            long long entries = 0;
            long long dispatch_families = 0;
            long long dispatch_nonempty = 0;
            long long dispatch_empty = 0;
            long long dispatch_entries = 0;
            long long literal_families = 0;
            long long literal_nonempty = 0;
            long long literal_empty = 0;
            long long literal_entries = 0;
            auto run_piece = [&](py::object family, py::object piece) {
                families.append(family);
                pieces.append(piece);
                ++built;
                if (direct_family_payload_piece_empty(piece)) {
                    ++empty;
                    return;
                }
                const long long n_entries = direct_family_payload_entry_count(piece);
                ++nonempty;
                entries += n_entries;
            };
            auto run_dispatch_plan = [&](py::object plan_source) {
                if (plan_source.is_none()) {
                    return;
                }
                py::object plan = plan_source;
                if (PyCallable_Check(plan_source.ptr())) {
                    ++direct_family_two_phase_dispatch_plan_factory_calls;
                    plan = plan_source();
                } else {
                    ++direct_family_two_phase_dispatch_plan_static_plan_uses;
                }
                if (plan.is_none()) {
                    return;
                }
                py::object names_obj = py::none();
                py::object dispatcher = py::none();
                bool dispatcher_callable = false;
                bool builder_sequence = false;
                bool literal_sequence = false;
                py::sequence family_names;
                py::sequence family_builders;
                py::sequence family_pieces;
                if (
                    PyObject_HasAttrString(plan.ptr(), "family_names") == 1
                ) {
                    names_obj = plan.attr("family_names");
                    if (PyCallable_Check(names_obj.ptr())) {
                        names_obj = names_obj();
                    }
                    if (PyObject_HasAttrString(plan.ptr(), "family_pieces") == 1) {
                        dispatcher = plan.attr("family_pieces");
                        if (PyCallable_Check(dispatcher.ptr())) {
                            dispatcher = dispatcher();
                        }
                        literal_sequence = true;
                    } else if (
                        PyObject_HasAttrString(plan.ptr(), "build_piece") == 1
                    ) {
                        dispatcher = plan.attr("build_piece");
                        dispatcher_callable = PyCallable_Check(dispatcher.ptr());
                    } else {
                        throw std::runtime_error(
                            "direct-family two-phase dispatch object must expose "
                            "family_pieces or build_piece"
                        );
                    }
                } else {
                    if (static_cast<ssize_t>(py::len(plan)) < 2) {
                        throw std::runtime_error(
                            "direct-family two-phase dispatch plan must return "
                            "(family_names, family_builder)"
                        );
                    }
                    py::sequence plan_seq = plan.cast<py::sequence>();
                    names_obj = py::reinterpret_borrow<py::object>(plan_seq[0]);
                    dispatcher = py::reinterpret_borrow<py::object>(plan_seq[1]);
                    dispatcher_callable = PyCallable_Check(dispatcher.ptr());
                }
                family_names = names_obj.cast<py::sequence>();
                const ssize_t n_families =
                    static_cast<ssize_t>(py::len(family_names));
                if (literal_sequence) {
                    family_pieces = dispatcher.cast<py::sequence>();
                    if (
                        static_cast<ssize_t>(py::len(family_pieces))
                        != n_families
                    ) {
                        throw std::runtime_error(
                            "direct-family two-phase literal piece sequence "
                            "length mismatch"
                        );
                    }
                } else if (!dispatcher_callable) {
                    family_builders = dispatcher.cast<py::sequence>();
                    if (
                        static_cast<ssize_t>(py::len(family_builders))
                        != n_families
                    ) {
                        throw std::runtime_error(
                            "direct-family two-phase dispatch builder sequence "
                            "length mismatch"
                        );
                    }
                    builder_sequence = true;
                }
                for (ssize_t idx = 0; idx < n_families; ++idx) {
                    py::object family = py::reinterpret_borrow<py::object>(
                        family_names[idx]
                    );
                    py::object piece = py::none();
                    if (literal_sequence) {
                        piece = py::reinterpret_borrow<py::object>(
                            family_pieces[idx]
                        );
                    } else if (dispatcher_callable) {
                        piece = dispatcher(family);
                    } else if (builder_sequence) {
                        py::object builder = py::reinterpret_borrow<py::object>(
                            family_builders[idx]
                        );
                        if (builder.is_none() || !PyCallable_Check(builder.ptr())) {
                            throw std::runtime_error(
                                "direct-family two-phase dispatch builder item "
                                "must be callable"
                            );
                        }
                        piece = builder();
                    }
                    const bool is_empty = direct_family_payload_piece_empty(piece);
                    const long long n_entries =
                        is_empty ? 0 : direct_family_payload_entry_count(piece);
                    run_piece(family, piece);
                    ++dispatch_families;
                    if (is_empty) {
                        ++dispatch_empty;
                    } else {
                        ++dispatch_nonempty;
                        dispatch_entries += n_entries;
                    }
                    if (literal_sequence) {
                        ++literal_families;
                        if (is_empty) {
                            ++literal_empty;
                        } else {
                            ++literal_nonempty;
                            literal_entries += n_entries;
                        }
                    }
                }
            };
            run_dispatch_plan(first_plan_factory);
            run_dispatch_plan(second_plan_factory);
            py::dict payload = assemble_direct_family_payload(
                key,
                families,
                pieces,
                composite_cls,
                packed_cls,
                install
            );
            ++direct_family_piece_builder_plan_builds;
            direct_family_piece_builder_plan_families += built;
            direct_family_piece_builder_plan_pieces += nonempty;
            direct_family_piece_builder_plan_entries += entries;
            direct_family_piece_builder_plan_empty_pieces += empty;
            direct_family_two_phase_dispatch_plan_dispatch_families +=
                dispatch_families;
            direct_family_two_phase_dispatch_plan_dispatch_pieces +=
                dispatch_nonempty;
            direct_family_two_phase_dispatch_plan_dispatch_entries +=
                dispatch_entries;
            direct_family_two_phase_dispatch_plan_dispatch_empty_pieces +=
                dispatch_empty;
            direct_family_two_phase_dispatch_plan_literal_families +=
                literal_families;
            direct_family_two_phase_dispatch_plan_literal_pieces +=
                literal_nonempty;
            direct_family_two_phase_dispatch_plan_literal_entries +=
                literal_entries;
            direct_family_two_phase_dispatch_plan_literal_empty_pieces +=
                literal_empty;
            const double elapsed = wall_seconds() - start;
            direct_family_piece_builder_plan_seconds += elapsed;
            direct_family_piece_builder_plan_last_seconds = elapsed;
            direct_family_piece_builder_plan_last_error.clear();
            direct_family_two_phase_dispatch_plan_last_error.clear();
            return payload;
        } catch (const py::error_already_set& exc) {
            ++direct_family_piece_builder_plan_failures;
            ++direct_family_two_phase_dispatch_plan_failures;
            const double elapsed = wall_seconds() - start;
            direct_family_piece_builder_plan_seconds += elapsed;
            direct_family_piece_builder_plan_last_seconds = elapsed;
            direct_family_piece_builder_plan_last_error = exc.what();
            direct_family_two_phase_dispatch_plan_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++direct_family_piece_builder_plan_failures;
            ++direct_family_two_phase_dispatch_plan_failures;
            const double elapsed = wall_seconds() - start;
            direct_family_piece_builder_plan_seconds += elapsed;
            direct_family_piece_builder_plan_last_seconds = elapsed;
            direct_family_piece_builder_plan_last_error = exc.what();
            direct_family_two_phase_dispatch_plan_last_error = exc.what();
            throw;
        }
    }

    static void load_int_revision_map(
        std::unordered_map<int, long long>& out,
        py::object obj
    ) {
        out.clear();
        if (obj.is_none()) {
            return;
        }
        if (py::isinstance<py::dict>(obj)) {
            py::dict d = obj.cast<py::dict>();
            for (auto item : d) {
                out[py::cast<int>(item.first)] = py::cast<long long>(item.second);
            }
            return;
        }
        py::sequence seq = obj.cast<py::sequence>();
        const ssize_t n = static_cast<ssize_t>(py::len(seq));
        for (ssize_t idx = 0; idx < n; ++idx) {
            py::tuple pair =
                tuple_from_sequence_object(
                    py::reinterpret_borrow<py::object>(seq[idx])
                ).cast<py::tuple>();
            if (py::len(pair) < 2) {
                continue;
            }
            out[py::cast<int>(pair[0])] = py::cast<long long>(pair[1]);
        }
    }

    void set_direct_family_revision_state(
        long long env_revision,
        py::sequence site_revisions,
        py::object left_boundary_revisions = py::none(),
        py::object right_boundary_revisions = py::none()
    ) {
        try {
            direct_family_revision_env = env_revision;
            direct_family_site_revisions.clear();
            const ssize_t n = static_cast<ssize_t>(py::len(site_revisions));
            direct_family_site_revisions.reserve(
                static_cast<size_t>(std::max<ssize_t>(0, n))
            );
            for (ssize_t idx = 0; idx < n; ++idx) {
                direct_family_site_revisions.push_back(
                    py::cast<long long>(site_revisions[idx])
                );
            }
            load_int_revision_map(
                direct_family_left_boundary_revisions,
                left_boundary_revisions
            );
            load_int_revision_map(
                direct_family_right_boundary_revisions,
                right_boundary_revisions
            );
            ++direct_family_revision_state_updates;
            direct_family_revision_state_last_error.clear();
        } catch (const py::error_already_set& exc) {
            ++direct_family_revision_state_failures;
            direct_family_revision_state_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++direct_family_revision_state_failures;
            direct_family_revision_state_last_error = exc.what();
            throw;
        }
    }

    py::tuple direct_family_revision_cache_key(int bond) {
        try {
            const int i = bond;
            const auto left_it = direct_family_left_boundary_revisions.find(i);
            const auto right_it =
                direct_family_right_boundary_revisions.find(i + 1);
            const long long left_rev =
                left_it == direct_family_left_boundary_revisions.end()
                ? 0
                : left_it->second;
            const long long right_rev =
                right_it == direct_family_right_boundary_revisions.end()
                ? 0
                : right_it->second;
            const ssize_t n_sites =
                static_cast<ssize_t>(direct_family_site_revisions.size());
            const ssize_t left_stop =
                std::max<ssize_t>(0, std::min<ssize_t>(n_sites, i));
            py::tuple left_sites(left_stop);
            for (ssize_t idx = 0; idx < left_stop; ++idx) {
                left_sites[idx] = py::int_(direct_family_site_revisions[idx]);
            }
            const ssize_t right_start =
                std::max<ssize_t>(
                    0,
                    std::min<ssize_t>(n_sites, static_cast<ssize_t>(i) + 2)
                );
            py::tuple right_sites(n_sites - right_start);
            for (ssize_t idx = right_start; idx < n_sites; ++idx) {
                right_sites[idx - right_start] =
                    py::int_(direct_family_site_revisions[idx]);
            }
            ++direct_family_revision_cache_key_builds;
            return py::make_tuple(
                "direct_family_environment",
                py::int_(i),
                py::int_(direct_family_revision_env),
                py::make_tuple("left", py::int_(i), py::int_(left_rev)),
                py::make_tuple("right", py::int_(i + 1), py::int_(right_rev)),
                py::make_tuple("left_sites", left_sites),
                py::make_tuple("right_sites", right_sites)
            );
        } catch (const py::error_already_set& exc) {
            ++direct_family_revision_cache_key_failures;
            direct_family_revision_state_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++direct_family_revision_cache_key_failures;
            direct_family_revision_state_last_error = exc.what();
            throw;
        }
    }

    static std::string direct_family_cpp_key_string(
        const std::string& prefix,
        int bond,
        py::object cache_key
    ) {
        return prefix + ":" + std::to_string(bond) + ":" +
            py::repr(cache_key).cast<std::string>();
    }

    py::dict direct_family_cpp_key_bundle(int bond, py::object cache_key) {
        py::dict out;
        try {
            if (cache_key.is_none()) {
                out["payload_key"] = py::str("");
                out["builder_key"] = py::str("");
                out["plan_key"] = py::str("");
                out["cache_key"] = py::none();
                return out;
            }
            out["payload_key"] = py::str(
                direct_family_cpp_key_string(
                    "direct-family-payload",
                    bond,
                    cache_key
                )
            );
            out["builder_key"] = py::str(
                direct_family_cpp_key_string(
                    "direct-family-builder",
                    bond,
                    cache_key
                )
            );
            out["plan_key"] = py::str(
                direct_family_cpp_key_string(
                    "direct-family-plan",
                    bond,
                    cache_key
                )
            );
            out["cache_key"] = cache_key;
            ++direct_family_cpp_key_bundle_builds;
            return out;
        } catch (const py::error_already_set& exc) {
            ++direct_family_cpp_key_bundle_failures;
            direct_family_revision_state_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++direct_family_cpp_key_bundle_failures;
            direct_family_revision_state_last_error = exc.what();
            throw;
        }
    }

    void install_direct_family_two_phase_dispatch_plan(
        const std::string& key,
        py::object first_plan_factory,
        py::object second_plan_factory,
        py::object composite_cls = py::none(),
        py::object packed_cls = py::none()
    ) {
        DirectFamilyTwoPhaseDispatchPlanRecord record;
        record.first_plan_source = std::move(first_plan_factory);
        record.second_plan_source = std::move(second_plan_factory);
        record.composite_cls = std::move(composite_cls);
        record.packed_cls = std::move(packed_cls);
        record.static_plan_sources = false;
        auto it = direct_family_two_phase_dispatch_plan_records.find(key);
        if (it == direct_family_two_phase_dispatch_plan_records.end()) {
            direct_family_two_phase_dispatch_plan_records.emplace(
                key,
                std::move(record)
            );
        } else {
            it->second = std::move(record);
            ++direct_family_two_phase_dispatch_plan_replacements;
        }
        ++direct_family_two_phase_dispatch_plan_installs;
        direct_family_two_phase_dispatch_plan_last_error.clear();
    }

    void install_direct_family_two_phase_dispatch_static_plan(
        const std::string& key,
        py::object first_plan,
        py::object second_plan,
        py::object composite_cls = py::none(),
        py::object packed_cls = py::none()
    ) {
        DirectFamilyTwoPhaseDispatchPlanRecord record;
        record.first_plan_source = std::move(first_plan);
        record.second_plan_source = std::move(second_plan);
        record.composite_cls = std::move(composite_cls);
        record.packed_cls = std::move(packed_cls);
        record.static_plan_sources = true;
        auto it = direct_family_two_phase_dispatch_plan_records.find(key);
        if (it == direct_family_two_phase_dispatch_plan_records.end()) {
            direct_family_two_phase_dispatch_plan_records.emplace(
                key,
                std::move(record)
            );
        } else {
            it->second = std::move(record);
            ++direct_family_two_phase_dispatch_plan_replacements;
        }
        ++direct_family_two_phase_dispatch_plan_installs;
        ++direct_family_two_phase_dispatch_plan_static_plan_installs;
        direct_family_two_phase_dispatch_plan_last_error.clear();
    }

    py::object prepare_direct_family_payload_from_two_phase_dispatch_plan(
        const std::string& payload_key,
        const std::string& plan_key,
        bool force = false,
        bool install = true
    ) {
        ++direct_family_two_phase_dispatch_plan_prepare_calls;
        if (install && !payload_key.empty() && !force) {
            auto payload_it = direct_family_payload_records.find(payload_key);
            if (payload_it != direct_family_payload_records.end()) {
                ++direct_family_two_phase_dispatch_plan_cache_hits;
                ++direct_family_payload_hits;
                direct_family_two_phase_dispatch_plan_last_error.clear();
                return payload_it->second;
            }
        }
        auto plan_it = direct_family_two_phase_dispatch_plan_records.find(plan_key);
        if (plan_it == direct_family_two_phase_dispatch_plan_records.end()) {
            ++direct_family_two_phase_dispatch_plan_misses;
            ++direct_family_two_phase_dispatch_plan_failures;
            direct_family_two_phase_dispatch_plan_last_error =
                "MovingEnvironment direct-family two-phase dispatch plan is absent";
            throw std::runtime_error(
                direct_family_two_phase_dispatch_plan_last_error
            );
        }
        try {
            DirectFamilyTwoPhaseDispatchPlanRecord& record = plan_it->second;
            py::dict payload = build_direct_family_payload_from_two_phase_dispatch_plans(
                payload_key,
                record.first_plan_source,
                record.second_plan_source,
                record.composite_cls,
                record.packed_cls,
                install && !payload_key.empty()
            );
            direct_family_two_phase_dispatch_plan_last_error.clear();
            return payload;
        } catch (const py::error_already_set& exc) {
            ++direct_family_two_phase_dispatch_plan_failures;
            direct_family_two_phase_dispatch_plan_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++direct_family_two_phase_dispatch_plan_failures;
            direct_family_two_phase_dispatch_plan_last_error = exc.what();
            throw;
        }
    }

    py::dict prepare_same_side_route_identity_info(
        py::object table,
        long long max_terms
    ) {
        ++same_side_route_identity_info_calls;
        const double start = wall_seconds();
        auto unsupported = [&](const std::string& reason) {
            const double elapsed = wall_seconds() - start;
            ++same_side_route_identity_info_unsupported;
            same_side_route_identity_info_seconds += elapsed;
            same_side_route_identity_info_last_seconds = elapsed;
            same_side_route_identity_info_last_reason = reason;
            same_side_route_identity_info_last_error.clear();
            py::dict out;
            out["supported"] = py::bool_(false);
            out["reason"] = py::str(reason);
            out["seconds"] = py::float_(elapsed);
            return out;
        };
        try {
            if (max_terms <= 0) {
                return unsupported("disabled");
            }
            py::object route_plan = py::getattr(
                table,
                "_pyqed_same_side_route_columns",
                py::none()
            );
            if (route_plan.is_none()) {
                return unsupported("missing_route_plan");
            }
            py::object boundary_results_obj = py::getattr(
                table,
                "_pyqed_same_side_route_boundary_results",
                py::tuple()
            );
            if (boundary_results_obj.is_none()) {
                boundary_results_obj = py::tuple();
            }
            py::object boundary_results =
                tuple_from_sequence_object(boundary_results_obj);
            py::object boundary_table_ids_obj = py::getattr(
                table,
                "_pyqed_same_side_route_boundary_table_ids",
                py::tuple()
            );
            py::array_t<long long, py::array::c_style | py::array::forcecast>
                boundary_table_ids = boundary_table_ids_obj.cast<
                    py::array_t<long long, py::array::c_style | py::array::forcecast>
                >();
            if (
                boundary_table_ids.ndim() != 1 ||
                static_cast<ssize_t>(boundary_table_ids.shape(0)) <= 0
            ) {
                return unsupported("missing_boundary_table_ids");
            }
            py::object boundary_value_table = py::getattr(
                table,
                "_pyqed_same_side_route_boundary_value_table",
                py::none()
            );
            if (boundary_value_table.is_none()) {
                return unsupported("missing_boundary_value_table");
            }
            py::object boundary_payloads_obj = py::getattr(
                boundary_value_table,
                "payloads",
                py::tuple()
            );
            if (boundary_payloads_obj.is_none()) {
                boundary_payloads_obj = py::tuple();
            }
            py::object boundary_payloads =
                tuple_from_sequence_object(boundary_payloads_obj);
            if (static_cast<ssize_t>(py::len(boundary_payloads)) <= 0) {
                return unsupported("missing_boundary_payloads");
            }
            py::object complete_obj = py::getattr(
                table,
                "_pyqed_same_side_route_boundary_table_complete",
                py::bool_(false)
            );
            if (!py::cast<bool>(complete_obj)) {
                return unsupported("incomplete_boundary_table");
            }

            long long records = 0;
            if (py::hasattr(route_plan, "records")) {
                records = py::cast<long long>(route_plan.attr("records"));
            }
            long long terms = 0;
            if (py::hasattr(route_plan, "terms")) {
                terms = py::cast<long long>(route_plan.attr("terms"));
            } else if (py::hasattr(route_plan, "offsets")) {
                py::array_t<long long, py::array::c_style | py::array::forcecast>
                    offsets = route_plan.attr("offsets").cast<
                        py::array_t<long long, py::array::c_style | py::array::forcecast>
                    >();
                if (offsets.ndim() == 1 && offsets.shape(0) > 0) {
                    auto offset_view = offsets.unchecked<1>();
                    terms = static_cast<long long>(
                        offset_view(static_cast<ssize_t>(offsets.shape(0)) - 1)
                    );
                }
            }
            if (terms <= 0) {
                terms = static_cast<long long>(boundary_table_ids.shape(0));
            }
            if (terms > max_terms) {
                return unsupported("too_many_terms");
            }

            py::object row_map_obj = py::getattr(
                table,
                "_pyqed_same_side_route_row_map",
                py::none()
            );
            long long row_count = 0;
            if (row_map_obj.is_none()) {
                py::dict row_map;
                py::object raw_tuples_obj = py::getattr(
                    route_plan,
                    "raw_key_tuples",
                    py::tuple()
                );
                if (raw_tuples_obj.is_none()) {
                    raw_tuples_obj = py::tuple();
                }
                py::object raw_tuples_tuple =
                    tuple_from_sequence_object(raw_tuples_obj);
                py::sequence raw_tuples = raw_tuples_tuple.cast<py::sequence>();
                const ssize_t tuple_rows =
                    static_cast<ssize_t>(py::len(raw_tuples));
                if (tuple_rows > 0) {
                    for (ssize_t row = 0; row < tuple_rows; ++row) {
                        py::object key = tuple_from_sequence_object(
                            py::reinterpret_borrow<py::object>(raw_tuples[row])
                        );
                        row_map[key] = py::int_(row);
                    }
                    row_count = static_cast<long long>(tuple_rows);
                } else {
                    py::array_t<long long, py::array::c_style | py::array::forcecast>
                        raw_rows = route_plan.attr("raw_keys").cast<
                            py::array_t<long long, py::array::c_style | py::array::forcecast>
                        >();
                    if (raw_rows.ndim() != 2) {
                        return unsupported("invalid_raw_keys");
                    }
                    ssize_t usable_rows =
                        static_cast<ssize_t>(raw_rows.shape(0));
                    if (py::hasattr(route_plan, "offsets")) {
                        py::array_t<long long, py::array::c_style | py::array::forcecast>
                            offsets = route_plan.attr("offsets").cast<
                                py::array_t<long long, py::array::c_style | py::array::forcecast>
                            >();
                        if (offsets.ndim() == 1) {
                            usable_rows = std::min<ssize_t>(
                                usable_rows,
                                std::max<ssize_t>(
                                    0,
                                    static_cast<ssize_t>(offsets.shape(0)) - 1
                                )
                            );
                        }
                    }
                    auto raw_view = raw_rows.unchecked<2>();
                    const ssize_t n_cols =
                        static_cast<ssize_t>(raw_rows.shape(1));
                    for (ssize_t row = 0; row < usable_rows; ++row) {
                        py::list key_items;
                        for (ssize_t col = 0; col < n_cols; ++col) {
                            key_items.append(py::int_(raw_view(row, col)));
                        }
                        row_map[tuple_from_sequence_object(key_items)] =
                            py::int_(row);
                    }
                    row_count = static_cast<long long>(usable_rows);
                }
                table.attr("_pyqed_same_side_route_row_map") = row_map;
                row_map_obj = row_map;
                ++same_side_route_identity_info_row_map_builds;
            } else {
                ++same_side_route_identity_info_row_map_hits;
                row_count = static_cast<long long>(py::len(row_map_obj));
            }

            const double elapsed = wall_seconds() - start;
            ++same_side_route_identity_info_successes;
            same_side_route_identity_info_records += records;
            same_side_route_identity_info_terms += terms;
            same_side_route_identity_info_rows += row_count;
            same_side_route_identity_info_seconds += elapsed;
            same_side_route_identity_info_last_seconds = elapsed;
            same_side_route_identity_info_last_reason.clear();
            same_side_route_identity_info_last_error.clear();

            py::dict out;
            out["supported"] = py::bool_(true);
            out["table"] = table;
            out["route_plan"] = route_plan;
            out["boundary_results"] = boundary_results;
            out["boundary_table_ids"] = boundary_table_ids;
            out["boundary_value_table"] = boundary_value_table;
            out["boundary_payloads"] = boundary_payloads;
            out["row_map"] = row_map_obj;
            out["records"] = py::int_(records);
            out["terms"] = py::int_(terms);
            out["rows"] = py::int_(row_count);
            out["seconds"] = py::float_(elapsed);
            return out;
        } catch (const py::error_already_set& exc) {
            ++same_side_route_identity_info_failures;
            const double elapsed = wall_seconds() - start;
            same_side_route_identity_info_seconds += elapsed;
            same_side_route_identity_info_last_seconds = elapsed;
            same_side_route_identity_info_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++same_side_route_identity_info_failures;
            const double elapsed = wall_seconds() - start;
            same_side_route_identity_info_seconds += elapsed;
            same_side_route_identity_info_last_seconds = elapsed;
            same_side_route_identity_info_last_error = exc.what();
            throw;
        }
    }

    py::dict prepare_same_side_route_boundary_batch(
        py::object table,
        py::object route_plan,
        py::object value_table
    ) {
        ++same_side_route_boundary_batch_calls;
        const double start = wall_seconds();
        try {
            py::object boundary_keys_obj = py::getattr(
                route_plan,
                "boundary_keys",
                py::tuple()
            );
            if (boundary_keys_obj.is_none()) {
                boundary_keys_obj = py::tuple();
            }
            py::object boundary_keys_tuple =
                tuple_from_sequence_object(boundary_keys_obj);
            py::sequence boundary_keys =
                boundary_keys_tuple.cast<py::sequence>();
            const ssize_t n_keys = static_cast<ssize_t>(py::len(boundary_keys));
            py::array_t<long long> table_ids(n_keys);
            auto table_id_view = table_ids.mutable_unchecked<1>();

            py::list missing_keys;
            py::list missing_positions;
            long long hits = 0;
            long long misses = 0;
            py::object payloads = py::tuple();
            if (!value_table.is_none() && n_keys > 0) {
                py::dict entries = value_table.attr("entries").cast<py::dict>();
                py::dict ids = value_table.attr("ids").cast<py::dict>();
                payloads = py::getattr(value_table, "payloads", py::tuple());
                for (ssize_t idx = 0; idx < n_keys; ++idx) {
                    py::object key = py::reinterpret_borrow<py::object>(
                        boundary_keys[idx]
                    );
                    if (!entries.contains(key) || !ids.contains(key)) {
                        table_id_view(idx) = -1;
                        missing_keys.append(key);
                        missing_positions.append(py::int_(idx));
                        ++misses;
                        continue;
                    }
                    table_id_view(idx) = py::cast<long long>(ids[key]);
                    ++hits;
                }

                auto get_counter = [&](const char* name) -> long long {
                    py::object obj = py::getattr(
                        value_table,
                        name,
                        py::int_(0)
                    );
                    if (obj.is_none()) {
                        return 0;
                    }
                    return py::cast<long long>(obj);
                };
                value_table.attr("batch_resolves") = py::int_(
                    get_counter("batch_resolves") + 1
                );
                value_table.attr("hits") = py::int_(
                    get_counter("hits") + hits
                );
                value_table.attr("misses") = py::int_(
                    get_counter("misses") + misses
                );
                value_table.attr("last_batch_size") = py::int_(n_keys);
                value_table.attr("last_batch_hits") = py::int_(hits);
                value_table.attr("last_batch_misses") = py::int_(misses);
                value_table.attr("cpp_resolves") = py::int_(
                    get_counter("cpp_resolves") + 1
                );
            } else {
                for (ssize_t idx = 0; idx < n_keys; ++idx) {
                    table_id_view(idx) = -1;
                    py::object key = py::reinterpret_borrow<py::object>(
                        boundary_keys[idx]
                    );
                    missing_keys.append(key);
                    missing_positions.append(py::int_(idx));
                    ++misses;
                }
            }

            const bool complete = (n_keys > 0 && hits == n_keys);
            table.attr("_pyqed_same_side_route_boundary_table_ids") = table_ids;
            table.attr("_pyqed_same_side_route_boundary_value_table") =
                value_table;
            table.attr("_pyqed_same_side_route_boundary_payloads") = payloads;
            table.attr("_pyqed_same_side_route_boundary_table_complete") =
                py::bool_(complete);

            const double elapsed = wall_seconds() - start;
            ++same_side_route_boundary_batch_successes;
            same_side_route_boundary_batch_keys +=
                static_cast<long long>(n_keys);
            same_side_route_boundary_batch_hits += hits;
            same_side_route_boundary_batch_misses += misses;
            if (complete) {
                ++same_side_route_boundary_batch_complete;
            }
            same_side_route_boundary_batch_seconds += elapsed;
            same_side_route_boundary_batch_last_seconds = elapsed;
            same_side_route_boundary_batch_last_error.clear();

            py::dict out;
            out["table_ids"] = table_ids;
            out["missing_keys"] = tuple_from_sequence_object(missing_keys);
            out["missing_positions"] = tuple_from_sequence_object(missing_positions);
            out["hits"] = py::int_(hits);
            out["misses"] = py::int_(misses);
            out["keys"] = py::int_(n_keys);
            out["complete"] = py::bool_(complete);
            out["seconds"] = py::float_(elapsed);
            return out;
        } catch (const py::error_already_set& exc) {
            ++same_side_route_boundary_batch_failures;
            const double elapsed = wall_seconds() - start;
            same_side_route_boundary_batch_seconds += elapsed;
            same_side_route_boundary_batch_last_seconds = elapsed;
            same_side_route_boundary_batch_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++same_side_route_boundary_batch_failures;
            const double elapsed = wall_seconds() - start;
            same_side_route_boundary_batch_seconds += elapsed;
            same_side_route_boundary_batch_last_seconds = elapsed;
            same_side_route_boundary_batch_last_error = exc.what();
            throw;
        }
    }

    py::dict prepare_same_side_route_boundary_parent_rows(
        const std::string& side,
        py::object route_plan,
        py::object missing_keys_obj,
        py::object missing_positions_obj
    ) {
        ++same_side_route_boundary_parent_plan_calls;
        const double start = wall_seconds();
        try {
            py::object missing_keys_tuple =
                tuple_from_sequence_object(missing_keys_obj);
            py::object missing_positions_tuple =
                tuple_from_sequence_object(missing_positions_obj);
            py::sequence missing_keys =
                missing_keys_tuple.cast<py::sequence>();
            py::sequence missing_positions =
                missing_positions_tuple.cast<py::sequence>();
            const ssize_t n_missing =
                static_cast<ssize_t>(py::len(missing_keys));
            if (static_cast<ssize_t>(py::len(missing_positions)) != n_missing) {
                throw std::runtime_error(
                    "same-side boundary parent row keys/positions differ"
                );
            }

            py::list unique_parent_keys;
            py::list parent_rows;
            bool used_route_layout = false;
            bool route_layout_valid = false;
            py::array_t<long long, py::array::c_style | py::array::forcecast>
                parent_ids;
            py::object parent_keys_tuple = py::tuple();
            py::object local_pieces_tuple = py::tuple();
            if (py::hasattr(route_plan, "boundary_parent_ids")) {
                parent_ids = route_plan.attr("boundary_parent_ids").cast<
                    py::array_t<long long, py::array::c_style | py::array::forcecast>
                >();
                parent_keys_tuple = tuple_from_sequence_object(
                    py::getattr(route_plan, "boundary_parent_keys", py::tuple())
                );
                local_pieces_tuple = tuple_from_sequence_object(
                    py::getattr(route_plan, "boundary_local_pieces", py::tuple())
                );
                route_layout_valid = (
                    parent_ids.ndim() == 1 &&
                    static_cast<ssize_t>(py::len(parent_keys_tuple)) > 0 &&
                    static_cast<ssize_t>(py::len(local_pieces_tuple)) >=
                        static_cast<ssize_t>(parent_ids.shape(0))
                );
            }

            auto append_unique_parent = [&](
                py::dict& parent_pos,
                py::object parent_key
            ) -> long long {
                if (parent_pos.contains(parent_key)) {
                    return py::cast<long long>(parent_pos[parent_key]);
                }
                const long long parent_idx =
                    static_cast<long long>(py::len(unique_parent_keys));
                parent_pos[parent_key] = py::int_(parent_idx);
                unique_parent_keys.append(parent_key);
                return parent_idx;
            };

            if (route_layout_valid) {
                try {
                    py::dict parent_pos;
                    auto parent_id_view = parent_ids.unchecked<1>();
                    py::sequence parent_keys =
                        parent_keys_tuple.cast<py::sequence>();
                    py::sequence local_pieces =
                        local_pieces_tuple.cast<py::sequence>();
                    for (ssize_t idx = 0; idx < n_missing; ++idx) {
                        py::object key =
                            py::reinterpret_borrow<py::object>(missing_keys[idx]);
                        const long long pos = py::cast<long long>(
                            py::reinterpret_borrow<py::object>(
                                missing_positions[idx]
                            )
                        );
                        if (
                            pos < 0 ||
                            pos >= static_cast<long long>(parent_ids.shape(0))
                        ) {
                            throw std::runtime_error("parent id position out of range");
                        }
                        const long long parent_id =
                            static_cast<long long>(parent_id_view(pos));
                        if (
                            parent_id < 0 ||
                            parent_id >= static_cast<long long>(
                                py::len(parent_keys_tuple)
                            )
                        ) {
                            throw std::runtime_error("parent id out of range");
                        }
                        py::object parent_key =
                            py::reinterpret_borrow<py::object>(
                                parent_keys[parent_id]
                            );
                        py::object local_piece =
                            py::str(py::reinterpret_borrow<py::object>(
                                local_pieces[pos]
                            ));
                        const long long parent_idx =
                            append_unique_parent(parent_pos, parent_key);
                        parent_rows.append(py::make_tuple(
                            key,
                            py::int_(pos),
                            py::int_(parent_idx),
                            parent_key,
                            local_piece
                        ));
                    }
                    used_route_layout = true;
                } catch (const py::error_already_set&) {
                    PyErr_Clear();
                    unique_parent_keys = py::list();
                    parent_rows = py::list();
                    used_route_layout = false;
                } catch (const std::exception&) {
                    unique_parent_keys = py::list();
                    parent_rows = py::list();
                    used_route_layout = false;
                }
            }

            if (!used_route_layout) {
                py::dict parent_pos;
                for (ssize_t idx = 0; idx < n_missing; ++idx) {
                    py::object key =
                        py::reinterpret_borrow<py::object>(missing_keys[idx]);
                    py::sequence key_seq = key.cast<py::sequence>();
                    if (static_cast<ssize_t>(py::len(key_seq)) < 2) {
                        throw std::runtime_error(
                            "same-side boundary key must contain pattern and piece"
                        );
                    }
                    py::object pattern_obj =
                        tuple_from_sequence_object(
                            py::reinterpret_borrow<py::object>(key_seq[0])
                        );
                    py::object piece =
                        py::str(py::reinterpret_borrow<py::object>(key_seq[1]));
                    py::sequence pattern = pattern_obj.cast<py::sequence>();
                    const ssize_t n_pattern =
                        static_cast<ssize_t>(py::len(pattern));
                    py::list parent_items;
                    py::object local_piece;
                    if (side == "left") {
                        for (ssize_t col = 0; col < std::max<ssize_t>(0, n_pattern - 1); ++col) {
                            parent_items.append(
                                py::reinterpret_borrow<py::object>(pattern[col])
                            );
                        }
                        if (n_pattern > 0) {
                            local_piece = py::str(
                                py::reinterpret_borrow<py::object>(
                                    pattern[n_pattern - 1]
                                )
                            );
                        } else {
                            local_piece = piece;
                        }
                    } else {
                        for (ssize_t col = 1; col < n_pattern; ++col) {
                            parent_items.append(
                                py::reinterpret_borrow<py::object>(pattern[col])
                            );
                        }
                        if (n_pattern > 0) {
                            local_piece = py::str(
                                py::reinterpret_borrow<py::object>(pattern[0])
                            );
                        } else {
                            local_piece = piece;
                        }
                    }
                    py::object parent_pattern =
                        tuple_from_sequence_object(parent_items);
                    py::object parent_key = py::make_tuple(parent_pattern, piece);
                    const long long parent_idx =
                        append_unique_parent(parent_pos, parent_key);
                    const long long pos = py::cast<long long>(
                        py::reinterpret_borrow<py::object>(
                            missing_positions[idx]
                        )
                    );
                    parent_rows.append(py::make_tuple(
                        key,
                        py::int_(pos),
                        py::int_(parent_idx),
                        parent_key,
                        local_piece
                    ));
                }
            }

            const double elapsed = wall_seconds() - start;
            ++same_side_route_boundary_parent_plan_successes;
            same_side_route_boundary_parent_plan_rows +=
                static_cast<long long>(py::len(parent_rows));
            same_side_route_boundary_parent_plan_unique +=
                static_cast<long long>(py::len(unique_parent_keys));
            if (used_route_layout) {
                ++same_side_route_boundary_parent_plan_route_layout;
            } else {
                ++same_side_route_boundary_parent_plan_fallback;
            }
            same_side_route_boundary_parent_plan_seconds += elapsed;
            same_side_route_boundary_parent_plan_last_seconds = elapsed;
            same_side_route_boundary_parent_plan_last_error.clear();

            py::dict out;
            out["unique_parent_keys"] =
                tuple_from_sequence_object(unique_parent_keys);
            out["parent_rows"] = tuple_from_sequence_object(parent_rows);
            out["used_route_layout"] = py::bool_(used_route_layout);
            out["rows"] = py::int_(py::len(parent_rows));
            out["unique"] = py::int_(py::len(unique_parent_keys));
            out["seconds"] = py::float_(elapsed);
            return out;
        } catch (const py::error_already_set& exc) {
            ++same_side_route_boundary_parent_plan_failures;
            const double elapsed = wall_seconds() - start;
            same_side_route_boundary_parent_plan_seconds += elapsed;
            same_side_route_boundary_parent_plan_last_seconds = elapsed;
            same_side_route_boundary_parent_plan_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++same_side_route_boundary_parent_plan_failures;
            const double elapsed = wall_seconds() - start;
            same_side_route_boundary_parent_plan_seconds += elapsed;
            same_side_route_boundary_parent_plan_last_seconds = elapsed;
            same_side_route_boundary_parent_plan_last_error = exc.what();
            throw;
        }
    }

    py::dict prepare_same_side_route_boundary_parent_values(
        py::object prev_value_table,
        py::object unique_parent_keys_obj,
        py::object parent_rows_obj
    ) {
        ++same_side_route_boundary_parent_value_calls;
        const double start = wall_seconds();
        try {
            py::object unique_parent_keys_tuple =
                tuple_from_sequence_object(unique_parent_keys_obj);
            py::object parent_rows_tuple =
                tuple_from_sequence_object(parent_rows_obj);
            py::sequence unique_parent_keys =
                unique_parent_keys_tuple.cast<py::sequence>();
            py::sequence parent_rows = parent_rows_tuple.cast<py::sequence>();
            const ssize_t n_keys =
                static_cast<ssize_t>(py::len(unique_parent_keys));
            const ssize_t n_rows =
                static_cast<ssize_t>(py::len(parent_rows));

            py::dict entries = prev_value_table.attr("entries").cast<py::dict>();
            py::list parent_values;
            py::list missing_parent_keys;
            py::list missing_parent_positions;
            long long hits = 0;
            long long misses = 0;
            for (ssize_t idx = 0; idx < n_keys; ++idx) {
                py::object key = py::reinterpret_borrow<py::object>(
                    unique_parent_keys[idx]
                );
                if (!entries.contains(key)) {
                    parent_values.append(py::none());
                    missing_parent_keys.append(key);
                    missing_parent_positions.append(py::int_(idx));
                    ++misses;
                    continue;
                }
                py::object value =
                    py::reinterpret_borrow<py::object>(entries[key]);
                if (value.is_none()) {
                    parent_values.append(py::none());
                    missing_parent_keys.append(key);
                    missing_parent_positions.append(py::int_(idx));
                    ++misses;
                    continue;
                }
                parent_values.append(value);
                ++hits;
            }

            py::list available_rows;
            py::list missing_rows;
            for (ssize_t idx = 0; idx < n_rows; ++idx) {
                py::sequence row = py::reinterpret_borrow<py::sequence>(
                    parent_rows[idx]
                );
                if (static_cast<ssize_t>(py::len(row)) < 5) {
                    throw std::runtime_error(
                        "same-side parent row must contain key, pos, parent index, parent key, local piece"
                    );
                }
                py::object key = py::reinterpret_borrow<py::object>(row[0]);
                py::object pos = py::reinterpret_borrow<py::object>(row[1]);
                const long long parent_idx = py::cast<long long>(
                    py::reinterpret_borrow<py::object>(row[2])
                );
                py::object parent_key =
                    py::reinterpret_borrow<py::object>(row[3]);
                py::object local_piece =
                    py::reinterpret_borrow<py::object>(row[4]);
                py::object parent_value = py::none();
                if (
                    parent_idx >= 0 &&
                    parent_idx < static_cast<long long>(py::len(parent_values))
                ) {
                    parent_value = py::reinterpret_borrow<py::object>(
                        parent_values[parent_idx]
                    );
                }
                if (parent_value.is_none()) {
                    missing_rows.append(py::make_tuple(
                        key,
                        pos,
                        parent_key,
                        local_piece
                    ));
                    continue;
                }
                available_rows.append(py::make_tuple(
                    key,
                    pos,
                    parent_key,
                    local_piece,
                    parent_value
                ));
            }

            auto get_counter = [&](const char* name) -> long long {
                py::object obj = py::getattr(
                    prev_value_table,
                    name,
                    py::int_(0)
                );
                if (obj.is_none()) {
                    return 0;
                }
                return py::cast<long long>(obj);
            };
            prev_value_table.attr("batch_resolves") = py::int_(
                get_counter("batch_resolves") + 1
            );
            prev_value_table.attr("hits") = py::int_(
                get_counter("hits") + hits
            );
            prev_value_table.attr("misses") = py::int_(
                get_counter("misses") + misses
            );
            prev_value_table.attr("last_batch_size") = py::int_(n_keys);
            prev_value_table.attr("last_batch_hits") = py::int_(hits);
            prev_value_table.attr("last_batch_misses") = py::int_(misses);
            prev_value_table.attr("cpp_resolves") = py::int_(
                get_counter("cpp_resolves") + 1
            );

            const double elapsed = wall_seconds() - start;
            ++same_side_route_boundary_parent_value_successes;
            same_side_route_boundary_parent_value_rows +=
                static_cast<long long>(n_rows);
            same_side_route_boundary_parent_value_available +=
                static_cast<long long>(py::len(available_rows));
            same_side_route_boundary_parent_value_missing +=
                static_cast<long long>(py::len(missing_rows));
            same_side_route_boundary_parent_value_hits += hits;
            same_side_route_boundary_parent_value_misses += misses;
            same_side_route_boundary_parent_value_seconds += elapsed;
            same_side_route_boundary_parent_value_last_seconds = elapsed;
            same_side_route_boundary_parent_value_last_error.clear();

            py::dict out;
            out["parent_values"] = tuple_from_sequence_object(parent_values);
            out["available_rows"] = tuple_from_sequence_object(available_rows);
            out["missing_rows"] = tuple_from_sequence_object(missing_rows);
            out["missing_parent_keys"] =
                tuple_from_sequence_object(missing_parent_keys);
            out["missing_parent_positions"] =
                tuple_from_sequence_object(missing_parent_positions);
            out["hits"] = py::int_(hits);
            out["misses"] = py::int_(misses);
            out["rows"] = py::int_(n_rows);
            out["available"] = py::int_(py::len(available_rows));
            out["missing"] = py::int_(py::len(missing_rows));
            out["seconds"] = py::float_(elapsed);
            return out;
        } catch (const py::error_already_set& exc) {
            ++same_side_route_boundary_parent_value_failures;
            const double elapsed = wall_seconds() - start;
            same_side_route_boundary_parent_value_seconds += elapsed;
            same_side_route_boundary_parent_value_last_seconds = elapsed;
            same_side_route_boundary_parent_value_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++same_side_route_boundary_parent_value_failures;
            const double elapsed = wall_seconds() - start;
            same_side_route_boundary_parent_value_seconds += elapsed;
            same_side_route_boundary_parent_value_last_seconds = elapsed;
            same_side_route_boundary_parent_value_last_error = exc.what();
            throw;
        }
    }

    py::dict apply_same_side_route_boundary_parent_advances(
        py::object available_rows_obj,
        py::object advance_fn
    ) {
        ++same_side_route_boundary_parent_advance_calls;
        const double start = wall_seconds();
        try {
            py::object available_rows_tuple =
                tuple_from_sequence_object(available_rows_obj);
            py::sequence available_rows =
                available_rows_tuple.cast<py::sequence>();
            const ssize_t n_rows =
                static_cast<ssize_t>(py::len(available_rows));
            py::dict advance_cache;
            py::list advanced_keys;
            py::list advanced_positions;
            py::list advanced_values;
            py::list remaining_keys;
            py::list remaining_positions;
            long long cache_hits = 0;
            long long cache_builds = 0;
            long long none_count = 0;
            for (ssize_t idx = 0; idx < n_rows; ++idx) {
                py::sequence row = py::reinterpret_borrow<py::sequence>(
                    available_rows[idx]
                );
                if (static_cast<ssize_t>(py::len(row)) < 5) {
                    throw std::runtime_error(
                        "available parent row must contain key, pos, parent key, local piece, parent value"
                    );
                }
                py::object key = py::reinterpret_borrow<py::object>(row[0]);
                py::object pos = py::reinterpret_borrow<py::object>(row[1]);
                py::object parent_key =
                    py::reinterpret_borrow<py::object>(row[2]);
                py::object local_piece =
                    py::reinterpret_borrow<py::object>(row[3]);
                py::object parent_value =
                    py::reinterpret_borrow<py::object>(row[4]);
                py::sequence key_seq = key.cast<py::sequence>();
                if (static_cast<ssize_t>(py::len(key_seq)) < 1) {
                    throw std::runtime_error(
                        "same-side boundary key must contain a pattern"
                    );
                }
                py::object pattern = tuple_from_sequence_object(
                    py::reinterpret_borrow<py::object>(key_seq[0])
                );
                py::object advance_key = py::make_tuple(
                    parent_key,
                    local_piece,
                    py::int_(
                        static_cast<unsigned long long>(
                            reinterpret_cast<std::uintptr_t>(parent_value.ptr())
                        )
                    )
                );
                py::object advanced = py::none();
                if (advance_cache.contains(advance_key)) {
                    advanced = py::reinterpret_borrow<py::object>(
                        advance_cache[advance_key]
                    );
                    ++cache_hits;
                } else {
                    advanced = advance_fn(pattern, parent_value);
                    advance_cache[advance_key] = advanced;
                    ++cache_builds;
                }
                if (advanced.is_none()) {
                    ++none_count;
                    remaining_keys.append(key);
                    remaining_positions.append(pos);
                    continue;
                }
                advanced_keys.append(key);
                advanced_positions.append(pos);
                advanced_values.append(advanced);
            }

            const double elapsed = wall_seconds() - start;
            ++same_side_route_boundary_parent_advance_successes;
            same_side_route_boundary_parent_advance_rows +=
                static_cast<long long>(n_rows);
            same_side_route_boundary_parent_advance_advanced +=
                static_cast<long long>(py::len(advanced_keys));
            same_side_route_boundary_parent_advance_remaining +=
                static_cast<long long>(py::len(remaining_keys));
            same_side_route_boundary_parent_advance_cache_hits += cache_hits;
            same_side_route_boundary_parent_advance_cache_builds += cache_builds;
            same_side_route_boundary_parent_advance_none += none_count;
            same_side_route_boundary_parent_advance_seconds += elapsed;
            same_side_route_boundary_parent_advance_last_seconds = elapsed;
            same_side_route_boundary_parent_advance_last_error.clear();

            py::dict out;
            out["advanced_keys"] = tuple_from_sequence_object(advanced_keys);
            out["advanced_positions"] =
                tuple_from_sequence_object(advanced_positions);
            out["advanced_values"] = tuple_from_sequence_object(advanced_values);
            out["remaining_keys"] = tuple_from_sequence_object(remaining_keys);
            out["remaining_positions"] =
                tuple_from_sequence_object(remaining_positions);
            out["rows"] = py::int_(n_rows);
            out["advanced"] = py::int_(py::len(advanced_keys));
            out["remaining"] = py::int_(py::len(remaining_keys));
            out["cache_hits"] = py::int_(cache_hits);
            out["cache_builds"] = py::int_(cache_builds);
            out["none"] = py::int_(none_count);
            out["seconds"] = py::float_(elapsed);
            return out;
        } catch (const py::error_already_set& exc) {
            ++same_side_route_boundary_parent_advance_failures;
            const double elapsed = wall_seconds() - start;
            same_side_route_boundary_parent_advance_seconds += elapsed;
            same_side_route_boundary_parent_advance_last_seconds = elapsed;
            same_side_route_boundary_parent_advance_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++same_side_route_boundary_parent_advance_failures;
            const double elapsed = wall_seconds() - start;
            same_side_route_boundary_parent_advance_seconds += elapsed;
            same_side_route_boundary_parent_advance_last_seconds = elapsed;
            same_side_route_boundary_parent_advance_last_error = exc.what();
            throw;
        }
    }

    py::dict prepare_same_side_route_missing_parent_builds(
        py::object missing_parent_rows_obj
    ) {
        ++same_side_route_missing_parent_build_plan_calls;
        const double start = wall_seconds();
        try {
            py::object rows_tuple =
                tuple_from_sequence_object(missing_parent_rows_obj);
            py::sequence rows = rows_tuple.cast<py::sequence>();
            const ssize_t n_rows = static_cast<ssize_t>(py::len(rows));
            py::dict parent_pos;
            py::list unique_parent_keys;
            py::list parent_patterns;
            py::list planned_rows;
            auto append_unique_parent = [&](
                py::object parent_key
            ) -> long long {
                if (parent_pos.contains(parent_key)) {
                    return py::cast<long long>(parent_pos[parent_key]);
                }
                const long long parent_idx =
                    static_cast<long long>(py::len(unique_parent_keys));
                parent_pos[parent_key] = py::int_(parent_idx);
                unique_parent_keys.append(parent_key);
                py::sequence parent_seq = parent_key.cast<py::sequence>();
                if (static_cast<ssize_t>(py::len(parent_seq)) < 1) {
                    throw std::runtime_error(
                        "same-side missing parent key must contain a pattern"
                    );
                }
                parent_patterns.append(tuple_from_sequence_object(
                    py::reinterpret_borrow<py::object>(parent_seq[0])
                ));
                return parent_idx;
            };
            for (ssize_t idx = 0; idx < n_rows; ++idx) {
                py::sequence row = py::reinterpret_borrow<py::sequence>(
                    rows[idx]
                );
                if (static_cast<ssize_t>(py::len(row)) < 4) {
                    throw std::runtime_error(
                        "missing parent row must contain key, pos, parent key, local piece"
                    );
                }
                py::object key = py::reinterpret_borrow<py::object>(row[0]);
                py::object pos = py::reinterpret_borrow<py::object>(row[1]);
                py::object parent_key =
                    py::reinterpret_borrow<py::object>(row[2]);
                py::object local_piece =
                    py::reinterpret_borrow<py::object>(row[3]);
                const long long parent_idx = append_unique_parent(parent_key);
                planned_rows.append(py::make_tuple(
                    key,
                    pos,
                    py::int_(parent_idx),
                    parent_key,
                    local_piece
                ));
            }
            const double elapsed = wall_seconds() - start;
            ++same_side_route_missing_parent_build_plan_successes;
            same_side_route_missing_parent_build_plan_rows +=
                static_cast<long long>(n_rows);
            same_side_route_missing_parent_build_plan_unique +=
                static_cast<long long>(py::len(unique_parent_keys));
            same_side_route_missing_parent_build_plan_seconds += elapsed;
            same_side_route_missing_parent_build_plan_last_seconds = elapsed;
            same_side_route_missing_parent_build_plan_last_error.clear();

            py::dict out;
            out["unique_parent_keys"] =
                tuple_from_sequence_object(unique_parent_keys);
            out["parent_patterns"] =
                tuple_from_sequence_object(parent_patterns);
            out["parent_rows"] = tuple_from_sequence_object(planned_rows);
            out["rows"] = py::int_(n_rows);
            out["unique"] = py::int_(py::len(unique_parent_keys));
            out["seconds"] = py::float_(elapsed);
            return out;
        } catch (const py::error_already_set& exc) {
            ++same_side_route_missing_parent_build_plan_failures;
            const double elapsed = wall_seconds() - start;
            same_side_route_missing_parent_build_plan_seconds += elapsed;
            same_side_route_missing_parent_build_plan_last_seconds = elapsed;
            same_side_route_missing_parent_build_plan_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++same_side_route_missing_parent_build_plan_failures;
            const double elapsed = wall_seconds() - start;
            same_side_route_missing_parent_build_plan_seconds += elapsed;
            same_side_route_missing_parent_build_plan_last_seconds = elapsed;
            same_side_route_missing_parent_build_plan_last_error = exc.what();
            throw;
        }
    }

    py::dict prepare_same_side_route_built_parent_advances(
        py::object parent_rows_obj,
        py::object unique_parent_keys_obj,
        py::object built_parent_values_obj
    ) {
        ++same_side_route_built_parent_advance_plan_calls;
        const double start = wall_seconds();
        try {
            py::object parent_rows_tuple =
                tuple_from_sequence_object(parent_rows_obj);
            py::object unique_parent_keys_tuple =
                tuple_from_sequence_object(unique_parent_keys_obj);
            py::object built_parent_values_tuple =
                tuple_from_sequence_object(built_parent_values_obj);
            py::sequence parent_rows =
                parent_rows_tuple.cast<py::sequence>();
            py::sequence unique_parent_keys =
                unique_parent_keys_tuple.cast<py::sequence>();
            py::sequence built_parent_values =
                built_parent_values_tuple.cast<py::sequence>();
            const ssize_t n_rows =
                static_cast<ssize_t>(py::len(parent_rows));
            const ssize_t n_unique =
                static_cast<ssize_t>(py::len(unique_parent_keys));
            py::list parent_put_keys;
            py::list parent_put_values;
            for (ssize_t idx = 0; idx < n_unique; ++idx) {
                py::object value = py::none();
                if (idx < static_cast<ssize_t>(py::len(built_parent_values))) {
                    value = py::reinterpret_borrow<py::object>(
                        built_parent_values[idx]
                    );
                }
                if (!value.is_none()) {
                    parent_put_keys.append(
                        py::reinterpret_borrow<py::object>(
                            unique_parent_keys[idx]
                        )
                    );
                    parent_put_values.append(value);
                }
            }

            py::list available_rows;
            py::list remaining_rows;
            for (ssize_t idx = 0; idx < n_rows; ++idx) {
                py::sequence row = py::reinterpret_borrow<py::sequence>(
                    parent_rows[idx]
                );
                if (static_cast<ssize_t>(py::len(row)) < 5) {
                    throw std::runtime_error(
                        "built parent row must contain key, pos, parent index, parent key, local piece"
                    );
                }
                py::object key = py::reinterpret_borrow<py::object>(row[0]);
                py::object pos = py::reinterpret_borrow<py::object>(row[1]);
                const long long parent_idx = py::cast<long long>(
                    py::reinterpret_borrow<py::object>(row[2])
                );
                py::object parent_key =
                    py::reinterpret_borrow<py::object>(row[3]);
                py::object local_piece =
                    py::reinterpret_borrow<py::object>(row[4]);
                py::object parent_value = py::none();
                if (
                    parent_idx >= 0 &&
                    parent_idx < static_cast<long long>(
                        py::len(built_parent_values)
                    )
                ) {
                    parent_value = py::reinterpret_borrow<py::object>(
                        built_parent_values[parent_idx]
                    );
                }
                if (parent_value.is_none()) {
                    remaining_rows.append(py::make_tuple(
                        key,
                        pos,
                        parent_key,
                        local_piece
                    ));
                    continue;
                }
                available_rows.append(py::make_tuple(
                    key,
                    pos,
                    parent_key,
                    local_piece,
                    parent_value
                ));
            }

            const double elapsed = wall_seconds() - start;
            ++same_side_route_built_parent_advance_plan_successes;
            same_side_route_built_parent_advance_plan_rows +=
                static_cast<long long>(n_rows);
            same_side_route_built_parent_advance_plan_available +=
                static_cast<long long>(py::len(available_rows));
            same_side_route_built_parent_advance_plan_missing +=
                static_cast<long long>(py::len(remaining_rows));
            same_side_route_built_parent_advance_plan_puts +=
                static_cast<long long>(py::len(parent_put_keys));
            same_side_route_built_parent_advance_plan_seconds += elapsed;
            same_side_route_built_parent_advance_plan_last_seconds = elapsed;
            same_side_route_built_parent_advance_plan_last_error.clear();

            py::dict out;
            out["parent_put_keys"] =
                tuple_from_sequence_object(parent_put_keys);
            out["parent_put_values"] =
                tuple_from_sequence_object(parent_put_values);
            out["available_rows"] = tuple_from_sequence_object(available_rows);
            out["remaining_rows"] = tuple_from_sequence_object(remaining_rows);
            out["rows"] = py::int_(n_rows);
            out["available"] = py::int_(py::len(available_rows));
            out["missing"] = py::int_(py::len(remaining_rows));
            out["puts"] = py::int_(py::len(parent_put_keys));
            out["seconds"] = py::float_(elapsed);
            return out;
        } catch (const py::error_already_set& exc) {
            ++same_side_route_built_parent_advance_plan_failures;
            const double elapsed = wall_seconds() - start;
            same_side_route_built_parent_advance_plan_seconds += elapsed;
            same_side_route_built_parent_advance_plan_last_seconds = elapsed;
            same_side_route_built_parent_advance_plan_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++same_side_route_built_parent_advance_plan_failures;
            const double elapsed = wall_seconds() - start;
            same_side_route_built_parent_advance_plan_seconds += elapsed;
            same_side_route_built_parent_advance_plan_last_seconds = elapsed;
            same_side_route_built_parent_advance_plan_last_error = exc.what();
            throw;
        }
    }

    py::dict select_same_side_route_identity_rows(
        py::object route_plan,
        py::object p_entries,
        py::object consumed
    ) {
        ++same_side_route_identity_select_calls;
        const double start = wall_seconds();
        try {
            py::dict p_dict = p_entries.cast<py::dict>();
            py::object raw_tuples_obj =
                py::getattr(route_plan, "raw_key_tuples", py::tuple());
            py::object term_counts_obj =
                py::getattr(route_plan, "term_counts", py::tuple());
            py::sequence raw_tuples =
                raw_tuples_obj.is_none()
                    ? py::tuple().cast<py::sequence>()
                    : raw_tuples_obj.cast<py::sequence>();
            py::array_t<long long, py::array::c_style | py::array::forcecast>
                term_counts = term_counts_obj.cast<
                    py::array_t<long long, py::array::c_style | py::array::forcecast>
                >();
            const ssize_t n_raw_tuples =
                static_cast<ssize_t>(py::len(raw_tuples));
            const ssize_t n_term_counts =
                term_counts.ndim() == 1
                    ? static_cast<ssize_t>(term_counts.shape(0))
                    : 0;
            const bool tuple_rows = (
                n_raw_tuples > 0 && n_term_counts >= n_raw_tuples
            );
            py::array_t<long long, py::array::c_style | py::array::forcecast>
                raw_rows;
            py::array_t<long long, py::array::c_style | py::array::forcecast>
                offsets;
            ssize_t usable_rows = 0;
            if (tuple_rows) {
                usable_rows = n_raw_tuples;
            } else {
                raw_rows = route_plan.attr("raw_keys").cast<
                    py::array_t<long long, py::array::c_style | py::array::forcecast>
                >();
                offsets = route_plan.attr("offsets").cast<
                    py::array_t<long long, py::array::c_style | py::array::forcecast>
                >();
                if (raw_rows.ndim() != 2 || offsets.ndim() != 1) {
                    throw std::runtime_error(
                        "same-side route plan raw_keys must be rank-2 and offsets rank-1"
                    );
                }
                usable_rows = std::min<ssize_t>(
                    static_cast<ssize_t>(raw_rows.shape(0)),
                    std::max<ssize_t>(
                        0,
                        static_cast<ssize_t>(offsets.shape(0)) - 1
                    )
                );
            }

            auto consumed_contains = [&](py::object key) -> bool {
                int contains = 0;
                if (PySet_Check(consumed.ptr())) {
                    contains = PySet_Contains(consumed.ptr(), key.ptr());
                } else {
                    contains = PySequence_Contains(consumed.ptr(), key.ptr());
                }
                if (contains < 0) {
                    throw py::error_already_set();
                }
                return contains != 0;
            };

            std::vector<long long> rows;
            std::vector<cdouble> coeffs;
            py::list raw_keys;
            long long scanned = 0;
            long long skipped_consumed = 0;
            long long skipped_zero = 0;
            long long selected_terms = 0;
            auto term_count_view = term_counts.unchecked<1>();
            auto consume_row = [&](ssize_t row, py::object raw_key, long long term_count) {
                ++scanned;
                if (consumed_contains(raw_key)) {
                    ++skipped_consumed;
                    return;
                }
                cdouble coeff(0.0, 0.0);
                if (p_dict.contains(raw_key)) {
                    coeff = py::cast<cdouble>(
                        py::reinterpret_borrow<py::object>(p_dict[raw_key])
                    );
                }
                if (std::abs(coeff) <= 1.0e-14) {
                    ++skipped_zero;
                    return;
                }
                if (term_count <= 0) {
                    return;
                }
                rows.push_back(static_cast<long long>(row));
                coeffs.push_back(coeff);
                raw_keys.append(raw_key);
                selected_terms += term_count;
            };
            if (tuple_rows) {
                for (ssize_t row = 0; row < usable_rows; ++row) {
                    consume_row(
                        row,
                        py::reinterpret_borrow<py::object>(raw_tuples[row]),
                        static_cast<long long>(term_count_view(row))
                    );
                }
            } else {
                auto offset_view = offsets.unchecked<1>();
                auto raw_view = raw_rows.unchecked<2>();
                for (ssize_t row = 0; row < usable_rows; ++row) {
                    py::list key_items;
                    const ssize_t n_cols =
                        static_cast<ssize_t>(raw_rows.shape(1));
                    for (ssize_t col = 0; col < n_cols; ++col) {
                        key_items.append(py::int_(raw_view(row, col)));
                    }
                    const long long row_start =
                        static_cast<long long>(offset_view(row));
                    const long long row_stop =
                        static_cast<long long>(offset_view(row + 1));
                    consume_row(
                        row,
                        tuple_from_sequence_object(key_items),
                        row_stop - row_start
                    );
                }
            }

            py::array_t<long long> row_array(static_cast<ssize_t>(rows.size()));
            py::array_t<cdouble> coeff_array(static_cast<ssize_t>(coeffs.size()));
            auto row_out = row_array.mutable_unchecked<1>();
            auto coeff_out = coeff_array.mutable_unchecked<1>();
            for (ssize_t idx = 0; idx < static_cast<ssize_t>(rows.size()); ++idx) {
                row_out(idx) = rows[static_cast<size_t>(idx)];
                coeff_out(idx) = coeffs[static_cast<size_t>(idx)];
            }

            const double elapsed = wall_seconds() - start;
            same_side_route_identity_select_rows +=
                static_cast<long long>(rows.size());
            same_side_route_identity_select_terms += selected_terms;
            same_side_route_identity_select_scanned += scanned;
            same_side_route_identity_select_skipped_consumed += skipped_consumed;
            same_side_route_identity_select_skipped_zero += skipped_zero;
            same_side_route_identity_select_seconds += elapsed;
            same_side_route_identity_select_last_seconds = elapsed;
            same_side_route_identity_select_last_error.clear();

            py::dict out;
            out["rows"] = row_array;
            out["coeffs"] = coeff_array;
            out["raw_keys"] = tuple_from_sequence_object(raw_keys);
            out["terms"] = py::int_(selected_terms);
            out["usable_rows"] = py::int_(usable_rows);
            out["scanned"] = py::int_(scanned);
            out["skipped_consumed"] = py::int_(skipped_consumed);
            out["skipped_zero"] = py::int_(skipped_zero);
            out["seconds"] = py::float_(elapsed);
            return out;
        } catch (const py::error_already_set& exc) {
            ++same_side_route_identity_select_failures;
            same_side_route_identity_select_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++same_side_route_identity_select_failures;
            same_side_route_identity_select_last_error = exc.what();
            throw;
        }
    }

    py::object build_same_side_route_identity_entries(
        py::object entries_cls,
        const std::string& side,
        py::object selected_rows,
        py::object selected_coeffs,
        long long selected_terms,
        py::object route_plan,
        py::object boundary_table_ids,
        py::object boundary_values,
        py::object boundary_table,
        py::object identity_tensor,
        const std::string& source
    ) {
        ++same_side_route_identity_entry_build_calls;
        const double start = wall_seconds();
        try {
            py::array_t<long long, py::array::c_style | py::array::forcecast>
                rows = selected_rows.cast<
                    py::array_t<long long, py::array::c_style | py::array::forcecast>
                >();
            py::array_t<cdouble, py::array::c_style | py::array::forcecast>
                coeffs = selected_coeffs.cast<
                    py::array_t<cdouble, py::array::c_style | py::array::forcecast>
                >();
            if (rows.ndim() != 1 || coeffs.ndim() != 1) {
                throw std::runtime_error(
                    "same-side route identity selected rows/coeffs must be rank-1"
                );
            }
            const ssize_t n_rows = static_cast<ssize_t>(rows.shape(0));
            if (static_cast<ssize_t>(coeffs.shape(0)) != n_rows) {
                throw std::runtime_error(
                    "same-side route identity selected rows and coeffs differ"
                );
            }
            py::object out = entries_cls(
                py::arg("side") = py::str(side),
                py::arg("row_ids") = rows,
                py::arg("row_coeffs") = coeffs,
                py::arg("route_plan") = route_plan,
                py::arg("boundary_table_ids") = boundary_table_ids,
                py::arg("boundary_values") = boundary_values,
                py::arg("boundary_table") = boundary_table,
                py::arg("identity_tensor") = identity_tensor,
                py::arg("source") = py::str(source)
            );
            const double elapsed = wall_seconds() - start;
            same_side_route_identity_entry_build_rows +=
                static_cast<long long>(n_rows);
            same_side_route_identity_entry_build_terms +=
                static_cast<long long>(selected_terms);
            same_side_route_identity_entry_build_seconds += elapsed;
            same_side_route_identity_entry_build_last_seconds = elapsed;
            same_side_route_identity_entry_build_last_error.clear();
            return out;
        } catch (const py::error_already_set& exc) {
            ++same_side_route_identity_entry_build_failures;
            same_side_route_identity_entry_build_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++same_side_route_identity_entry_build_failures;
            same_side_route_identity_entry_build_last_error = exc.what();
            throw;
        }
    }

    void clear_direct_family_payloads() {
        const long long cleared =
            static_cast<long long>(direct_family_payload_records.size());
        if (cleared != 0) {
            direct_family_payload_records.clear();
            ++direct_family_payload_clears;
            direct_family_payload_cleared_entries += cleared;
        }
    }

    void install_direct_family_payload_builder(
        const std::string& key,
        py::object builder
    ) {
        if (builder.is_none() || !PyCallable_Check(builder.ptr())) {
            direct_family_payload_builder_last_error =
                "direct-family payload builder must be callable";
            ++direct_family_payload_builder_failures;
            throw std::runtime_error(direct_family_payload_builder_last_error);
        }
        DirectFamilyPayloadBuilderRecord record;
        record.builder = std::move(builder);
        auto it = direct_family_payload_builder_records.find(key);
        if (it == direct_family_payload_builder_records.end()) {
            direct_family_payload_builder_records.emplace(key, std::move(record));
        } else {
            it->second = std::move(record);
            ++direct_family_payload_builder_replacements;
        }
        ++direct_family_payload_builder_installs;
        direct_family_payload_builder_last_error.clear();
    }

    static long long direct_family_payload_entry_count(py::handle payload) {
        if (!payload || payload.is_none()) {
            return 0;
        }
        try {
            if (py::isinstance<py::dict>(payload)) {
                py::dict dict = py::reinterpret_borrow<py::dict>(payload);
                long long count = 0;
                for (auto item : dict) {
                    py::object entries =
                        py::reinterpret_borrow<py::object>(item.second);
                    try {
                        count += static_cast<long long>(py::len(entries));
                    } catch (const py::error_already_set&) {
                        PyErr_Clear();
                    } catch (const std::exception&) {
                    }
                }
                return count;
            }
            return static_cast<long long>(py::len(payload));
        } catch (const py::error_already_set&) {
            PyErr_Clear();
            return 0;
        } catch (const std::exception&) {
            return 0;
        }
    }

    py::object prepare_direct_family_payload_from_builder(
        const std::string& payload_key,
        const std::string& builder_key,
        bool force = false
    ) {
        ++direct_family_payload_builder_prepare_calls;
        if (!force) {
            auto payload_it = direct_family_payload_records.find(payload_key);
            if (payload_it != direct_family_payload_records.end()) {
                ++direct_family_payload_builder_cache_hits;
                ++direct_family_payload_hits;
                direct_family_payload_builder_last_error.clear();
                return payload_it->second;
            }
        }
        auto builder_it = direct_family_payload_builder_records.find(builder_key);
        if (builder_it == direct_family_payload_builder_records.end()) {
            ++direct_family_payload_builder_misses;
            ++direct_family_payload_builder_failures;
            direct_family_payload_builder_last_error =
                "MovingEnvironment direct-family payload builder record is absent";
            throw std::runtime_error(direct_family_payload_builder_last_error);
        }
        try {
            const double build_start = wall_seconds();
            py::object payload = builder_it->second.builder();
            const double build_elapsed = wall_seconds() - build_start;
            const long long entries = direct_family_payload_entry_count(payload);
            install_direct_family_payload(payload_key, payload);
            ++direct_family_payload_builder_builds;
            direct_family_payload_builder_build_seconds += build_elapsed;
            direct_family_payload_builder_last_build_seconds = build_elapsed;
            direct_family_payload_builder_entries += entries;
            direct_family_payload_builder_last_entries = entries;
            direct_family_payload_builder_last_error.clear();
            return payload;
        } catch (const py::error_already_set& exc) {
            ++direct_family_payload_builder_failures;
            direct_family_payload_builder_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++direct_family_payload_builder_failures;
            direct_family_payload_builder_last_error = exc.what();
            throw;
        }
    }

    void clear_direct_family_payload_builders() {
        const long long cleared =
            static_cast<long long>(direct_family_payload_builder_records.size());
        if (cleared != 0) {
            direct_family_payload_builder_records.clear();
            ++direct_family_payload_builder_clears;
            direct_family_payload_builder_cleared_entries += cleared;
        }
    }

    static py::object owner_step_object_or_none(py::object value) {
        if (value.is_none()) {
            return py::none();
        }
        return value;
    }

    void install_owner_bond_step(
        const std::string& key,
        py::object prepare,
        py::object prepare_payload,
        py::object optimize,
        py::object assign,
        py::object invalidate,
        py::object cache_guess,
        py::object move_environment,
        py::object fallback_environment,
        const std::string& direct_family_payload_key = "",
        const std::string& direct_family_builder_key = "",
        const std::string& direct_family_plan_key = "",
        const std::string& owner_local_optimize_key = ""
    ) {
        OwnerBondStepRecord record;
        record.prepare = owner_step_object_or_none(prepare);
        record.prepare_payload = owner_step_object_or_none(prepare_payload);
        record.optimize = owner_step_object_or_none(optimize);
        record.assign = owner_step_object_or_none(assign);
        record.invalidate = owner_step_object_or_none(invalidate);
        record.cache_guess = owner_step_object_or_none(cache_guess);
        record.move_environment = owner_step_object_or_none(move_environment);
        record.fallback_environment =
            owner_step_object_or_none(fallback_environment);
        record.direct_family_payload_key = direct_family_payload_key;
        record.direct_family_builder_key = direct_family_builder_key;
        record.direct_family_plan_key = direct_family_plan_key;
        record.owner_local_optimize_key = owner_local_optimize_key;
        auto it = owner_bond_step_records.find(key);
        if (it == owner_bond_step_records.end()) {
            owner_bond_step_records.emplace(key, std::move(record));
        } else {
            ++owner_bond_step_record_replacements;
            it->second = std::move(record);
        }
        ++owner_bond_step_record_installs;
        owner_bond_step_record_last_error.clear();
    }

    void clear_owner_bond_steps() {
        const long long cleared =
            static_cast<long long>(owner_bond_step_records.size());
        if (cleared != 0) {
            owner_bond_step_records.clear();
            ++owner_bond_step_record_clears;
            owner_bond_step_record_cleared_entries += cleared;
        }
    }

    void install_owner_typed_bond_step(
        const std::string& key,
        py::object bridge,
        int bond,
        const std::string& sweep_direction,
        const std::string& step_direction,
        const std::string& clear_side,
        bool should_move = true,
        const std::string& direct_family_payload_key = "",
        const std::string& direct_family_builder_key = "",
        const std::string& direct_family_plan_key = "",
        py::object direct_family_plan_provider = py::none(),
        const std::string& owner_local_optimize_key = "",
        py::object moving_environment = py::none(),
        const std::string& environment_direction = "",
        py::object update_rows = py::none(),
        py::object pop_rows = py::none(),
        py::object update_records = py::none(),
        py::object pop_records = py::none()
    ) {
        OwnerTypedBondStepRecord record;
        record.bridge = bridge;
        record.moving_environment = owner_step_object_or_none(moving_environment);
        record.bond = bond;
        record.sweep_direction = sweep_direction;
        record.step_direction = step_direction;
        record.clear_side = clear_side;
        record.should_move = should_move;
        record.direct_family_payload_key = direct_family_payload_key;
        record.direct_family_builder_key = direct_family_builder_key;
        record.direct_family_plan_key = direct_family_plan_key;
        record.direct_family_plan_provider =
            owner_step_object_or_none(direct_family_plan_provider);
        if (
            !record.direct_family_plan_provider.is_none() &&
            PyCallable_Check(record.direct_family_plan_provider.ptr())
        ) {
            ++owner_typed_bond_step_direct_plan_provider_record_installs;
        }
        record.owner_local_optimize_key = owner_local_optimize_key;
        record.environment_direction = environment_direction;
        record.update_rows = owner_step_object_or_none(update_rows);
        record.pop_rows = owner_step_object_or_none(pop_rows);
        record.update_records = owner_step_object_or_none(update_records);
        record.pop_records = owner_step_object_or_none(pop_records);
        auto it = owner_typed_bond_step_records.find(key);
        if (it == owner_typed_bond_step_records.end()) {
            owner_typed_bond_step_records.emplace(key, std::move(record));
        } else {
            ++owner_typed_bond_step_record_replacements;
            it->second = std::move(record);
        }
        ++owner_typed_bond_step_record_installs;
        owner_typed_bond_step_record_last_error.clear();
    }

    void clear_owner_typed_bond_steps() {
        const long long cleared =
            static_cast<long long>(owner_typed_bond_step_records.size());
        if (cleared != 0) {
            owner_typed_bond_step_records.clear();
            ++owner_typed_bond_step_record_clears;
            owner_typed_bond_step_record_cleared_entries += cleared;
        }
    }

    py::dict update_owner_typed_bond_step_direct_family_keys(
        const std::string& key,
        const std::string& direct_family_payload_key = "",
        const std::string& direct_family_builder_key = "",
        const std::string& direct_family_plan_key = ""
    ) {
        py::dict out;
        auto it = owner_typed_bond_step_records.find(key);
        if (it == owner_typed_bond_step_records.end()) {
            ++owner_typed_bond_step_direct_key_update_misses;
            out["updated"] = py::bool_(false);
            out["reason"] = py::str("missing_typed_bond_step_record");
            return out;
        }
        try {
            OwnerTypedBondStepRecord& record = it->second;
            record.direct_family_payload_key = direct_family_payload_key;
            record.direct_family_builder_key = direct_family_builder_key;
            record.direct_family_plan_key = direct_family_plan_key;
            if (!record.owner_local_optimize_key.empty()) {
                auto local_it = owner_local_optimize_records.find(
                    record.owner_local_optimize_key
                );
                if (local_it != owner_local_optimize_records.end()) {
                    local_it->second.direct_family_payload_key =
                        direct_family_payload_key;
                }
            }
            ++owner_typed_bond_step_direct_key_updates;
            out["updated"] = py::bool_(true);
            out["payload_key"] = py::str(direct_family_payload_key);
            out["builder_key"] = py::str(direct_family_builder_key);
            out["plan_key"] = py::str(direct_family_plan_key);
            return out;
        } catch (...) {
            ++owner_typed_bond_step_direct_key_update_failures;
            throw;
        }
    }

    py::dict refresh_owner_typed_bond_step_direct_family_keys_from_provider(
        const std::string& key,
        int bond,
        py::object provider
    ) {
        return refresh_owner_typed_bond_step_direct_family_keys_from_provider_impl(
            key,
            bond,
            provider,
            false
        );
    }

    py::dict refresh_owner_typed_bond_step_direct_family_keys_from_provider_impl(
        const std::string& key,
        int bond,
        py::object provider,
        bool successor_refresh
    ) {
        py::dict out;
        if (provider.is_none() || !PyCallable_Check(provider.ptr())) {
            ++owner_typed_bond_step_direct_key_provider_refresh_empty;
            if (successor_refresh) {
                ++owner_typed_bond_step_direct_key_successor_refresh_empty;
            }
            out["updated"] = py::bool_(false);
            out["reason"] = py::str("missing_provider");
            return out;
        }
        ++owner_typed_bond_step_direct_key_provider_refresh_calls;
        if (successor_refresh) {
            ++owner_typed_bond_step_direct_key_successor_refresh_calls;
        }
        std::string payload_key;
        std::string builder_key;
        std::string plan_key;
        try {
            py::object provided = provider(py::int_(bond), py::str(key));
            if (!provided.is_none()) {
                if (py::isinstance<py::dict>(provided)) {
                    py::dict info = provided.cast<py::dict>();
                    if (info.contains(py::str("payload_key"))) {
                        py::object value = py::reinterpret_borrow<py::object>(
                            info[py::str("payload_key")]
                        );
                        if (!value.is_none()) {
                            payload_key = py::cast<std::string>(value);
                        }
                    }
                    if (info.contains(py::str("builder_key"))) {
                        py::object value = py::reinterpret_borrow<py::object>(
                            info[py::str("builder_key")]
                        );
                        if (!value.is_none()) {
                            builder_key = py::cast<std::string>(value);
                        }
                    }
                    if (info.contains(py::str("plan_key"))) {
                        py::object value = py::reinterpret_borrow<py::object>(
                            info[py::str("plan_key")]
                        );
                        if (!value.is_none()) {
                            plan_key = py::cast<std::string>(value);
                        }
                    }
                } else {
                    py::tuple pair =
                        tuple_from_sequence_object(provided).cast<py::tuple>();
                    if (py::len(pair) >= 2) {
                        payload_key = py::cast<std::string>(pair[0]);
                        plan_key = py::cast<std::string>(pair[1]);
                    }
                }
            }
        } catch (const py::error_already_set&) {
            ++owner_typed_bond_step_direct_key_provider_refresh_failures;
            if (successor_refresh) {
                ++owner_typed_bond_step_direct_key_successor_refresh_failures;
            }
            PyErr_Clear();
            update_owner_typed_bond_step_direct_family_keys(key, "", "", "");
            out["updated"] = py::bool_(false);
            out["reason"] = py::str("provider_exception");
            return out;
        } catch (const std::exception&) {
            ++owner_typed_bond_step_direct_key_provider_refresh_failures;
            if (successor_refresh) {
                ++owner_typed_bond_step_direct_key_successor_refresh_failures;
            }
            update_owner_typed_bond_step_direct_family_keys(key, "", "", "");
            out["updated"] = py::bool_(false);
            out["reason"] = py::str("provider_exception");
            return out;
        }
        if (payload_key.empty()) {
            ++owner_typed_bond_step_direct_key_provider_refresh_empty;
            if (successor_refresh) {
                ++owner_typed_bond_step_direct_key_successor_refresh_empty;
            }
            update_owner_typed_bond_step_direct_family_keys(key, "", "", "");
            out["updated"] = py::bool_(false);
            out["reason"] = py::str("empty_payload_key");
            return out;
        }
        py::dict updated = update_owner_typed_bond_step_direct_family_keys(
            key,
            payload_key,
            builder_key,
            plan_key
        );
        if (py::cast<bool>(updated[py::str("updated")])) {
            ++owner_typed_bond_step_direct_key_provider_refresh_accepts;
            if (successor_refresh) {
                ++owner_typed_bond_step_direct_key_successor_refresh_accepts;
            }
        } else {
            ++owner_typed_bond_step_direct_key_provider_refresh_empty;
            if (successor_refresh) {
                ++owner_typed_bond_step_direct_key_successor_refresh_empty;
            }
        }
        return updated;
    }

    py::dict update_owner_typed_bond_step_direct_family_successor(
        const std::string& key,
        int successor_bond,
        const std::string& successor_step_key,
        py::object provider = py::none()
    ) {
        py::dict out;
        auto it = owner_typed_bond_step_records.find(key);
        if (it == owner_typed_bond_step_records.end()) {
            ++owner_typed_bond_step_direct_key_update_misses;
            out["updated"] = py::bool_(false);
            out["reason"] = py::str("missing_typed_bond_step_record");
            return out;
        }
        OwnerTypedBondStepRecord& record = it->second;
        record.successor_direct_family_bond = successor_bond;
        record.successor_direct_family_step_key = successor_step_key;
        record.successor_direct_family_key_provider =
            owner_step_object_or_none(provider);
        out["updated"] = py::bool_(true);
        out["successor_bond"] = py::int_(successor_bond);
        out["successor_step_key"] = py::str(successor_step_key);
        return out;
    }

    py::dict install_owner_typed_bond_step_direct_family_successor_chain(
        py::sequence step_keys,
        py::object provider = py::none()
    ) {
        ++owner_typed_bond_step_direct_key_successor_chain_calls;
        py::dict out;
        std::vector<std::pair<int, std::string>> steps;
        try {
            const ssize_t n = static_cast<ssize_t>(py::len(step_keys));
            steps.reserve(static_cast<size_t>(std::max<ssize_t>(0, n)));
            for (ssize_t idx = 0; idx < n; ++idx) {
                py::object item =
                    py::reinterpret_borrow<py::object>(step_keys[idx]);
                py::tuple pair = tuple_from_sequence_object(item).cast<py::tuple>();
                if (py::len(pair) < 2) {
                    throw std::runtime_error(
                        "direct-family successor chain entries must be (bond, key)"
                    );
                }
                steps.emplace_back(
                    py::cast<int>(pair[0]),
                    py::cast<std::string>(pair[1])
                );
            }
            if (steps.empty()) {
                out["updated"] = py::bool_(false);
                out["reason"] = py::str("empty_step_keys");
                out["links"] = py::int_(0);
                return out;
            }

            py::dict first = refresh_owner_typed_bond_step_direct_family_keys_from_provider_impl(
                steps.front().second,
                steps.front().first,
                provider,
                false
            );
            const bool first_updated =
                first.contains(py::str("updated")) &&
                py::cast<bool>(first[py::str("updated")]);

            long long links = 0;
            for (size_t idx = 0; idx + 1 < steps.size(); ++idx) {
                py::dict linked = update_owner_typed_bond_step_direct_family_successor(
                    steps[idx].second,
                    steps[idx + 1].first,
                    steps[idx + 1].second,
                    provider
                );
                if (
                    linked.contains(py::str("updated")) &&
                    py::cast<bool>(linked[py::str("updated")])
                ) {
                    ++links;
                }
            }
            py::dict tail = update_owner_typed_bond_step_direct_family_successor(
                steps.back().second,
                -1,
                "",
                py::none()
            );
            if (
                tail.contains(py::str("updated")) &&
                py::cast<bool>(tail[py::str("updated")])
            ) {
                ++links;
            }

            owner_typed_bond_step_direct_key_successor_chain_links += links;
            if (first_updated) {
                ++owner_typed_bond_step_direct_key_successor_chain_accepts;
            }
            out["updated"] = py::bool_(first_updated);
            out["links"] = py::int_(links);
            out["steps"] = py::int_(static_cast<long long>(steps.size()));
            out["first"] = first;
            return out;
        } catch (const py::error_already_set&) {
            ++owner_typed_bond_step_direct_key_successor_chain_failures;
            throw;
        } catch (const std::exception&) {
            ++owner_typed_bond_step_direct_key_successor_chain_failures;
            throw;
        }
    }

    void install_owner_typed_half_sweep_plan(
        const std::string& key,
        const std::string& direction,
        py::sequence step_keys,
        const std::string& step_direction
    ) {
        OwnerTypedHalfSweepPlanRecord record;
        record.direction = direction;
        record.step_direction = step_direction;
        const ssize_t n = static_cast<ssize_t>(py::len(step_keys));
        record.step_keys.reserve(static_cast<size_t>(std::max<ssize_t>(0, n)));
        for (ssize_t idx = 0; idx < n; ++idx) {
            py::object item = py::reinterpret_borrow<py::object>(step_keys[idx]);
            py::tuple pair = tuple_from_sequence_object(item).cast<py::tuple>();
            if (py::len(pair) != 2) {
                owner_typed_half_sweep_plan_last_error =
                    "owner typed half-sweep plan entries must be (bond, key)";
                throw std::runtime_error(owner_typed_half_sweep_plan_last_error);
            }
            record.step_keys.emplace_back(
                py::cast<ssize_t>(pair[0]),
                py::cast<std::string>(pair[1])
            );
        }
        auto it = owner_typed_half_sweep_plan_records.find(key);
        if (it == owner_typed_half_sweep_plan_records.end()) {
            owner_typed_half_sweep_plan_records.emplace(key, std::move(record));
        } else {
            ++owner_typed_half_sweep_plan_replacements;
            it->second = std::move(record);
        }
        ++owner_typed_half_sweep_plan_installs;
        owner_typed_half_sweep_plan_last_error.clear();
    }

    void clear_owner_typed_half_sweep_plans() {
        owner_typed_half_sweep_plan_records.clear();
    }

    OwnerSiteChainRecord& owner_site_chain_for(const std::string& key) {
        auto found = owner_site_chain_records.find(key);
        if (found == owner_site_chain_records.end()) {
            ++owner_site_chain_failures;
            throw std::runtime_error("MovingEnvironment owner site-chain record is absent");
        }
        return found->second;
    }

    void install_owner_site_chain(
        const std::string& key,
        py::sequence sites
    ) {
        OwnerSiteChainRecord record;
        record.source = py::reinterpret_borrow<py::object>(sites);
        const ssize_t n_sites = static_cast<ssize_t>(py::len(sites));
        record.sites.reserve(static_cast<size_t>(std::max<ssize_t>(0, n_sites)));
        for (ssize_t site = 0; site < n_sites; ++site) {
            record.sites.push_back(
                py::reinterpret_borrow<py::object>(sites[site])
            );
        }
        auto found = owner_site_chain_records.find(key);
        if (found == owner_site_chain_records.end()) {
            owner_site_chain_records.emplace(key, std::move(record));
        } else {
            ++owner_site_chain_replacements;
            found->second = std::move(record);
        }
        ++owner_site_chain_installs;
    }

    void clear_owner_site_chains() {
        owner_site_chain_records.clear();
    }

    py::object owner_site_chain_get(
        const std::string& key,
        ssize_t site
    ) {
        OwnerSiteChainRecord& record = owner_site_chain_for(key);
        if (site < 0 || site >= static_cast<ssize_t>(record.sites.size())) {
            ++owner_site_chain_failures;
            throw std::runtime_error("MovingEnvironment owner site-chain index is out of range");
        }
        ++owner_site_chain_gets;
        return record.sites[static_cast<size_t>(site)];
    }

    void owner_site_chain_set(
        const std::string& key,
        ssize_t site,
        py::object value
    ) {
        OwnerSiteChainRecord& record = owner_site_chain_for(key);
        if (site < 0 || site >= static_cast<ssize_t>(record.sites.size())) {
            ++owner_site_chain_failures;
            throw std::runtime_error("MovingEnvironment owner site-chain index is out of range");
        }
        record.sites[static_cast<size_t>(site)] = value;
        record.dirty = true;
        ++owner_site_chain_sets;
    }

    void sync_owner_site_chain_to_sequence(
        const std::string& key,
        py::object target = py::none()
    ) {
        OwnerSiteChainRecord& record = owner_site_chain_for(key);
        py::object out = target.is_none() ? record.source : target;
        if (out.is_none()) {
            ++owner_site_chain_failures;
            throw std::runtime_error("MovingEnvironment owner site-chain has no sync target");
        }
        for (ssize_t site = 0; site < static_cast<ssize_t>(record.sites.size()); ++site) {
            out.attr("__setitem__")(
                py::int_(site),
                record.sites[static_cast<size_t>(site)]
            );
        }
        record.dirty = false;
        ++owner_site_chain_syncs;
        owner_site_chain_sync_sites += static_cast<long long>(record.sites.size());
    }

    py::dict install_owner_typed_half_sweep_template_plan(
        const std::string& plan_key,
        const std::string& direction,
        const std::string& step_direction,
        py::sequence bond_specs,
        py::object bridge,
        py::object moving_environment,
        py::object mps,
        py::object mpo,
        py::object E,
        py::object F,
        py::object m_max,
        const std::string& optimize_direction,
        py::object flat_guess_predicate,
        py::object flat_guess_cls,
        py::object block_tensor_cls,
        double davidson_tol,
        int davidson_max_iter,
        bool local_dense_enabled,
        py::object complementary_operator_families,
        py::object complementary_boundary_payload_provider,
        py::object complementary_split_stats,
        py::object complementary_family_environment_provider,
        py::object matvec_options,
        py::object site_factors,
        py::object flat_guess_cache,
        py::object environment_record_provider,
        bool native_merge_enabled,
        bool boundary_stack_access,
        const std::string& site_chain_key = ""
    ) {
        const std::string owner_id = py_handle_identity(moving_environment);
        std::vector<std::pair<ssize_t, std::string>> step_pairs;
        const ssize_t n = static_cast<ssize_t>(py::len(bond_specs));
        step_pairs.reserve(static_cast<size_t>(std::max<ssize_t>(0, n)));
        long long local_records = 0;
        long long step_records = 0;
        for (ssize_t idx = 0; idx < n; ++idx) {
            py::object item = py::reinterpret_borrow<py::object>(bond_specs[idx]);
            py::tuple spec = tuple_from_sequence_object(item).cast<py::tuple>();
            if (py::len(spec) < 2) {
                owner_typed_half_sweep_plan_last_error =
                    "typed half-sweep template bond specs must be (bond, should_move[, clear_side])";
                throw std::runtime_error(owner_typed_half_sweep_plan_last_error);
            }
            const int bond = py::cast<int>(spec[0]);
            const bool should_move = py::cast<bool>(spec[1]);
            std::string clear_side;
            if (py::len(spec) >= 3) {
                py::object clear_value = py::reinterpret_borrow<py::object>(spec[2]);
                if (!clear_value.is_none()) {
                    clear_side = py::cast<std::string>(clear_value);
                }
            }
            const std::string owner_local_key =
                "owner-local-typed:" + owner_id + ":" + step_direction + ":" +
                std::to_string(bond);
            if (owner_local_optimize_records.find(owner_local_key) ==
                owner_local_optimize_records.end()) {
                py::object site_a = py::none();
                py::object site_b = py::none();
                if (!site_chain_key.empty()) {
                    site_a = owner_site_chain_get(site_chain_key, bond);
                    site_b = owner_site_chain_get(site_chain_key, bond + 1);
                } else {
                    site_a = mps.attr("__getitem__")(py::int_(bond));
                    site_b = mps.attr("__getitem__")(py::int_(bond + 1));
                }
                py::object comp_payload = py::none();
                if (
                    !complementary_boundary_payload_provider.is_none() &&
                    PyCallable_Check(complementary_boundary_payload_provider.ptr())
                ) {
                    comp_payload = complementary_boundary_payload_provider(py::int_(bond));
                }
                py::object comp_family_env = py::none();
                if (
                    !complementary_family_environment_provider.is_none() &&
                    PyCallable_Check(complementary_family_environment_provider.ptr())
                ) {
                    comp_family_env =
                        complementary_family_environment_provider(py::int_(bond));
                }
                install_owner_local_optimize(
                    owner_local_key,
                    moving_environment,
                    bridge,
                    flat_guess_predicate,
                    flat_guess_cls,
                    block_tensor_cls,
                    site_a,
                    site_b,
                    mpo.attr("__getitem__")(py::int_(bond)),
                    mpo.attr("__getitem__")(py::int_(bond + 1)),
                    E,
                    F,
                    m_max,
                    optimize_direction,
                    py::none(),
                    davidson_tol,
                    davidson_max_iter,
                    0.0,
                    local_dense_enabled,
                    complementary_operator_families,
                    py::int_(bond),
                    comp_payload,
                    complementary_split_stats,
                    comp_family_env,
                    py::none(),
                    matvec_options,
                    true,
                    site_factors,
                    bond,
                    true,
                    flat_guess_cache,
                    bond,
                    false,
                    true,
                    "",
                    native_merge_enabled,
                    boundary_stack_access,
                    site_chain_key
                );
                ++local_records;
            }

            const std::string step_key =
                "owner-typed-bond-step:" + owner_id + ":" + direction + ":" +
                step_direction + ":" + std::to_string(bond) + ":" +
                std::to_string(should_move ? 1 : 0);
            if (owner_typed_bond_step_records.find(step_key) ==
                owner_typed_bond_step_records.end()) {
                py::object env_record = py::none();
                if (
                    should_move &&
                    !environment_record_provider.is_none() &&
                    PyCallable_Check(environment_record_provider.ptr())
                ) {
                    env_record = environment_record_provider(
                        py::str(step_direction),
                        py::int_(bond)
                    );
                }
                py::object env_moving = py::none();
                std::string env_direction;
                py::object update_rows = py::none();
                py::object pop_rows = py::none();
                py::object update_records = py::none();
                py::object pop_records = py::none();
                if (!env_record.is_none()) {
                    py::dict env = env_record.cast<py::dict>();
                    env_moving = moving_environment;
                    if (env.contains(py::str("environment_direction"))) {
                        env_direction = py::cast<std::string>(
                            env[py::str("environment_direction")]
                        );
                    }
                    if (env.contains(py::str("update_rows"))) {
                        update_rows = py::reinterpret_borrow<py::object>(
                            env[py::str("update_rows")]
                        );
                    }
                    if (env.contains(py::str("pop_rows"))) {
                        pop_rows = py::reinterpret_borrow<py::object>(
                            env[py::str("pop_rows")]
                        );
                    }
                    if (env.contains(py::str("update_records"))) {
                        update_records = py::reinterpret_borrow<py::object>(
                            env[py::str("update_records")]
                        );
                    }
                    if (env.contains(py::str("pop_records"))) {
                        pop_records = py::reinterpret_borrow<py::object>(
                            env[py::str("pop_records")]
                        );
                    }
                }
                install_owner_typed_bond_step(
                    step_key,
                    bridge,
                    bond,
                    direction,
                    step_direction,
                    clear_side,
                    should_move,
                    "",
                    "",
                    "",
                    py::none(),
                    owner_local_key,
                    env_moving,
                    env_direction,
                    update_rows,
                    pop_rows,
                    update_records,
                    pop_records
                );
                ++step_records;
            }
            step_pairs.emplace_back(static_cast<ssize_t>(bond), step_key);
        }

        py::list step_key_rows;
        for (const auto& pair : step_pairs) {
            step_key_rows.append(py::make_tuple(py::int_(pair.first), py::str(pair.second)));
        }
        install_owner_typed_half_sweep_plan(
            plan_key,
            direction,
            step_key_rows,
            step_direction
        );
        ++owner_typed_half_sweep_template_plan_installs;
        owner_typed_half_sweep_template_plan_bonds += static_cast<long long>(n);
        owner_typed_half_sweep_template_local_records += local_records;
        owner_typed_half_sweep_template_step_records += step_records;
        owner_typed_half_sweep_plan_last_error.clear();

        py::dict out;
        out["backend"] = py::str("cpp_owner_typed_half_sweep_template_plan_installer");
        out["plan_key"] = py::str(plan_key);
        out["bonds"] = py::int_(n);
        out["local_records"] = py::int_(local_records);
        out["step_records"] = py::int_(step_records);
        out["installs"] = py::int_(local_records + step_records + 1);
        return out;
    }

    void install_owner_sweep_schedule_plan(
        const std::string& key,
        py::sequence schedule_entries
    ) {
        OwnerSweepSchedulePlanRecord record;
        const ssize_t n = static_cast<ssize_t>(py::len(schedule_entries));
        record.entries.reserve(static_cast<size_t>(std::max<ssize_t>(0, n)));
        for (ssize_t idx = 0; idx < n; ++idx) {
            py::object item = py::reinterpret_borrow<py::object>(
                schedule_entries[idx]
            );
            py::tuple row = tuple_from_sequence_object(item).cast<py::tuple>();
            if (py::len(row) != 3 && py::len(row) != 4) {
                owner_sweep_schedule_plan_last_error =
                    "owner sweep-schedule entries must be (sweep, direction, plan_key[, noise])";
                throw std::runtime_error(owner_sweep_schedule_plan_last_error);
            }
            OwnerSweepScheduleEntry entry;
            entry.sweep_index = py::cast<ssize_t>(row[0]);
            entry.direction = py::cast<std::string>(row[1]);
            entry.half_sweep_plan_key = py::cast<std::string>(row[2]);
            if (py::len(row) == 4) {
                entry.noise = real_scalar(
                    py::reinterpret_borrow<py::object>(row[3])
                );
            }
            record.entries.push_back(std::move(entry));
        }
        auto it = owner_sweep_schedule_plan_records.find(key);
        if (it == owner_sweep_schedule_plan_records.end()) {
            owner_sweep_schedule_plan_records.emplace(key, std::move(record));
        } else {
            ++owner_sweep_schedule_plan_replacements;
            it->second = std::move(record);
        }
        ++owner_sweep_schedule_plan_installs;
        owner_sweep_schedule_plan_last_error.clear();
    }

    void install_owner_alternating_sweep_schedule_plan(
        const std::string& key,
        const std::string& lr_half_sweep_plan_key,
        const std::string& rl_half_sweep_plan_key,
        ssize_t requested_halves,
        py::object noise_values = py::none()
    ) {
        if (requested_halves < 0) {
            owner_sweep_schedule_plan_last_error =
                "owner alternating sweep-schedule half count must be non-negative";
            throw std::runtime_error(owner_sweep_schedule_plan_last_error);
        }
        if (
            requested_halves > 0 &&
            owner_typed_half_sweep_plan_records.find(lr_half_sweep_plan_key) ==
                owner_typed_half_sweep_plan_records.end()
        ) {
            owner_sweep_schedule_plan_last_error =
                "owner alternating sweep-schedule LR half-sweep plan is absent";
            throw std::runtime_error(owner_sweep_schedule_plan_last_error);
        }
        if (
            requested_halves > 1 &&
            owner_typed_half_sweep_plan_records.find(rl_half_sweep_plan_key) ==
                owner_typed_half_sweep_plan_records.end()
        ) {
            owner_sweep_schedule_plan_last_error =
                "owner alternating sweep-schedule RL half-sweep plan is absent";
            throw std::runtime_error(owner_sweep_schedule_plan_last_error);
        }

        OwnerSweepSchedulePlanRecord record;
        record.entries.reserve(
            static_cast<size_t>(std::max<ssize_t>(0, requested_halves))
        );
        py::sequence noise_sequence;
        ssize_t n_noise = 0;
        if (!noise_values.is_none()) {
            noise_sequence = noise_values.cast<py::sequence>();
            n_noise = static_cast<ssize_t>(py::len(noise_sequence));
        }
        for (ssize_t half = 0; half < requested_halves; ++half) {
            OwnerSweepScheduleEntry entry;
            entry.sweep_index = half;
            if ((half % 2) == 0) {
                entry.direction = "lr";
                entry.half_sweep_plan_key = lr_half_sweep_plan_key;
            } else {
                entry.direction = "rl";
                entry.half_sweep_plan_key = rl_half_sweep_plan_key;
            }
            if (half < n_noise) {
                entry.noise = real_scalar(
                    py::reinterpret_borrow<py::object>(noise_sequence[half])
                );
            }
            record.entries.push_back(std::move(entry));
        }

        auto it = owner_sweep_schedule_plan_records.find(key);
        if (it == owner_sweep_schedule_plan_records.end()) {
            owner_sweep_schedule_plan_records.emplace(key, std::move(record));
        } else {
            ++owner_sweep_schedule_plan_replacements;
            it->second = std::move(record);
        }
        ++owner_sweep_schedule_plan_installs;
        ++owner_sweep_schedule_plan_alternating_installs;
        owner_sweep_schedule_plan_alternating_expanded_halves +=
            static_cast<long long>(requested_halves);
        owner_sweep_schedule_plan_last_error.clear();
    }

    void set_owner_sweep_schedule_final_recenter(
        const std::string& key,
        const std::string& recenter_left_half_sweep_plan_key,
        const std::string& recenter_right_half_sweep_plan_key,
        ssize_t center_i,
        ssize_t sweep_index
    ) {
        auto it = owner_sweep_schedule_plan_records.find(key);
        if (it == owner_sweep_schedule_plan_records.end()) {
            owner_sweep_schedule_plan_last_error =
                "owner sweep-schedule final recenter plan is absent";
            throw std::runtime_error(owner_sweep_schedule_plan_last_error);
        }
        if (
            !recenter_left_half_sweep_plan_key.empty() &&
            owner_typed_half_sweep_plan_records.find(
                recenter_left_half_sweep_plan_key
            ) == owner_typed_half_sweep_plan_records.end()
        ) {
            owner_sweep_schedule_plan_last_error =
                "owner sweep-schedule final recenter-left plan is absent";
            throw std::runtime_error(owner_sweep_schedule_plan_last_error);
        }
        if (
            !recenter_right_half_sweep_plan_key.empty() &&
            owner_typed_half_sweep_plan_records.find(
                recenter_right_half_sweep_plan_key
            ) == owner_typed_half_sweep_plan_records.end()
        ) {
            owner_sweep_schedule_plan_last_error =
                "owner sweep-schedule final recenter-right plan is absent";
            throw std::runtime_error(owner_sweep_schedule_plan_last_error);
        }
        it->second.final_recenter_enabled =
            !recenter_left_half_sweep_plan_key.empty() ||
            !recenter_right_half_sweep_plan_key.empty();
        it->second.final_recenter_center = center_i;
        it->second.final_recenter_sweep_index = sweep_index;
        it->second.final_recenter_left_plan_key =
            recenter_left_half_sweep_plan_key;
        it->second.final_recenter_right_plan_key =
            recenter_right_half_sweep_plan_key;
        ++owner_sweep_schedule_plan_final_recenter_configures;
        owner_sweep_schedule_plan_last_error.clear();
    }

    void clear_owner_sweep_schedule_plans() {
        owner_sweep_schedule_plan_records.clear();
    }

    static void dict_increment(py::dict stats, const char* key, long long delta = 1) {
        py::str py_key(key);
        long long value = 0;
        if (stats.contains(py_key)) {
            value = py::cast<long long>(stats[py_key]);
        }
        stats[py_key] = py::int_(value + delta);
    }

    static void dict_add_seconds(py::dict stats, const char* key, double value) {
        py::str py_key(key);
        double current = 0.0;
        if (stats.contains(py_key)) {
            current = py::cast<double>(stats[py_key]);
        }
        stats[py_key] = py::float_(current + value);
    }

    static double real_scalar(py::object value) {
        try {
            return py::cast<double>(value);
        } catch (...) {
            PyErr_Clear();
        }
        try {
            cdouble z = py::cast<cdouble>(value);
            return z.real();
        } catch (...) {
            PyErr_Clear();
        }
        try {
            py::object np = py::module_::import("numpy");
            py::object flat = np.attr("asarray")(value).attr("reshape")(py::int_(-1));
            py::object item = flat.attr("__getitem__")(py::int_(0));
            return py::cast<double>(np.attr("real")(item));
        } catch (...) {
            PyErr_Clear();
        }
        return std::numeric_limits<double>::quiet_NaN();
    }

    static bool truthy_attr(py::object obj, const char* name, bool fallback = false) {
        try {
            py::object value = py::getattr(obj, name, py::bool_(fallback));
            return PyObject_IsTrue(value.ptr()) == 1;
        } catch (...) {
            return fallback;
        }
    }

    void install_owner_local_optimize(
        const std::string& key,
        py::object moving_environment,
        py::object merge_fn,
        py::object flat_guess_predicate,
        py::object flat_guess_cls,
        py::object block_tensor_cls,
        py::object A,
        py::object B,
        py::object W1,
        py::object W2,
        py::object E,
        py::object F,
        py::object m_max,
        const std::string& direction,
        py::object init_vecs = py::none(),
        double davidson_tol = 1.0e-5,
        int davidson_max_iter = 30,
        double noise = 0.0,
        bool local_dense_enabled = false,
        py::object complementary_operator_families = py::none(),
        py::object bond = py::none(),
        py::object complementary_boundary_payloads = py::none(),
        py::object complementary_split_stats = py::none(),
        py::object complementary_family_environments = py::none(),
        py::object complementary_direct_family_environments = py::none(),
        py::object matvec_options = py::none(),
        bool native_site_storage = true,
        py::object site_factors = py::none(),
        int site_index = -1,
        bool commit_site_factors = false,
        py::object flat_guess_cache = py::none(),
        int flat_guess_cache_index = -1,
        bool invalidate_direct_family_caches = false,
        bool owner_grouped_solve_update = false,
        const std::string& direct_family_payload_key = "",
        bool native_merge_enabled = false,
        bool boundary_stack_access = false,
        const std::string& site_chain_key = ""
    ) {
        OwnerLocalOptimizeRecord record;
        record.moving_environment = moving_environment;
        record.merge_fn = merge_fn;
        record.flat_guess_predicate = flat_guess_predicate;
        record.flat_guess_cls = flat_guess_cls;
        record.block_tensor_cls = block_tensor_cls;
        record.A = A;
        record.B = B;
        record.W1 = W1;
        record.W2 = W2;
        record.E = E;
        record.F = F;
        record.m_max = m_max;
        record.direction = direction;
        record.init_vecs = init_vecs;
        record.davidson_tol = davidson_tol;
        record.davidson_max_iter = davidson_max_iter;
        record.noise = noise;
        record.local_dense_enabled = local_dense_enabled;
        record.complementary_operator_families = complementary_operator_families;
        record.bond = bond;
        record.complementary_boundary_payloads = complementary_boundary_payloads;
        record.complementary_split_stats = complementary_split_stats;
        record.complementary_family_environments = complementary_family_environments;
        record.complementary_direct_family_environments =
            complementary_direct_family_environments;
        record.matvec_options = matvec_options;
        record.native_site_storage = native_site_storage;
        record.site_factors = site_factors;
        record.site_index = site_index;
        record.commit_site_factors = commit_site_factors;
        record.flat_guess_cache = flat_guess_cache;
        record.flat_guess_cache_index = flat_guess_cache_index;
        record.invalidate_direct_family_caches = invalidate_direct_family_caches;
        record.owner_grouped_solve_update = owner_grouped_solve_update;
        record.direct_family_payload_key = direct_family_payload_key;
        record.site_chain_key = site_chain_key;
        record.native_merge_enabled = native_merge_enabled;
        record.boundary_stack_access = boundary_stack_access;
        record.current_noise = noise;
        auto it = owner_local_optimize_records.find(key);
        if (it == owner_local_optimize_records.end()) {
            owner_local_optimize_records.emplace(key, std::move(record));
        } else {
            ++owner_local_optimize_record_replacements;
            it->second = std::move(record);
        }
        ++owner_local_optimize_record_installs;
    }

    void clear_owner_local_optimizes() {
        const long long cleared =
            static_cast<long long>(owner_local_optimize_records.size());
        if (cleared != 0) {
            owner_local_optimize_records.clear();
            ++owner_local_optimize_record_clears;
            owner_local_optimize_record_cleared_entries += cleared;
        }
    }

    py::object reject_owner_local_optimize(py::dict stats, const std::string& reason) {
        ++owner_local_optimize_runner_rejections;
        owner_local_optimize_runner_last_reason = reason;
        dict_increment(stats, "owner_local_optimize_rejections");
        stats["owner_local_optimize_rejected_reason"] = py::str(reason);
        stats["owner_local_optimize_backend_actual"] =
            py::str("cpp_owner_local_fallback");
        return py::none();
    }

    py::object native_owner_local_merge(
        const OwnerLocalOptimizeRecord& record,
        py::object A,
        py::object B,
        py::dict stats
    ) {
        ++owner_local_optimize_native_merge_calls;
        dict_increment(stats, "owner_local_optimize_native_merge_calls");
        try {
            py::object left_data = py::getattr(A, "data");
            py::object right_data = py::getattr(B, "data");
            py::dict sector_to_id;
            py::list id_to_sector;
            auto sector_id = [&](py::object sector) -> ssize_t {
                if (sector_to_id.contains(sector)) {
                    return py::cast<ssize_t>(sector_to_id[sector]);
                }
                const ssize_t sid = static_cast<ssize_t>(py::len(id_to_sector));
                sector_to_id[sector] = py::int_(sid);
                id_to_sector.append(sector);
                return sid;
            };
            auto pack_data = [&](py::object data_obj) -> py::dict {
                py::dict packed;
                for (py::handle item_handle : data_obj.attr("items")()) {
                    py::tuple item = py::reinterpret_borrow<py::tuple>(item_handle);
                    py::tuple key = tuple_from_sequence_object(
                        py::reinterpret_borrow<py::object>(item[0])
                    ).cast<py::tuple>();
                    py::tuple packed_key(static_cast<size_t>(py::len(key)));
                    for (ssize_t axis = 0; axis < static_cast<ssize_t>(py::len(key)); ++axis) {
                        packed_key[axis] = py::int_(
                            sector_id(py::reinterpret_borrow<py::object>(key[axis]))
                        );
                    }
                    packed[packed_key] =
                        py::reinterpret_borrow<py::object>(item[1]);
                }
                return packed;
            };
            auto decode_key = [&](py::object key_obj) -> py::tuple {
                py::tuple key = tuple_from_sequence_object(key_obj).cast<py::tuple>();
                py::tuple decoded(static_cast<size_t>(py::len(key)));
                for (ssize_t axis = 0; axis < static_cast<ssize_t>(py::len(key)); ++axis) {
                    const ssize_t sid = py::cast<ssize_t>(key[axis]);
                    decoded[axis] = id_to_sector.attr("__getitem__")(py::int_(sid));
                }
                return decoded;
            };
            py::dict packed_left = pack_data(left_data);
            py::dict packed_right = pack_data(right_data);
            py::tuple result =
                abelian_merge_adjacent_site_tensors_data_cpp(
                    packed_left,
                    packed_right
                );
            py::dict packed_data = py::reinterpret_borrow<py::dict>(result[0]);
            py::dict data;
            for (auto item : packed_data) {
                data[decode_key(py::reinterpret_borrow<py::object>(item.first))] =
                    py::reinterpret_borrow<py::object>(item.second);
            }

            py::object cls = py::getattr(A, "__class__");
            py::object aqns = py::getattr(A, "qns");
            py::object bqns = py::getattr(B, "qns");
            py::object adirs = py::getattr(A, "dirs");
            py::object bdirs = py::getattr(B, "dirs");
            py::list qns;
            qns.append(aqns.attr("__getitem__")(py::int_(0)));
            qns.append(bqns.attr("__getitem__")(py::int_(1)));
            qns.append(aqns.attr("__getitem__")(py::int_(2)));
            qns.append(bqns.attr("__getitem__")(py::int_(2)));
            py::list dirs;
            dirs.append(adirs.attr("__getitem__")(py::int_(0)));
            dirs.append(bdirs.attr("__getitem__")(py::int_(1)));
            dirs.append(adirs.attr("__getitem__")(py::int_(2)));
            dirs.append(bdirs.attr("__getitem__")(py::int_(2)));

            if (record.current_noise > 0.0 && py::len(data) > 0) {
                py::dict valid_left;
                py::dict valid_right;
                py::dict phys_dim_left;
                py::dict phys_dim_right;
                auto set_dim_max = [](py::dict dims, py::object sector, ssize_t dim) {
                    ssize_t current = 0;
                    if (dims.contains(sector)) {
                        current = py::cast<ssize_t>(dims[sector]);
                    }
                    if (dim > current) {
                        dims[sector] = py::int_(dim);
                    }
                };
                for (auto item : data) {
                    py::tuple key = tuple_from_sequence_object(
                        py::reinterpret_borrow<py::object>(item.first)
                    ).cast<py::tuple>();
                    py::array_t<cdouble, py::array::c_style | py::array::forcecast> block =
                        py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(item.second);
                    if (!block || block.ndim() != 4) {
                        throw std::runtime_error("native noisy merge block must be rank 4");
                    }
                    valid_left[py::reinterpret_borrow<py::object>(key[0])] =
                        py::int_(block.shape(0));
                    valid_right[py::reinterpret_borrow<py::object>(key[1])] =
                        py::int_(block.shape(1));
                    if (!phys_dim_left.contains(key[2])) {
                        phys_dim_left[py::reinterpret_borrow<py::object>(key[2])] =
                            py::int_(block.shape(2));
                    }
                    if (!phys_dim_right.contains(key[3])) {
                        phys_dim_right[py::reinterpret_borrow<py::object>(key[3])] =
                            py::int_(block.shape(3));
                    }
                }
                auto add_mpo_phys_dims = [&](py::object mpo_site, py::dict dims) {
                    py::object mpo_data = py::getattr(mpo_site, "data", py::none());
                    if (mpo_data.is_none()) {
                        return;
                    }
                    for (py::handle item_handle : mpo_data.attr("items")()) {
                        py::tuple item = py::reinterpret_borrow<py::tuple>(item_handle);
                        py::tuple key = tuple_from_sequence_object(
                            py::reinterpret_borrow<py::object>(item[0])
                        ).cast<py::tuple>();
                        py::array_t<cdouble, py::array::c_style | py::array::forcecast> block =
                            py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(item[1]);
                        if (!block || block.ndim() < 4 || py::len(key) < 4) {
                            continue;
                        }
                        set_dim_max(
                            dims,
                            py::reinterpret_borrow<py::object>(key[2]),
                            block.shape(2)
                        );
                        set_dim_max(
                            dims,
                            py::reinterpret_borrow<py::object>(key[3]),
                            block.shape(3)
                        );
                    }
                };
                add_mpo_phys_dims(record.W1, phys_dim_left);
                add_mpo_phys_dims(record.W2, phys_dim_right);

                py::object phys_qns_left = aqns.attr("__getitem__")(py::int_(2));
                py::object phys_qns_right = bqns.attr("__getitem__")(py::int_(2));
                std::mt19937_64 rng(
                    static_cast<std::uint64_t>(
                        std::chrono::high_resolution_clock::now()
                            .time_since_epoch()
                            .count()
                    ) ^
                    static_cast<std::uint64_t>(reinterpret_cast<std::uintptr_t>(this))
                );
                std::uniform_real_distribution<double> dist(
                    -0.5 * record.current_noise,
                    0.5 * record.current_noise
                );
                long long injected_blocks = 0;
                for (auto left_item : valid_left) {
                    py::object ql = py::reinterpret_borrow<py::object>(left_item.first);
                    const ssize_t dl = py::cast<ssize_t>(left_item.second);
                    for (py::handle qp1_handle : phys_qns_left) {
                        py::object qp1 = py::reinterpret_borrow<py::object>(qp1_handle);
                        for (py::handle qp2_handle : phys_qns_right) {
                            py::object qp2 = py::reinterpret_borrow<py::object>(qp2_handle);
                            PyObject* partial_ptr = PyNumber_Add(ql.ptr(), qp1.ptr());
                            if (partial_ptr == nullptr) {
                                throw py::error_already_set();
                            }
                            py::object partial = py::reinterpret_steal<py::object>(partial_ptr);
                            PyObject* target_ptr = PyNumber_Add(partial.ptr(), qp2.ptr());
                            if (target_ptr == nullptr) {
                                throw py::error_already_set();
                            }
                            py::object qr = py::reinterpret_steal<py::object>(target_ptr);
                            if (!valid_right.contains(qr)) {
                                continue;
                            }
                            py::tuple key(4);
                            key[0] = ql;
                            key[1] = qr;
                            key[2] = qp1;
                            key[3] = qp2;
                            if (data.contains(key)) {
                                continue;
                            }
                            const ssize_t dr = py::cast<ssize_t>(valid_right[qr]);
                            const ssize_t dp1 = phys_dim_left.contains(qp1)
                                ? py::cast<ssize_t>(phys_dim_left[qp1])
                                : 1;
                            const ssize_t dp2 = phys_dim_right.contains(qp2)
                                ? py::cast<ssize_t>(phys_dim_right[qp2])
                                : 1;
                            py::array_t<cdouble> noise_block({dl, dr, dp1, dp2});
                            auto noise_view = noise_block.mutable_unchecked<4>();
                            for (ssize_t i0 = 0; i0 < dl; ++i0) {
                                for (ssize_t i1 = 0; i1 < dr; ++i1) {
                                    for (ssize_t i2 = 0; i2 < dp1; ++i2) {
                                        for (ssize_t i3 = 0; i3 < dp2; ++i3) {
                                            noise_view(i0, i1, i2, i3) =
                                                cdouble(dist(rng), dist(rng));
                                        }
                                    }
                                }
                            }
                            data[key] = noise_block;
                            ++injected_blocks;
                        }
                    }
                }
                if (injected_blocks > 0) {
                    ++owner_local_optimize_native_noise_injections;
                    owner_local_optimize_native_noise_blocks += injected_blocks;
                    dict_increment(stats, "owner_local_optimize_native_noise_injections");
                    dict_increment(
                        stats,
                        "owner_local_optimize_native_noise_blocks",
                        injected_blocks
                    );
                }
            }

            const double norm_value = abelian_block_data_norm_cpp(data);
            py::object norm = py::float_(norm_value);
            if (norm_value > 0.0) {
                data = abelian_scale_block_data_cpp(
                    data,
                    cdouble(1.0 / norm_value, 0.0)
                );
            }
            py::list layout_items;
            std::vector<py::array_t<cdouble, py::array::c_style | py::array::forcecast>> blocks;
            blocks.reserve(static_cast<size_t>(py::len(data)));
            ssize_t total = 0;
            for (auto item : data) {
                py::array_t<cdouble, py::array::c_style | py::array::forcecast> block =
                    py::array_t<cdouble, py::array::c_style | py::array::forcecast>::ensure(item.second);
                if (!block) {
                    throw std::runtime_error("native merged data block is not array-like");
                }
                py::tuple shape(static_cast<size_t>(block.ndim()));
                ssize_t n = 1;
                for (ssize_t axis = 0; axis < block.ndim(); ++axis) {
                    shape[axis] = py::int_(block.shape(axis));
                    n *= block.shape(axis);
                }
                layout_items.append(
                    py::make_tuple(
                        py::reinterpret_borrow<py::object>(item.first),
                        shape
                    )
                );
                total += n;
                blocks.push_back(block);
            }
            py::array_t<cdouble> flat({total});
            auto flat_view = flat.mutable_unchecked<1>();
            ssize_t pos = 0;
            for (auto& block : blocks) {
                auto info = block.request();
                const cdouble* ptr = static_cast<const cdouble*>(info.ptr);
                const ssize_t n = static_cast<ssize_t>(info.size);
                for (ssize_t idx = 0; idx < n; ++idx) {
                    flat_view(pos + idx) = ptr[idx];
                }
                pos += n;
            }
            py::tuple layout = tuple_from_sequence_object(layout_items).cast<py::tuple>();
            py::object proto = cls(
                data,
                qns,
                dirs,
                py::arg("copy") = false
            );
            ++owner_local_optimize_native_merge_accepted;
            dict_increment(stats, "owner_local_optimize_native_merge_accepts");
            stats["owner_local_optimize_merge_actual"] =
                py::str(
                    record.current_noise > 0.0
                        ? "cpp_native_noisy_merge_normalize_flatten"
                        : "cpp_native_merge_normalize_flatten"
                );
            return py::make_tuple(proto, norm, flat, layout);
        } catch (...) {
            PyErr_Clear();
            ++owner_local_optimize_native_merge_failures;
            dict_increment(stats, "owner_local_optimize_native_merge_failures");
            return py::none();
        }
    }

    static ssize_t flat_layout_dim(py::object layout) {
        py::sequence rows = layout.cast<py::sequence>();
        ssize_t total = 0;
        for (ssize_t row = 0; row < static_cast<ssize_t>(py::len(rows)); ++row) {
            py::tuple item = tuple_from_sequence_object(
                py::reinterpret_borrow<py::object>(rows[row])
            ).cast<py::tuple>();
            if (py::len(item) < 2) {
                throw std::runtime_error("flat layout rows must be (key, shape)");
            }
            py::tuple shape = tuple_from_sequence_object(
                py::reinterpret_borrow<py::object>(item[1])
            ).cast<py::tuple>();
            ssize_t block = 1;
            for (ssize_t axis = 0; axis < static_cast<ssize_t>(py::len(shape)); ++axis) {
                const ssize_t dim = py::cast<ssize_t>(shape[axis]);
                if (dim < 0) {
                    throw std::runtime_error("flat layout dimensions must be nonnegative");
                }
                block *= dim;
            }
            total += block;
        }
        return total;
    }

    py::object refresh_owner_grouped_table_from_descriptor_cpp(
        const OwnerLocalOptimizeRecord& record,
        py::dict stats,
        py::object H_op,
        py::object layout,
        py::object table_hint
    ) {
        dict_increment(stats, "owner_local_grouped_cpp_table_refresh_attempts");
        const double start = wall_seconds();
        try {
            const std::string table_key =
                grouped_table_key_from_bond_hint(table_hint);
            const ssize_t dim = flat_layout_dim(layout);
            if (dim <= 0) {
                stats["owner_local_grouped_cpp_table_refresh_last_reason"] =
                    py::str("empty_layout");
                return py::none();
            }
            const double sparse_density_threshold = py::cast<double>(
                py::getattr(
                    H_op,
                    "_renormalized_operator_table_sparse_density_threshold",
                    py::float_(0.0)
                )
            );
            if (!record.direct_family_payload_key.empty()) {
                if (direct_family_payload_records.find(record.direct_family_payload_key)
                    == direct_family_payload_records.end()) {
                    stats["owner_local_grouped_cpp_table_refresh_last_reason"] =
                        py::str("direct_family_payload_not_installed");
                    return py::none();
                }
                const std::string route_plan_key =
                    std::string("direct-family-route-plan|") + table_key;
                py::dict info =
                    refresh_grouped_table_record_from_direct_family_route_plan(
                        table_key,
                        record.direct_family_payload_key,
                        route_plan_key,
                        layout,
                        dim,
                        sparse_density_threshold
                    );
                const double elapsed = wall_seconds() - start;
                dict_increment(stats, "owner_local_grouped_cpp_table_refresh_accepts");
                dict_add_seconds(
                    stats,
                    "owner_local_grouped_cpp_table_refresh_seconds",
                    elapsed
                );
                stats["owner_local_grouped_cpp_table_refresh_last_seconds"] =
                    py::float_(elapsed);
                stats["owner_local_grouped_cpp_table_refresh_backend_actual"] =
                    py::str("cpp_direct_family_route_plan_table_record");
                stats["owner_local_grouped_cpp_table_refresh_last_table_key"] =
                    py::str(table_key);
                stats["owner_local_grouped_cpp_table_refresh_last_reason"] = py::none();
                const double table_seconds = py::cast<double>(
                    info[py::str("table_seconds")]
                );
                const double total_seconds = py::cast<double>(
                    info[py::str("seconds")]
                );
                stats["cpp_named_raw_payload_plan_backend_actual"] =
                    py::str("cpp_direct_family_route_plan_owner_table_refresh");
                dict_increment(stats, "cpp_direct_family_payload_table_refreshes");
                dict_increment(stats, "cpp_direct_family_route_plan_table_refreshes");
                dict_add_seconds(
                    stats,
                    "cpp_direct_family_payload_table_refresh_seconds",
                    total_seconds
                );
                dict_add_seconds(
                    stats,
                    "cpp_direct_family_route_plan_table_refresh_seconds",
                    total_seconds
                );
                stats["cpp_direct_family_payload_table_refresh_last_seconds"] =
                    py::float_(total_seconds);
                stats["cpp_direct_family_route_plan_table_refresh_last_seconds"] =
                    py::float_(total_seconds);
                if (info.contains(py::str("plan_key"))) {
                    stats["cpp_direct_family_route_plan_last_key"] =
                        py::reinterpret_borrow<py::object>(info[py::str("plan_key")]);
                }
                if (info.contains(py::str("plan_stats"))) {
                    py::dict plan_stats = py::reinterpret_borrow<py::dict>(
                        info[py::str("plan_stats")]
                    );
                    for (auto item : plan_stats) {
                        const std::string key = py::str(item.first).cast<std::string>();
                        stats[py::str("cpp_direct_family_route_plan_last_" + key)] =
                            py::reinterpret_borrow<py::object>(item.second);
                    }
                }
                dict_increment(stats, "cpp_grouped_renormalized_table_refreshes");
                dict_add_seconds(
                    stats,
                    "cpp_grouped_renormalized_table_refresh_seconds",
                    table_seconds
                );
                dict_increment(stats, "cpp_grouped_renormalized_table_slot_reuses");
                dict_increment(stats, "cpp_grouped_renormalized_table_bond_slot_reuses");
                stats["cpp_grouped_renormalized_table_last_storage"] =
                    py::reinterpret_borrow<py::object>(info[py::str("storage")]);
                stats["cpp_grouped_renormalized_table_last_blocks"] =
                    py::reinterpret_borrow<py::object>(info[py::str("blocks")]);
                stats["cpp_grouped_renormalized_table_last_elements"] =
                    py::reinterpret_borrow<py::object>(
                        info[py::str("block_matrix_elements")]
                    );
                stats["cpp_grouped_renormalized_table_last_sparse_nnz"] =
                    py::reinterpret_borrow<py::object>(
                        info[py::str("block_sparse_nnz")]
                    );
                stats["cpp_grouped_renormalized_table_last_refresh_kind"] =
                    py::reinterpret_borrow<py::object>(info[py::str("refresh_kind")]);
                const std::string refresh_kind = py::str(
                    info[py::str("refresh_kind")]
                ).cast<std::string>();
                const bool created_table = (
                    info.contains(py::str("created_table"))
                    && py::cast<bool>(info[py::str("created_table")])
                );
                if (
                    refresh_kind == "dense_in_place"
                    || refresh_kind == "raw_dense_in_place"
                    || refresh_kind == "raw_dense_schedule_in_place"
                    || refresh_kind == "direct_route_plan_table_in_place"
                    || refresh_kind == "factorized_refresh"
                ) {
                    dict_increment(
                        stats,
                        "cpp_grouped_renormalized_table_fast_refreshes"
                    );
                } else if (created_table) {
                    dict_increment(
                        stats,
                        "cpp_grouped_renormalized_table_initial_build_refreshes"
                    );
                } else if (
                    refresh_kind == "dense_rebuild_in_place"
                    || refresh_kind == "raw_dense_rebuild_in_place"
                ) {
                    dict_increment(
                        stats,
                        "cpp_grouped_renormalized_table_rebuild_in_place_refreshes"
                    );
                } else {
                    dict_increment(
                        stats,
                        "cpp_grouped_renormalized_table_rebuild_refreshes"
                    );
                }
                stats["owner_local_grouped_cpp_table_refresh_last_reason"] =
                    py::none();
                for (const char* key : {
                         "raw_schedule_hits",
                         "raw_schedule_misses",
                         "raw_schedule_stores",
                         "direct_table_schedule_hits",
                         "direct_table_schedule_misses",
                         "direct_table_schedule_stores",
                     }) {
                    if (info.contains(py::str(key))) {
                        std::string stat_key =
                            std::string("cpp_grouped_renormalized_table_") + key;
                        stats[py::str(stat_key)] =
                            py::reinterpret_borrow<py::object>(info[py::str(key)]);
                    }
                }
                return info;
            }
            if (
                !record.complementary_direct_family_environments.is_none() &&
                PyObject_IsTrue(record.complementary_direct_family_environments.ptr()) == 1
            ) {
                stats["owner_local_grouped_cpp_table_refresh_last_reason"] =
                    py::str("missing_direct_family_payload_key");
                return py::none();
            }
            py::object descriptor_obj = py::getattr(
                record.moving_environment,
                "_cpp_family_mpo_descriptor_key",
                py::none()
            );
            if (descriptor_obj.is_none()) {
                stats["owner_local_grouped_cpp_table_refresh_last_reason"] =
                    py::str("missing_descriptor_key");
                return py::none();
            }
            const std::string descriptor_key =
                py::cast<std::string>(descriptor_obj);
            if (family_mpo_descriptor_records.find(descriptor_key)
                == family_mpo_descriptor_records.end()) {
                stats["owner_local_grouped_cpp_table_refresh_last_reason"] =
                    py::str("descriptor_not_installed");
                return py::none();
            }
            const ssize_t bond = py::cast<ssize_t>(record.bond);
            const std::string plan_key =
                descriptor_key + "|" + table_key;
            py::dict info = refresh_grouped_table_record_from_family_mpo_descriptor(
                table_key,
                plan_key,
                descriptor_key,
                bond,
                layout,
                dim,
                sparse_density_threshold
            );
            const double elapsed = wall_seconds() - start;
            dict_increment(stats, "owner_local_grouped_cpp_table_refresh_accepts");
            dict_add_seconds(
                stats,
                "owner_local_grouped_cpp_table_refresh_seconds",
                elapsed
            );
            stats["owner_local_grouped_cpp_table_refresh_last_seconds"] =
                py::float_(elapsed);
            stats["owner_local_grouped_cpp_table_refresh_backend_actual"] =
                py::str("cpp_family_mpo_descriptor_table_record");
            stats["owner_local_grouped_cpp_table_refresh_last_table_key"] =
                py::str(table_key);
            stats["owner_local_grouped_cpp_table_refresh_last_reason"] = py::none();
            const double payload_seconds = py::cast<double>(
                info[py::str("payload_seconds")]
            );
            const double table_seconds = py::cast<double>(
                info[py::str("table_seconds")]
            );
            const double total_seconds = py::cast<double>(
                info[py::str("seconds")]
            );
            dict_increment(stats, "cpp_named_raw_payload_plan_refresh_calls");
            dict_add_seconds(
                stats,
                "cpp_named_raw_payload_plan_refresh_seconds",
                payload_seconds
            );
            stats["cpp_named_raw_payload_plan_last_refresh_seconds"] =
                py::float_(payload_seconds);
            stats["cpp_named_raw_payload_plan_backend_actual"] =
                py::str("cpp_family_mpo_descriptor_owner_table_refresh");
            dict_increment(stats, "cpp_named_raw_payload_plan_fused_table_refreshes");
            dict_add_seconds(
                stats,
                "cpp_named_raw_payload_plan_fused_table_seconds",
                total_seconds
            );
            stats["cpp_named_raw_payload_plan_fused_table_last_seconds"] =
                py::float_(total_seconds);
            py::dict plan_stats = py::reinterpret_borrow<py::dict>(
                info[py::str("plan_stats")]
            );
            for (auto item : plan_stats) {
                const std::string key = py::str(item.first).cast<std::string>();
                stats[py::str("cpp_named_raw_payload_plan_last_" + key)] =
                    py::reinterpret_borrow<py::object>(item.second);
            }
            dict_increment(stats, "renormalized_operator_payload_collect_calls");
            dict_add_seconds(
                stats,
                "renormalized_operator_payload_collect_seconds",
                payload_seconds
            );
            stats["renormalized_operator_payload_collect_last_seconds"] =
                py::float_(payload_seconds);
            dict_increment(stats, "cpp_grouped_renormalized_table_refreshes");
            dict_add_seconds(
                stats,
                "cpp_grouped_renormalized_table_refresh_seconds",
                table_seconds
            );
            dict_increment(stats, "cpp_grouped_renormalized_table_slot_reuses");
            dict_increment(stats, "cpp_grouped_renormalized_table_bond_slot_reuses");
            stats["cpp_grouped_renormalized_table_last_storage"] =
                py::reinterpret_borrow<py::object>(info[py::str("storage")]);
            stats["cpp_grouped_renormalized_table_last_blocks"] =
                py::reinterpret_borrow<py::object>(info[py::str("blocks")]);
            stats["cpp_grouped_renormalized_table_last_elements"] =
                py::reinterpret_borrow<py::object>(
                    info[py::str("block_matrix_elements")]
                );
            stats["cpp_grouped_renormalized_table_last_sparse_nnz"] =
                py::reinterpret_borrow<py::object>(
                    info[py::str("block_sparse_nnz")]
                );
            stats["cpp_grouped_renormalized_table_last_refresh_kind"] =
                py::reinterpret_borrow<py::object>(info[py::str("refresh_kind")]);
            const std::string refresh_kind = py::str(
                info[py::str("refresh_kind")]
            ).cast<std::string>();
            const bool created_table = (
                info.contains(py::str("created_table"))
                && py::cast<bool>(info[py::str("created_table")])
            );
            if (
                refresh_kind == "dense_in_place"
                || refresh_kind == "raw_dense_in_place"
                || refresh_kind == "raw_dense_schedule_in_place"
                || refresh_kind == "direct_route_plan_table_in_place"
                || refresh_kind == "factorized_refresh"
            ) {
                dict_increment(
                    stats,
                    "cpp_grouped_renormalized_table_fast_refreshes"
                );
            } else if (
                created_table
                && (
                    refresh_kind == "dense_rebuild_in_place"
                    || refresh_kind == "raw_dense_rebuild_in_place"
                    || refresh_kind == "raw_rebuild"
                    || refresh_kind == "build"
                )
            ) {
                dict_increment(
                    stats,
                    "cpp_grouped_renormalized_table_initial_build_refreshes"
                );
            } else if (
                refresh_kind == "dense_rebuild_in_place"
                || refresh_kind == "raw_dense_rebuild_in_place"
            ) {
                dict_increment(
                    stats,
                    "cpp_grouped_renormalized_table_rebuild_in_place_refreshes"
                );
            } else {
                dict_increment(
                    stats,
                    "cpp_grouped_renormalized_table_rebuild_refreshes"
                );
            }
            for (const char* key : {
                     "raw_schedule_hits",
                     "raw_schedule_misses",
                     "raw_schedule_stores",
                     "direct_table_schedule_hits",
                     "direct_table_schedule_misses",
                     "direct_table_schedule_stores",
                 }) {
                if (info.contains(py::str(key))) {
                    std::string stat_key =
                        std::string("cpp_grouped_renormalized_table_") + key;
                    stats[py::str(stat_key)] =
                        py::reinterpret_borrow<py::object>(info[py::str(key)]);
                }
            }
            return info;
        } catch (const py::error_already_set& exc) {
            dict_increment(stats, "owner_local_grouped_cpp_table_refresh_failures");
            stats["owner_local_grouped_cpp_table_refresh_last_error"] =
                py::str(exc.what());
            PyErr_Clear();
            return py::none();
        } catch (const std::exception& exc) {
            dict_increment(stats, "owner_local_grouped_cpp_table_refresh_failures");
            stats["owner_local_grouped_cpp_table_refresh_last_error"] =
                py::str(exc.what());
            return py::none();
        }
    }

    py::object prepare_owner_grouped_update_cpp(
        const OwnerLocalOptimizeRecord& record,
        py::dict stats,
        py::object H_op,
        py::object proto,
        py::object layout
    ) {
        dict_increment(stats, "owner_local_grouped_cpp_prepare_calls");
        try {
            if (
                PyObject_IsTrue(
                    py::getattr(
                        H_op,
                        "_moving_environment_cpp_davidson",
                        py::bool_(false)
                    ).ptr()
                ) != 1
            ) {
                return py::none();
            }
            if (record.block_tensor_cls.is_none()) {
                return py::none();
            }
            py::object table_hint = record.bond;
            py::object direct_table_hint =
                grouped_table_hint_from_layout(record.bond, layout);
            py::object direct_refresh =
                refresh_owner_grouped_table_from_descriptor_cpp(
                    record,
                    stats,
                    H_op,
                    layout,
                    direct_table_hint
                );
            if (direct_refresh.is_none()) {
                py::object compile_fn = py::getattr(
                    record.moving_environment,
                    "compiled_flat_matvec",
                    py::none()
                );
                if (compile_fn.is_none() || !PyCallable_Check(compile_fn.ptr())) {
                    return py::none();
                }
                py::object compiled = compile_fn(H_op, proto, layout);
                if (compiled.is_none()) {
                    return py::none();
                }
                dict_increment(
                    stats,
                    "owner_local_grouped_cpp_table_refresh_fallbacks"
                );
                stats["owner_local_grouped_cpp_table_refresh_fallback_actual"] =
                    py::str("python_compiled_flat_matvec");
            } else {
                stats["owner_local_grouped_cpp_table_refresh_fallback_actual"] =
                    py::str("none");
                table_hint = direct_table_hint;
            }
            py::dict sector_to_id;
            py::dict id_to_sector;
            auto sector_id = [&](py::object sector) -> ssize_t {
                if (sector_to_id.contains(sector)) {
                    return py::cast<ssize_t>(sector_to_id[sector]);
                }
                const ssize_t sid = static_cast<ssize_t>(py::len(id_to_sector));
                sector_to_id[sector] = py::int_(sid);
                id_to_sector[py::int_(sid)] = sector;
                return sid;
            };
            py::list packed_rows;
            for (py::handle item_handle : layout.cast<py::sequence>()) {
                py::tuple item = tuple_from_sequence_object(
                    py::reinterpret_borrow<py::object>(item_handle)
                ).cast<py::tuple>();
                if (py::len(item) != 2) {
                    throw std::runtime_error(
                        "MovingEnvironment grouped update layout entries must be (key, shape)"
                    );
                }
                py::tuple key = tuple_from_sequence_object(
                    py::reinterpret_borrow<py::object>(item[0])
                ).cast<py::tuple>();
                if (py::len(key) != 4) {
                    throw std::runtime_error(
                        "MovingEnvironment grouped update expects rank-4 layout keys"
                    );
                }
                py::object q0 = py::reinterpret_borrow<py::object>(key[0]);
                py::object q1 = py::reinterpret_borrow<py::object>(key[1]);
                py::object q2 = py::reinterpret_borrow<py::object>(key[2]);
                py::object q3 = py::reinterpret_borrow<py::object>(key[3]);
                PyObject* qmid_ptr = PyNumber_Add(q0.ptr(), q2.ptr());
                if (qmid_ptr == nullptr) {
                    throw py::error_already_set();
                }
                py::object qmid = py::reinterpret_steal<py::object>(qmid_ptr);
                py::tuple packed_key(5);
                packed_key[0] = py::int_(sector_id(q0));
                packed_key[1] = py::int_(sector_id(q1));
                packed_key[2] = py::int_(sector_id(q2));
                packed_key[3] = py::int_(sector_id(q3));
                packed_key[4] = py::int_(sector_id(qmid));
                py::tuple shape_src = tuple_from_sequence_object(
                    py::reinterpret_borrow<py::object>(item[1])
                ).cast<py::tuple>();
                py::tuple shape(static_cast<size_t>(py::len(shape_src)));
                for (ssize_t axis = 0; axis < static_cast<ssize_t>(py::len(shape_src)); ++axis) {
                    shape[axis] = py::int_(py::cast<ssize_t>(shape_src[axis]));
                }
                packed_rows.append(py::make_tuple(packed_key, shape));
            }
            py::sequence proto_qns = py::getattr(proto, "qns").cast<py::sequence>();
            py::sequence proto_dirs = py::getattr(proto, "dirs").cast<py::sequence>();
            py::tuple qns(static_cast<size_t>(py::len(proto_qns)));
            for (ssize_t axis = 0; axis < static_cast<ssize_t>(py::len(proto_qns)); ++axis) {
                qns[axis] = tuple_from_sequence_object(
                    py::reinterpret_borrow<py::object>(proto_qns[axis])
                );
            }
            py::tuple dirs(static_cast<size_t>(py::len(proto_dirs)));
            for (ssize_t axis = 0; axis < static_cast<ssize_t>(py::len(proto_dirs)); ++axis) {
                dirs[axis] = py::int_(py::cast<ssize_t>(proto_dirs[axis]));
            }
            dict_increment(stats, "owner_local_grouped_cpp_prepare_accepts");
            stats["owner_local_grouped_prepare_actual"] =
                py::str("cpp_owner_grouped_update_prepare");
            py::object tensor_cls = record.block_tensor_cls;
            if (record.native_site_storage) {
                tensor_cls = py::module_::import("pyqed.mps.abelian_direct")
                    .attr("AbelianSiteTensorData");
            }
            return py::make_tuple(
                tuple_from_sequence_object(packed_rows),
                qns,
                dirs,
                tensor_cls,
                id_to_sector,
                table_hint
            );
        } catch (const py::error_already_set& exc) {
            dict_increment(stats, "owner_local_grouped_cpp_prepare_failures");
            stats["owner_local_grouped_cpp_prepare_last_error"] =
                py::str(exc.what());
            PyErr_Clear();
            return py::none();
        } catch (const std::exception& exc) {
            dict_increment(stats, "owner_local_grouped_cpp_prepare_failures");
            stats["owner_local_grouped_cpp_prepare_last_error"] =
                py::str(exc.what());
            return py::none();
        }
    }

    py::object run_owner_local_grouped_solve_update(
        OwnerLocalOptimizeRecord& record,
        py::dict stats,
        py::object H_op,
        py::object proto,
        py::object flat_start,
        py::object flat_start_layout,
        int packed_max_iter
    ) {
        ++owner_local_grouped_solve_update_calls;
        dict_increment(stats, "owner_local_grouped_solve_update_calls");
        const double start = wall_seconds();
        struct OwnerGroupedSolveTimer {
            CppMovingEnvironment* owner;
            py::dict stats;
            double start;
            ~OwnerGroupedSolveTimer() {
                try {
                    const double elapsed = wall_seconds() - start;
                    owner->owner_local_grouped_solve_update_seconds += elapsed;
                    owner->owner_local_grouped_solve_update_last_seconds = elapsed;
                    CppMovingEnvironment::dict_add_seconds(
                        stats,
                        "owner_local_grouped_solve_update_seconds",
                        elapsed
                    );
                    stats["owner_local_grouped_solve_update_last_seconds"] =
                        py::float_(elapsed);
                } catch (...) {
                    PyErr_Clear();
                }
            }
        } timer{this, stats, start};
        try {
            int restart_dim = 0;
            try {
                restart_dim = py::cast<int>(
                    py::getattr(
                        H_op,
                        "_packed_local_davidson_restart_dim",
                        py::int_(0)
                    )
                );
            } catch (...) {
                PyErr_Clear();
                restart_dim = 0;
            }
            bool accept_unconverged = false;
            try {
                py::object option_value =
                    record.moving_environment.attr("_option_value")(
                        record.matvec_options,
                        py::str("moving_environment_cpp_accept_unconverged"),
                        py::bool_(false)
                    );
                accept_unconverged = PyObject_IsTrue(option_value.ptr()) == 1;
            } catch (...) {
                PyErr_Clear();
                accept_unconverged = false;
            }
            py::object update_result = py::none();
            py::object prepared_obj = prepare_owner_grouped_update_cpp(
                record,
                stats,
                H_op,
                proto,
                flat_start_layout
            );
            py::object direct_prepare = py::getattr(
                record.moving_environment,
                "prepare_owner_grouped_update",
                py::none()
            );
            if (
                !prepared_obj.is_none()
                || (!direct_prepare.is_none() && PyCallable_Check(direct_prepare.ptr()))
            ) {
                try {
                    if (prepared_obj.is_none()) {
                        prepared_obj = direct_prepare(
                            H_op,
                            proto,
                            flat_start_layout
                        );
                    }
                    if (!prepared_obj.is_none()) {
                        py::tuple prepared = prepared_obj.cast<py::tuple>();
                        if (py::len(prepared) >= 5) {
                            dict_increment(
                                stats,
                                "owner_local_grouped_direct_solve_update_calls"
                            );
                            dict_increment(stats, "cpp_solve_update_attempts");
                            py::array_t<cdouble, py::array::c_style | py::array::forcecast>
                                v0 = flat_start.cast<
                                    py::array_t<
                                        cdouble,
                                        py::array::c_style | py::array::forcecast
                                    >
                                >();
                            py::object packed_layout =
                                py::reinterpret_borrow<py::object>(prepared[0]);
                            py::object qns =
                                py::reinterpret_borrow<py::object>(prepared[1]);
                            py::object dirs =
                                py::reinterpret_borrow<py::object>(prepared[2]);
                            py::object tensor_cls =
                                py::reinterpret_borrow<py::object>(prepared[3]);
                            py::object sector_decoder =
                                py::reinterpret_borrow<py::object>(prepared[4]);
                            py::object table_hint = record.bond;
                            if (py::len(prepared) >= 6) {
                                table_hint = py::reinterpret_borrow<py::object>(
                                    prepared[5]
                                );
                            }
                            py::object pending_obj = py::getattr(
                                record.moving_environment,
                                "_pending_cpp_bond_environment_step",
                                py::none()
                            );
                            bool use_transaction = false;
                            py::dict pending;
                            if (!pending_obj.is_none()) {
                                pending = pending_obj.cast<py::dict>();
                                if (pending.contains(py::str("bond"))) {
                                    const ssize_t pending_bond = py::cast<ssize_t>(
                                        pending[py::str("bond")]
                                    );
                                    const ssize_t record_bond =
                                        py::cast<ssize_t>(record.bond);
                                    use_transaction = pending_bond == record_bond;
                                }
                            }

                            py::tuple raw_update;
                            if (use_transaction) {
                                dict_increment(
                                    stats,
                                    "cpp_bond_step_transaction_attempts"
                                );
                                dict_increment(
                                    stats,
                                    "cpp_bond_step_transaction_calls"
                                );
                                dict_increment(
                                    stats,
                                    "cpp_moving_environment_solve_update_auto_calls"
                                );
                                raw_update = bond_step_update_and_environment_auto(
                                    table_hint,
                                    v0,
                                    record.davidson_tol,
                                    packed_max_iter,
                                    restart_dim,
                                    accept_unconverged,
                                    packed_layout,
                                    qns,
                                    dirs,
                                    record.direction,
                                    tensor_cls,
                                    record.m_max,
                                    sector_decoder,
                                    py::cast<std::string>(
                                        pending[py::str("environment_direction")]
                                    ),
                                    py::reinterpret_borrow<py::sequence>(
                                        pending[py::str("update_rows")]
                                    ),
                                    py::reinterpret_borrow<py::sequence>(
                                        pending[py::str("pop_rows")]
                                    )
                                );
                                record.moving_environment.attr(
                                    "_pending_cpp_bond_environment_step"
                                ) = py::none();
                            } else {
                                dict_increment(
                                    stats,
                                    "cpp_moving_environment_solve_update_auto_calls"
                                );
                                raw_update =
                                    grouped_davidson_split_flat_two_site_update_auto(
                                        table_hint,
                                        v0,
                                        record.davidson_tol,
                                        packed_max_iter,
                                        restart_dim,
                                        accept_unconverged,
                                        packed_layout,
                                        qns,
                                        dirs,
                                        record.direction,
                                        tensor_cls,
                                        record.m_max,
                                        sector_decoder
                                    );
                            }

                            py::dict result = py::reinterpret_borrow<py::dict>(
                                raw_update[0]
                            );
                            result["table_source"] = py::str(
                                "grouped_renormalized_table_owner_direct_update"
                            );
                            const bool accepted = (
                                result.contains(py::str("accepted")) &&
                                PyObject_IsTrue(
                                    result[py::str("accepted")].ptr()
                                ) == 1 &&
                                !raw_update[1].is_none() &&
                                !raw_update[2].is_none()
                            );
                            py::object update = py::none();
                            py::object direct_left = py::none();
                            py::object direct_right = py::none();
                            py::object direct_trunc = py::none();
                            py::object direct_kept = py::none();
                            if (accepted) {
                                direct_left = py::reinterpret_borrow<py::object>(
                                    raw_update[1]
                                );
                                direct_right = py::reinterpret_borrow<py::object>(
                                    raw_update[2]
                                );
                                direct_trunc = py::reinterpret_borrow<py::object>(
                                    raw_update[5]
                                );
                                direct_kept = py::reinterpret_borrow<py::object>(
                                    raw_update[6]
                                );
                                dict_increment(
                                    stats,
                                    "owner_local_grouped_direct_solve_update_accepts"
                                );
                                dict_increment(
                                    stats,
                                    "owner_local_grouped_direct_raw_update_accepts"
                                );
                                stats[
                                    "owner_local_grouped_solve_update_backend_actual"
                                ] = py::str(
                                    "cpp_moving_environment_direct_grouped_update"
                                );
                                stats[
                                    "cpp_moving_environment_solve_update_backend"
                                ] = py::str("cpp_moving_environment_direct");
                                stats[
                                    "cpp_moving_environment_site_split_backend"
                                ] = py::str("cpp_moving_environment");
                                stats[
                                    "cpp_moving_environment_site_update_backend"
                                ] = py::str("cpp_moving_environment");
                                if (use_transaction && py::len(raw_update) >= 12) {
                                    const long long env_updates =
                                        py::cast<long long>(raw_update[8]);
                                    const long long env_pops =
                                        py::cast<long long>(raw_update[9]);
                                    const long long env_syncs =
                                        py::cast<long long>(raw_update[10]);
                                    const long long env_failures =
                                        py::cast<long long>(raw_update[11]);
                                    if (
                                        env_failures == 0 &&
                                        (env_updates > 0 || env_pops > 0)
                                    ) {
                                        py::dict info;
                                        info["sweep_direction"] =
                                            pending[py::str("sweep_direction")];
                                        info["bond"] = pending[py::str("bond")];
                                        info["updates"] = py::int_(env_updates);
                                        info["pops"] = py::int_(env_pops);
                                        info["syncs"] = py::int_(env_syncs);
                                        info["failures"] = py::int_(env_failures);
                                        info["environment_direction"] = pending[
                                            py::str("environment_direction")
                                        ];
                                        info["update_records"] = pending[
                                            py::str("update_records")
                                        ];
                                        info["pop_records"] = pending[
                                            py::str("pop_records")
                                        ];
                                        record.moving_environment.attr(
                                            "_last_cpp_bond_environment_step"
                                        ) = info;
                                        dict_increment(
                                            stats,
                                            "cpp_bond_step_transaction_accepted"
                                        );
                                        dict_increment(
                                            stats,
                                            "cpp_bond_step_transaction_environment_updates",
                                            env_updates
                                        );
                                        stats[
                                            "cpp_bond_step_transaction_backend_actual"
                                        ] = py::str("cpp_moving_environment");
                                    }
                                }
                            }
                            update_result = py::make_tuple(
                                result,
                                update,
                                direct_left,
                                direct_right,
                                direct_trunc,
                                direct_kept
                            );
                        }
                    }
                } catch (const py::error_already_set& exc) {
                    dict_increment(
                        stats,
                        "owner_local_grouped_direct_solve_update_failures"
                    );
                    stats["owner_local_grouped_direct_solve_update_last_error"] =
                        py::str(exc.what());
                    PyErr_Clear();
                    update_result = py::none();
                } catch (const std::exception& exc) {
                    dict_increment(
                        stats,
                        "owner_local_grouped_direct_solve_update_failures"
                    );
                    stats["owner_local_grouped_direct_solve_update_last_error"] =
                        py::str(exc.what());
                    update_result = py::none();
                }
            }
            if (update_result.is_none()) {
                dict_increment(
                    stats,
                    "owner_local_grouped_direct_solve_update_fallbacks"
                );
                py::object solver = py::getattr(
                    record.moving_environment,
                    "solve_cpp_davidson_update",
                    py::none()
                );
                if (solver.is_none() || !PyCallable_Check(solver.ptr())) {
                    ++owner_local_grouped_solve_update_rejections;
                    dict_increment(
                        stats,
                        "owner_local_grouped_solve_update_rejections"
                    );
                    owner_local_grouped_solve_update_last_reason =
                        "solve_cpp_davidson_update_unavailable";
                    stats["owner_local_grouped_solve_update_rejected_reason"] =
                        py::str(owner_local_grouped_solve_update_last_reason);
                    return py::none();
                }
                update_result = solver(
                    H_op,
                    proto,
                    flat_start_layout,
                    flat_start,
                    py::arg("tol") = record.davidson_tol,
                    py::arg("max_iter") = packed_max_iter,
                    py::arg("restart_dim") = restart_dim,
                    py::arg("accept_unconverged") = accept_unconverged,
                    py::arg("direction") = record.direction,
                    py::arg("m_max") = record.m_max
                );
            }
            if (update_result.is_none()) {
                ++owner_local_grouped_solve_update_rejections;
                dict_increment(stats, "owner_local_grouped_solve_update_rejections");
                owner_local_grouped_solve_update_last_reason =
                    "grouped_update_unavailable";
                stats["owner_local_grouped_solve_update_rejected_reason"] =
                    py::str(owner_local_grouped_solve_update_last_reason);
                return py::none();
            }
            py::tuple pair = update_result.cast<py::tuple>();
            if (py::len(pair) < 2) {
                ++owner_local_grouped_solve_update_rejections;
                dict_increment(stats, "owner_local_grouped_solve_update_rejections");
                owner_local_grouped_solve_update_last_reason =
                    "grouped_update_bad_result";
                stats["owner_local_grouped_solve_update_rejected_reason"] =
                    py::str(owner_local_grouped_solve_update_last_reason);
                return py::none();
            }
            py::dict result = py::reinterpret_borrow<py::object>(pair[0]).cast<py::dict>();
            py::object update = py::reinterpret_borrow<py::object>(pair[1]);
            const bool has_raw_update = (
                py::len(pair) >= 6 &&
                !py::reinterpret_borrow<py::object>(pair[2]).is_none() &&
                !py::reinterpret_borrow<py::object>(pair[3]).is_none()
            );
            const bool accepted = (
                result.contains(py::str("accepted")) &&
                PyObject_IsTrue(result[py::str("accepted")].ptr()) == 1 &&
                (!update.is_none() || has_raw_update)
            );
            if (!accepted) {
                ++owner_local_grouped_solve_update_rejections;
                dict_increment(stats, "owner_local_grouped_solve_update_rejections");
                owner_local_grouped_solve_update_last_reason =
                    "grouped_update_not_accepted";
                stats["owner_local_grouped_solve_update_rejected_reason"] =
                    py::str(owner_local_grouped_solve_update_last_reason);
                return py::none();
            }
            py::object energy = py::reinterpret_borrow<py::object>(
                result[py::str("energy")]
            );
            py::object vector = py::reinterpret_borrow<py::object>(
                result[py::str("vector")]
            );
            py::object residual = py::none();
            if (result.contains(py::str("residual_norm"))) {
                residual = py::reinterpret_borrow<py::object>(
                    result[py::str("residual_norm")]
                );
            }
            py::object converged = py::none();
            if (result.contains(py::str("converged"))) {
                converged = py::reinterpret_borrow<py::object>(
                    result[py::str("converged")]
                );
            }

            H_op.attr("last_packed_davidson_solution_update") = update;
            H_op.attr("last_packed_davidson_solution_flat") = vector;
            H_op.attr("last_packed_davidson_solution_layout") = flat_start_layout;
            H_op.attr("last_packed_davidson_solution_energy") = energy;
            H_op.attr("last_packed_davidson_solution_residual") = residual;
            H_op.attr("last_packed_davidson_solution_converged") = converged;

            py::dict profile_stats = H_op.attr("profile_stats").cast<py::dict>();
            py::dict packed_stats;
            py::object iterations = py::int_(0);
            if (result.contains(py::str("iterations"))) {
                iterations = py::reinterpret_borrow<py::object>(
                    result[py::str("iterations")]
                );
            }
            packed_stats["iterations"] = iterations;
            packed_stats["dimension"] = py::int_(py::len(vector));
            py::object basis_size = py::int_(0);
            if (result.contains(py::str("basis_size"))) {
                basis_size = py::reinterpret_borrow<py::object>(
                    result[py::str("basis_size")]
                );
            }
            packed_stats["basis_size"] = basis_size;
            packed_stats["layout_blocks"] = py::int_(py::len(flat_start_layout));
            packed_stats["layout_expansions"] = py::int_(0);
            py::object restarts = py::int_(0);
            if (result.contains(py::str("restarts"))) {
                restarts = py::reinterpret_borrow<py::object>(
                    result[py::str("restarts")]
                );
            }
            packed_stats["restarts"] = restarts;
            packed_stats["residual_norm"] = residual;
            packed_stats["converged"] = converged;
            packed_stats["cpp_davidson"] = py::bool_(true);
            packed_stats["cpp_owner_grouped_solve_update"] = py::bool_(true);
            py::object table_source =
                py::str("grouped_renormalized_table_owner_fused_update");
            if (result.contains(py::str("table_source"))) {
                table_source = py::reinterpret_borrow<py::object>(
                    result[py::str("table_source")]
                );
            }
            packed_stats["cpp_davidson_table_source"] = table_source;
            packed_stats["flat_solution_available"] = py::bool_(true);
            packed_stats["flat_solution_layout_blocks"] =
                py::int_(py::len(flat_start_layout));
            profile_stats["packed_local_davidson"] = packed_stats;

            ++owner_local_grouped_solve_update_accepted;
            dict_increment(stats, "owner_local_grouped_solve_update_accepts");
            std::string grouped_backend = "cpp_moving_environment_grouped_update";
            try {
                if (
                    py::cast<std::string>(table_source) ==
                    "grouped_renormalized_table_owner_direct_update"
                ) {
                    grouped_backend =
                        "cpp_moving_environment_direct_grouped_update";
                }
            } catch (...) {
                PyErr_Clear();
            }
            stats["owner_local_grouped_solve_update_backend_actual"] =
                py::str(grouped_backend);
            owner_local_grouped_solve_update_last_error.clear();
            owner_local_grouped_solve_update_last_reason.clear();
            if (has_raw_update) {
                return py::make_tuple(
                    energy,
                    update,
                    result,
                    py::reinterpret_borrow<py::object>(pair[2]),
                    py::reinterpret_borrow<py::object>(pair[3]),
                    py::reinterpret_borrow<py::object>(pair[4]),
                    py::reinterpret_borrow<py::object>(pair[5])
                );
            }
            return py::make_tuple(energy, update, result);
        } catch (const py::error_already_set& exc) {
            ++owner_local_grouped_solve_update_failures;
            dict_increment(stats, "owner_local_grouped_solve_update_failures");
            owner_local_grouped_solve_update_last_error = exc.what();
            stats["owner_local_grouped_solve_update_last_error"] =
                py::str(owner_local_grouped_solve_update_last_error);
            return py::none();
        } catch (const std::exception& exc) {
            ++owner_local_grouped_solve_update_failures;
            dict_increment(stats, "owner_local_grouped_solve_update_failures");
            owner_local_grouped_solve_update_last_error = exc.what();
            stats["owner_local_grouped_solve_update_last_error"] =
                py::str(owner_local_grouped_solve_update_last_error);
            return py::none();
        }
    }

    py::object run_owner_local_optimize_from_key(const std::string& key) {
        auto it = owner_local_optimize_records.find(key);
        if (it == owner_local_optimize_records.end()) {
            ++owner_local_optimize_record_misses;
            owner_local_optimize_runner_last_error =
                "MovingEnvironment owner local-optimize record is absent";
            throw std::runtime_error(owner_local_optimize_runner_last_error);
        }
        ++owner_local_optimize_record_hits;
        ++owner_local_optimize_runner_calls;
        const double start = wall_seconds();
        OwnerLocalOptimizeRecord& record = it->second;
        py::dict stats = record.moving_environment.attr("moving_profile_stats")
            .cast<py::dict>();
        dict_increment(stats, "owner_local_optimize_calls");
        struct OwnerLocalTimer {
            CppMovingEnvironment* owner;
            py::dict stats;
            double start;
            ~OwnerLocalTimer() {
                try {
                    const double elapsed = wall_seconds() - start;
                    owner->owner_local_optimize_runner_seconds += elapsed;
                    owner->owner_local_optimize_runner_last_seconds = elapsed;
                    CppMovingEnvironment::dict_add_seconds(
                        stats,
                        "owner_local_optimize_seconds",
                        elapsed
                    );
                    stats["owner_local_optimize_last_seconds"] =
                        py::float_(elapsed);
                } catch (...) {
                    PyErr_Clear();
                }
            }
        } timer{this, stats, start};
        try {
            py::object A = record.A;
            py::object B = record.B;
            if (!record.site_chain_key.empty() && record.site_index >= 0) {
                A = owner_site_chain_get(record.site_chain_key, record.site_index);
                B = owner_site_chain_get(record.site_chain_key, record.site_index + 1);
                stats["owner_site_chain_backend_actual"] =
                    py::str("cpp_owner_site_chain");
                dict_increment(stats, "owner_site_chain_gets", 2);
            } else if (!record.site_factors.is_none() && record.site_index >= 0) {
                A = record.site_factors.attr("__getitem__")(record.site_index);
                B = record.site_factors.attr("__getitem__")(record.site_index + 1);
            }
            py::object init_vecs = record.init_vecs;
            if (
                !init_vecs.is_none() &&
                PyCallable_Check(init_vecs.ptr())
            ) {
                init_vecs = init_vecs();
            } else if (
                init_vecs.is_none() &&
                !record.flat_guess_cache.is_none() &&
                record.flat_guess_cache_index >= 0
            ) {
                try {
                    init_vecs = record.flat_guess_cache.attr("get")(
                        record.flat_guess_cache_index
                    );
                } catch (...) {
                    PyErr_Clear();
                    init_vecs = py::none();
                }
            }
            py::object direct_family_environments =
                record.complementary_direct_family_environments;
            if (!record.direct_family_payload_key.empty()) {
                direct_family_environments =
                    direct_family_payload(record.direct_family_payload_key);
                dict_increment(
                    stats,
                    "owner_local_optimize_direct_payload_key_hits"
                );
            }
            if (
                !direct_family_environments.is_none() &&
                PyCallable_Check(direct_family_environments.ptr())
            ) {
                direct_family_environments = direct_family_environments();
            }

            if (!truthy_attr(A, "_pyqed_abelian_site_tensor_data") ||
                !truthy_attr(B, "_pyqed_abelian_site_tensor_data")) {
                return reject_owner_local_optimize(stats, "non_native_site_tensor");
            }
            if (record.noise > 0.0) {
                return reject_owner_local_optimize(stats, "noise_not_supported");
            }
            if (record.local_dense_enabled) {
                return reject_owner_local_optimize(stats, "dense_solver_not_supported");
            }

            py::object merged_obj = py::none();
            if (record.native_merge_enabled) {
                merged_obj = native_owner_local_merge(record, A, B, stats);
            }
            if (
                merged_obj.is_none() &&
                py::hasattr(record.merge_fn, "merge_for_bond")
            ) {
                ++owner_local_optimize_bridge_merge_calls;
                dict_increment(stats, "owner_local_optimize_bridge_merge_calls");
                stats["owner_local_optimize_merge_actual"] =
                    py::str(
                        record.current_noise > 0.0
                            ? "python_bridge_noisy_merge"
                            : "python_bridge_merge"
                    );
                merged_obj = record.merge_fn.attr("merge_for_bond")(
                    record.bond,
                    A,
                    B
                );
            } else if (merged_obj.is_none()) {
                ++owner_local_optimize_bridge_merge_calls;
                dict_increment(stats, "owner_local_optimize_bridge_merge_calls");
                stats["owner_local_optimize_merge_actual"] =
                    py::str("python_merge_callable");
                merged_obj = record.merge_fn(A, B);
            }
            py::tuple merged = merged_obj.cast<py::tuple>();
            if (py::len(merged) < 4) {
                return reject_owner_local_optimize(stats, "merge_failed");
            }
            py::object proto = py::reinterpret_borrow<py::object>(merged[0]);
            const double norm = py::cast<double>(merged[1]);
            py::object flat_start = py::reinterpret_borrow<py::object>(merged[2]);
            py::object flat_start_layout =
                py::reinterpret_borrow<py::object>(merged[3]);
            bool flat_start_is_current = true;
            if (!(norm > 0.0)) {
                return reject_owner_local_optimize(stats, "zero_initial_norm");
            }

            py::list W;
            W.append(record.W1);
            W.append(record.W2);
            py::object E = record.E;
            py::object F = record.F;
            if (record.boundary_stack_access && !E.is_none()) {
                E = E.attr("__getitem__")(py::int_(-1));
                ++owner_local_optimize_boundary_stack_reads;
                dict_increment(stats, "owner_local_optimize_boundary_stack_reads");
            } else if (!E.is_none() && py::hasattr(E, "left_boundary")) {
                ++owner_local_optimize_boundary_bridge_calls;
                dict_increment(stats, "owner_local_optimize_boundary_bridge_calls");
                E = E.attr("left_boundary")();
            } else if (!E.is_none() && PyCallable_Check(E.ptr())) {
                E = E();
            }
            if (record.boundary_stack_access && !F.is_none()) {
                F = F.attr("__getitem__")(py::int_(-1));
                ++owner_local_optimize_boundary_stack_reads;
                dict_increment(stats, "owner_local_optimize_boundary_stack_reads");
            } else if (!F.is_none() && py::hasattr(F, "right_boundary")) {
                ++owner_local_optimize_boundary_bridge_calls;
                dict_increment(stats, "owner_local_optimize_boundary_bridge_calls");
                F = F.attr("right_boundary")();
            } else if (!F.is_none() && PyCallable_Check(F.ptr())) {
                F = F();
            }
            py::object env_after_set = py::none();
            py::object owner_binder = py::getattr(
                record.moving_environment,
                "bind_owner_operatorless_local_problem",
                py::none()
            );
            if (!owner_binder.is_none() && PyCallable_Check(owner_binder.ptr())) {
                ++owner_local_problem_bind_owner_calls;
                dict_increment(stats, "owner_local_problem_bind_owner_calls");
                env_after_set = owner_binder(
                    E,
                    W,
                    F,
                    py::arg("complementary_operator_families") =
                        record.complementary_operator_families,
                    py::arg("bond") = record.bond,
                    py::arg("complementary_boundary_payloads") =
                        record.complementary_boundary_payloads,
                    py::arg("complementary_split_stats") =
                        record.complementary_split_stats,
                    py::arg("complementary_family_environments") =
                        record.complementary_family_environments,
                    py::arg("complementary_direct_family_environments") =
                        direct_family_environments,
                    py::arg("matvec_options") = record.matvec_options
                );
            } else {
                ++owner_local_problem_bind_set_bond_fallbacks;
                dict_increment(stats, "owner_local_problem_bind_set_bond_fallbacks");
                env_after_set = record.moving_environment.attr("set_bond")(
                    E,
                    W,
                    F,
                    py::arg("complementary_operator_families") =
                        record.complementary_operator_families,
                    py::arg("bond") = record.bond,
                    py::arg("complementary_boundary_payloads") =
                        record.complementary_boundary_payloads,
                    py::arg("complementary_split_stats") =
                        record.complementary_split_stats,
                    py::arg("complementary_family_environments") =
                        record.complementary_family_environments,
                    py::arg("complementary_direct_family_environments") =
                        direct_family_environments,
                    py::arg("matvec_options") = record.matvec_options
                );
            }
            py::object H_op = py::getattr(env_after_set, "operator", py::none());
            if (
                H_op.is_none() &&
                truthy_attr(env_after_set, "_operatorless_local_problem_active")
            ) {
                H_op = env_after_set;
            }
            if (H_op.is_none() || !truthy_attr(H_op, "_packed_local_davidson")) {
                return reject_owner_local_optimize(
                    stats,
                    "packed_local_davidson_disabled"
                );
            }

            try {
                py::object safe_layout = py::none();
                if (
                    truthy_attr(H_op, "_packed_local_safe_layout_expansion") &&
                    truthy_attr(H_op, "_packed_local_use_safe_closure") &&
                    !truthy_attr(H_op, "_packed_local_project_current_support")
                ) {
                    py::object safe_map =
                        H_op.attr("_safe_two_site_layout_map")(proto);
                    if (!safe_map.is_none()) {
                        safe_layout = H_op.attr("_layout_from_map")(safe_map);
                    }
                }
                if (!safe_layout.is_none()) {
                    int equal = PyObject_RichCompareBool(
                        safe_layout.ptr(),
                        flat_start_layout.ptr(),
                        Py_EQ
                    );
                    if (equal == 0) {
                        const ssize_t safe_dim =
                            py::cast<ssize_t>(H_op.attr("_size")(safe_layout));
                        const ssize_t active_max_dim = py::cast<ssize_t>(
                            py::getattr(
                                H_op,
                                "_packed_local_davidson_max_dim",
                                py::int_(0)
                            )
                        );
                        if (active_max_dim <= 0 || safe_dim <= active_max_dim) {
                            flat_start = H_op.attr("_flatten")(proto, safe_layout);
                            flat_start_layout = safe_layout;
                        }
                    }
                }
            } catch (...) {
                PyErr_Clear();
            }

            if (!init_vecs.is_none()) {
                py::object active_layout = flat_start_layout;
                py::tuple guesses;
                if (
                    PyTuple_Check(init_vecs.ptr()) ||
                    PyList_Check(init_vecs.ptr())
                ) {
                    guesses =
                        tuple_from_sequence_object(init_vecs).cast<py::tuple>();
                } else {
                    guesses = py::make_tuple(init_vecs);
                }
                const ssize_t n_guess = static_cast<ssize_t>(py::len(guesses));
                for (ssize_t idx = 0; idx < n_guess; ++idx) {
                    py::object guess =
                        py::reinterpret_borrow<py::object>(guesses[idx]);
                    if (
                        !record.flat_guess_predicate.is_none() &&
                        PyCallable_Check(record.flat_guess_predicate.ptr()) &&
                        PyObject_IsTrue(record.flat_guess_predicate(guess).ptr()) == 1
                    ) {
                        py::object guess_flat = py::getattr(guess, "flat");
                        py::object guess_layout = tuple_from_sequence_object(
                            py::getattr(guess, "layout")
                        );
                        int equal = PyObject_RichCompareBool(
                            guess_layout.ptr(),
                            active_layout.ptr(),
                            Py_EQ
                        );
                        if (equal == 0) {
                            try {
                                guess_flat = H_op.attr("_remap_flat")(
                                    guess_flat,
                                    guess_layout,
                                    active_layout
                                );
                            } catch (...) {
                                PyErr_Clear();
                                continue;
                            }
                        } else if (equal < 0) {
                            PyErr_Clear();
                            continue;
                        }
                        try {
                            const ssize_t active_dim =
                                py::cast<ssize_t>(H_op.attr("_size")(active_layout));
                            const ssize_t guess_dim =
                                py::cast<ssize_t>(py::getattr(guess_flat, "size"));
                            if (active_dim > 0 && guess_dim == active_dim) {
                                flat_start = guess_flat;
                                flat_start_layout = active_layout;
                                flat_start_is_current = false;
                                break;
                            }
                        } catch (...) {
                            PyErr_Clear();
                        }
                    }
                }
            }

            const bool defer_preconditioner =
                truthy_attr(H_op, "_packed_local_davidson") &&
                truthy_attr(H_op, "_packed_local_flat_preconditioner");
            py::object preconditioner = py::none();
            int packed_max_iter = record.davidson_max_iter;
            const int op_max_iter = py::cast<int>(
                py::getattr(
                    H_op,
                    "_packed_local_davidson_max_iter",
                    py::int_(0)
                )
            );
            if (op_max_iter > 0 && packed_max_iter > op_max_iter) {
                packed_max_iter = op_max_iter;
            }

            const double packed_start = wall_seconds();
            py::object energy = py::none();
            py::object payload = py::none();
            py::object native_update = py::none();
            bool grouped_solve_used = false;
            py::object grouped_solution = py::none();
            py::object direct_update_left = py::none();
            py::object direct_update_right = py::none();
            py::object direct_update_truncation = py::none();
            py::object direct_update_kept = py::none();
            if (record.owner_grouped_solve_update) {
                grouped_solution = run_owner_local_grouped_solve_update(
                    record,
                    stats,
                    H_op,
                    proto,
                    flat_start,
                    flat_start_layout,
                    packed_max_iter
                );
            }
            if (!grouped_solution.is_none()) {
                py::tuple grouped = grouped_solution.cast<py::tuple>();
                energy = py::reinterpret_borrow<py::object>(grouped[0]);
                native_update = py::reinterpret_borrow<py::object>(grouped[1]);
                payload = native_update;
                grouped_solve_used = true;
                if (py::len(grouped) >= 7) {
                    direct_update_left =
                        py::reinterpret_borrow<py::object>(grouped[3]);
                    direct_update_right =
                        py::reinterpret_borrow<py::object>(grouped[4]);
                    direct_update_truncation =
                        py::reinterpret_borrow<py::object>(grouped[5]);
                    direct_update_kept =
                        py::reinterpret_borrow<py::object>(grouped[6]);
                }
                stats["owner_local_optimize_solve_actual"] =
                    py::str("cpp_grouped_update");
            } else {
                if (!defer_preconditioner) {
                    preconditioner = H_op.attr("jacobi_preconditioner")(proto);
                }
                py::object packed_solution = record.moving_environment.attr("solve_local")(
                    proto,
                    py::arg("operator") = H_op,
                    py::arg("nstates") = 1,
                    py::arg("tol") = record.davidson_tol,
                    py::arg("max_iter") = packed_max_iter,
                    py::arg("preconditioner") = preconditioner,
                    py::arg("current") = proto,
                    py::arg("return_flat") = true,
                    py::arg("initial_flat") = flat_start,
                    py::arg("initial_layout") = flat_start_layout,
                    py::arg("initial_is_current") = flat_start_is_current,
                    py::arg("return_update") = true,
                    py::arg("update_direction") = record.direction,
                    py::arg("update_m_max") = record.m_max
                );
                if (packed_solution.is_none()) {
                    return reject_owner_local_optimize(
                        stats,
                        "packed_local_solve_rejected"
                    );
                }
                py::tuple solution = packed_solution.cast<py::tuple>();
                energy = py::reinterpret_borrow<py::object>(solution[0]);
                payload = py::reinterpret_borrow<py::object>(solution[1]);
                stats["owner_local_optimize_solve_actual"] =
                    py::str("python_solve_local");
            }

            py::dict profile_stats = H_op.attr("profile_stats").cast<py::dict>();
            py::dict local_solver;
            local_solver["kind"] = py::str(
                grouped_solve_used
                    ? "cpp_owner_grouped_davidson_update"
                    : "cpp_owner_native_packed_davidson"
            );
            local_solver["seconds"] = py::float_(wall_seconds() - packed_start);
            local_solver["tol"] = py::float_(record.davidson_tol);
            local_solver["max_iter"] = py::int_(record.davidson_max_iter);
            if (profile_stats.contains(py::str("packed_local_davidson"))) {
                py::dict packed_stats = profile_stats[
                    py::str("packed_local_davidson")
                ].cast<py::dict>();
                for (auto item : packed_stats) {
                    local_solver[item.first] = item.second;
                }
            }
            profile_stats["local_solver"] = local_solver;
            record.moving_environment.attr("last_owner_local_profile") =
                H_op.attr("profile_summary")();
            record.moving_environment.attr("last_owner_local_flat_guess") = py::none();

            if (
                native_update.is_none() &&
                (direct_update_left.is_none() || direct_update_right.is_none())
            ) {
                native_update = py::getattr(
                    H_op,
                    "last_packed_davidson_solution_update",
                    py::none()
                );
            }
            if (
                native_update.is_none() &&
                !payload.is_none() &&
                py::hasattr(payload, "left") &&
                py::hasattr(payload, "right") &&
                py::hasattr(payload, "truncation_error") &&
                py::hasattr(payload, "kept_states")
            ) {
                native_update = payload;
            }
            if (native_update.is_none()) {
                py::object flat = py::getattr(
                    H_op,
                    "last_packed_davidson_solution_flat",
                    py::none()
                );
                py::object flat_layout = py::getattr(
                    H_op,
                    "last_packed_davidson_solution_layout",
                    py::none()
                );
                if (flat.is_none() || flat_layout.is_none()) {
                    return reject_owner_local_optimize(
                        stats,
                        "missing_solution_update"
                    );
                }
                native_update = record.moving_environment.attr(
                    "split_flat_two_site_update"
                )(
                    flat,
                    flat_layout,
                    py::arg("qns") = proto.attr("qns"),
                    py::arg("dirs") = proto.attr("dirs"),
                    py::arg("direction") = record.direction,
                    py::arg("m_max") = record.m_max
                );
            }

            py::object flat = py::getattr(
                H_op,
                "last_packed_davidson_solution_flat",
                py::none()
            );
            py::object flat_layout = py::getattr(
                H_op,
                "last_packed_davidson_solution_layout",
                py::none()
            );
            py::object flat_guess = py::none();
            if (
                !flat.is_none() &&
                !flat_layout.is_none() &&
                !record.flat_guess_cls.is_none()
            ) {
                flat_guess = record.flat_guess_cls(
                    flat,
                    flat_layout,
                    py::arg("qns") = proto.attr("qns"),
                    py::arg("dirs") = proto.attr("dirs"),
                    py::arg("copy") = false
                );
                record.moving_environment.attr("last_owner_local_flat_guess") =
                    flat_guess;
            }

            py::object left;
            py::object right;
            if (!direct_update_left.is_none() && !direct_update_right.is_none()) {
                left = direct_update_left;
                right = direct_update_right;
                stats["owner_local_optimize_update_payload_actual"] =
                    py::str("cpp_raw_site_tensors");
            } else if (record.native_site_storage) {
                left = native_update.attr("left");
                right = native_update.attr("right");
                stats["owner_local_optimize_update_payload_actual"] =
                    py::str("native_update_wrapper");
            } else {
                left = record.block_tensor_cls(
                    native_update.attr("left").attr("data"),
                    native_update.attr("left").attr("qns"),
                    native_update.attr("left").attr("dirs")
                );
                right = record.block_tensor_cls(
                    native_update.attr("right").attr("data"),
                    native_update.attr("right").attr("qns"),
                    native_update.attr("right").attr("dirs")
                );
                stats["owner_local_optimize_update_payload_actual"] =
                    py::str("block_tensor_wrapper");
            }
            if (
                record.commit_site_factors &&
                !record.site_chain_key.empty() &&
                record.site_index >= 0
            ) {
                owner_site_chain_set(record.site_chain_key, record.site_index, left);
                owner_site_chain_set(record.site_chain_key, record.site_index + 1, right);
                dict_increment(stats, "owner_site_chain_sets", 2);
                dict_increment(stats, "owner_local_optimize_site_commits");
                stats["owner_local_optimize_commit_actual"] =
                    py::str("cpp_owner_site_chain");
            } else if (
                record.commit_site_factors &&
                !record.site_factors.is_none() &&
                record.site_index >= 0
            ) {
                record.site_factors.attr("__setitem__")(record.site_index, left);
                record.site_factors.attr("__setitem__")(record.site_index + 1, right);
                dict_increment(stats, "owner_local_optimize_site_commits");
                stats["owner_local_optimize_commit_actual"] =
                    py::str("cpp_site_factors");
            }
            if (
                !flat_guess.is_none() &&
                !record.flat_guess_cache.is_none() &&
                record.flat_guess_cache_index >= 0
            ) {
                py::list guesses;
                guesses.append(flat_guess);
                record.flat_guess_cache.attr("__setitem__")(
                    record.flat_guess_cache_index,
                    guesses
                );
                dict_increment(stats, "owner_local_optimize_guess_cache_sets");
            }
            if (record.invalidate_direct_family_caches) {
                py::object invalidator = py::getattr(
                    record.moving_environment,
                    "invalidate_direct_family_caches",
                    py::none()
                );
                if (
                    !invalidator.is_none() &&
                    PyCallable_Check(invalidator.ptr())
                ) {
                    invalidator();
                    dict_increment(
                        stats,
                        "owner_local_optimize_direct_cache_invalidations"
                    );
                }
            }
            ++owner_local_optimize_runner_accepted;
            dict_increment(stats, "owner_local_optimize_accepts");
            stats["owner_local_optimize_backend_actual"] =
                py::str("cpp_moving_environment_local_optimize");
            stats["owner_local_optimize_last_error"] = py::none();
            owner_local_optimize_runner_last_error.clear();
            py::object truncation_error = direct_update_truncation;
            if (truncation_error.is_none()) {
                truncation_error = native_update.attr("truncation_error");
            }
            py::object kept_states = direct_update_kept;
            if (kept_states.is_none()) {
                kept_states = native_update.attr("kept_states");
            }
            return py::make_tuple(energy, left, right, truncation_error, kept_states);
        } catch (const py::error_already_set& exc) {
            ++owner_local_optimize_runner_failures;
            dict_increment(stats, "owner_local_optimize_failures");
            owner_local_optimize_runner_last_error = exc.what();
            stats["owner_local_optimize_last_error"] =
                py::str(owner_local_optimize_runner_last_error);
            throw;
        } catch (const std::exception& exc) {
            ++owner_local_optimize_runner_failures;
            dict_increment(stats, "owner_local_optimize_failures");
            owner_local_optimize_runner_last_error = exc.what();
            stats["owner_local_optimize_last_error"] =
                py::str(owner_local_optimize_runner_last_error);
            throw;
        }
    }

    py::dict run_owner_bond_step(
        py::object prepare,
        py::object prepare_payload,
        py::object optimize,
        py::object assign,
        py::object invalidate,
        py::object cache_guess,
        py::object move_environment,
        py::object fallback_environment,
        const std::string& direct_family_payload_key = "",
        const std::string& direct_family_builder_key = "",
        const std::string& direct_family_plan_key = "",
        const std::string& owner_local_optimize_key = ""
    ) {
        ++owner_bond_step_runner_calls;
        const double start = wall_seconds();
        bool prepared = false;
        bool payload_prepared = false;
        bool direct_family_payload_prepared = false;
        bool moved = false;
        bool fallback_used = false;
        bool owner_local_used = false;
        bool owner_local_committed = false;
        double payload_seconds = 0.0;
        py::object result = py::none();
        try {
            if (!prepare.is_none() && PyCallable_Check(prepare.ptr())) {
                prepared = py::cast<bool>(prepare());
            }
            if (
                !direct_family_payload_key.empty() &&
                !direct_family_plan_key.empty()
            ) {
                const double payload_start = wall_seconds();
                prepare_direct_family_payload_from_two_phase_dispatch_plan(
                    direct_family_payload_key,
                    direct_family_plan_key,
                    false,
                    true
                );
                payload_seconds = wall_seconds() - payload_start;
                payload_prepared = true;
                direct_family_payload_prepared = true;
                ++owner_bond_step_runner_payload_prepares;
                owner_bond_step_runner_payload_seconds += payload_seconds;
                owner_bond_step_runner_payload_last_seconds = payload_seconds;
            } else if (
                !direct_family_payload_key.empty() &&
                !direct_family_builder_key.empty()
            ) {
                const double payload_start = wall_seconds();
                prepare_direct_family_payload_from_builder(
                    direct_family_payload_key,
                    direct_family_builder_key,
                    false
                );
                payload_seconds = wall_seconds() - payload_start;
                payload_prepared = true;
                direct_family_payload_prepared = true;
                ++owner_bond_step_runner_payload_prepares;
                owner_bond_step_runner_payload_seconds += payload_seconds;
                owner_bond_step_runner_payload_last_seconds = payload_seconds;
            } else if (
                !prepare_payload.is_none()
                && PyCallable_Check(prepare_payload.ptr())
            ) {
                const double payload_start = wall_seconds();
                prepare_payload();
                payload_seconds = wall_seconds() - payload_start;
                payload_prepared = true;
                ++owner_bond_step_runner_payload_prepares;
                owner_bond_step_runner_payload_seconds += payload_seconds;
                owner_bond_step_runner_payload_last_seconds = payload_seconds;
            }
            if (!owner_local_optimize_key.empty()) {
                try {
                    auto local_it =
                        owner_local_optimize_records.find(owner_local_optimize_key);
                    result = run_owner_local_optimize_from_key(
                        owner_local_optimize_key
                    );
                    if (!result.is_none()) {
                        owner_local_used = true;
                        if (local_it != owner_local_optimize_records.end()) {
                            const OwnerLocalOptimizeRecord& record = local_it->second;
                            owner_local_committed = (
                                record.commit_site_factors &&
                                (
                                    !record.site_chain_key.empty() ||
                                    !record.site_factors.is_none()
                                )
                            );
                        }
                    }
                } catch (const py::error_already_set&) {
                    PyErr_Clear();
                    result = py::none();
                } catch (const std::exception&) {
                    result = py::none();
                }
            }
            if (
                result.is_none() &&
                !optimize.is_none() &&
                PyCallable_Check(optimize.ptr())
            ) {
                result = optimize();
            }
            if (result.is_none()) {
                throw std::runtime_error(
                    "MovingEnvironment owner bond-step optimize callback is absent"
                );
            }
            if (
                !owner_local_committed &&
                !assign.is_none() &&
                PyCallable_Check(assign.ptr())
            ) {
                ++owner_bond_step_runner_assign_calls;
                assign(result);
            } else if (owner_local_committed) {
                ++owner_bond_step_runner_assign_skips;
            }
            if (!invalidate.is_none() && PyCallable_Check(invalidate.ptr())) {
                invalidate();
            }
            if (
                !owner_local_used &&
                !cache_guess.is_none() &&
                PyCallable_Check(cache_guess.ptr())
            ) {
                cache_guess();
            }
            if (
                !move_environment.is_none()
                && PyCallable_Check(move_environment.ptr())
            ) {
                moved = py::cast<bool>(move_environment());
            }
            if (
                !moved
                && !fallback_environment.is_none()
                && PyCallable_Check(fallback_environment.ptr())
            ) {
                fallback_environment();
                moved = true;
                fallback_used = true;
                ++owner_bond_step_runner_environment_fallbacks;
            }
            if (moved) {
                ++owner_bond_step_runner_environment_moves;
            }
            ++owner_bond_step_runner_accepted;
            const double elapsed = wall_seconds() - start;
            owner_bond_step_runner_seconds += elapsed;
            owner_bond_step_runner_last_seconds = elapsed;
            owner_bond_step_runner_last_error.clear();
            py::dict out;
            out["result"] = result;
            out["prepared"] = py::bool_(prepared);
            out["payload_prepared"] = py::bool_(payload_prepared);
            out["direct_family_payload_prepared"] =
                py::bool_(direct_family_payload_prepared);
            out["payload_seconds"] = py::float_(payload_seconds);
            out["moved"] = py::bool_(moved);
            out["fallback_used"] = py::bool_(fallback_used);
            out["seconds"] = py::float_(elapsed);
            out["backend"] = py::str("cpp_owner_bond_step_runner");
            return out;
        } catch (const py::error_already_set& exc) {
            ++owner_bond_step_runner_failures;
            const double elapsed = wall_seconds() - start;
            owner_bond_step_runner_seconds += elapsed;
            owner_bond_step_runner_last_seconds = elapsed;
            owner_bond_step_runner_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++owner_bond_step_runner_failures;
            const double elapsed = wall_seconds() - start;
            owner_bond_step_runner_seconds += elapsed;
            owner_bond_step_runner_last_seconds = elapsed;
            owner_bond_step_runner_last_error = exc.what();
            throw;
        }
    }

    py::dict run_owner_bond_step_from_key(const std::string& key) {
        auto it = owner_bond_step_records.find(key);
        if (it == owner_bond_step_records.end()) {
            ++owner_bond_step_record_misses;
            owner_bond_step_record_last_error =
                "MovingEnvironment owner bond-step record is absent";
            throw std::runtime_error(owner_bond_step_record_last_error);
        }
        ++owner_bond_step_record_hits;
        OwnerBondStepRecord& record = it->second;
        owner_bond_step_record_last_error.clear();
        return run_owner_bond_step(
            record.prepare,
            record.prepare_payload,
            record.optimize,
            record.assign,
            record.invalidate,
            record.cache_guess,
            record.move_environment,
            record.fallback_environment,
            record.direct_family_payload_key,
            record.direct_family_builder_key,
            record.direct_family_plan_key,
            record.owner_local_optimize_key
        );
    }

    py::dict run_owner_typed_bond_step_from_key(const std::string& key) {
        auto it = owner_typed_bond_step_records.find(key);
        if (it == owner_typed_bond_step_records.end()) {
            ++owner_typed_bond_step_record_misses;
            owner_typed_bond_step_record_last_error =
                "MovingEnvironment owner typed bond-step record is absent";
            throw std::runtime_error(owner_typed_bond_step_record_last_error);
        }
        ++owner_typed_bond_step_record_hits;
        OwnerTypedBondStepRecord& record = it->second;
        owner_typed_bond_step_record_last_error.clear();
        ++owner_bond_step_runner_calls;
        const double start = wall_seconds();
        bool prepared = false;
        bool payload_prepared = false;
        bool direct_family_payload_prepared = false;
        bool moved = false;
        bool fallback_used = false;
        bool owner_local_used = false;
        bool prepared_from_record = false;
        double payload_seconds = 0.0;
        py::object result = py::none();
        try {
            if (
                record.should_move &&
                !record.moving_environment.is_none() &&
                !record.environment_direction.empty() &&
                !record.update_rows.is_none() &&
                !record.pop_rows.is_none()
            ) {
                py::dict pending;
                pending["sweep_direction"] = py::str(record.step_direction);
                pending["bond"] = py::int_(record.bond);
                pending["environment_direction"] =
                    py::str(record.environment_direction);
                pending["update_rows"] = record.update_rows;
                pending["pop_rows"] = record.pop_rows;
                pending["update_records"] = record.update_records;
                pending["pop_records"] = record.pop_records;
                record.moving_environment.attr("_pending_cpp_bond_environment_step") =
                    pending;
                record.moving_environment.attr("_last_cpp_bond_environment_step") =
                    py::none();
                try {
                    py::dict stats = record.moving_environment
                        .attr("moving_profile_stats")
                        .cast<py::dict>();
                    dict_increment(stats, "cpp_bond_step_transaction_record_prepares");
                } catch (...) {
                    PyErr_Clear();
                }
                ++owner_typed_bond_step_environment_record_prepares;
                prepared = true;
                prepared_from_record = true;
            } else if (
                record.should_move &&
                py::hasattr(record.bridge, "prepare_bond")
            ) {
                ++owner_typed_bond_step_python_prepare_calls;
                prepared = py::cast<bool>(
                    record.bridge.attr("prepare_bond")(
                        py::str(record.step_direction),
                        py::int_(record.bond)
                    )
                );
            }
            const bool has_static_direct_family_keys =
                (
                    !record.direct_family_payload_key.empty() &&
                    (
                        !record.direct_family_plan_key.empty() ||
                        !record.direct_family_builder_key.empty()
                    )
                ) ||
                (
                    !record.direct_family_payload_key.empty() &&
                    direct_family_payload_records.find(record.direct_family_payload_key)
                        != direct_family_payload_records.end()
                );
            if (
                !has_static_direct_family_keys &&
                !record.direct_family_plan_provider.is_none() &&
                PyCallable_Check(record.direct_family_plan_provider.ptr())
            ) {
                record.direct_family_payload_key.clear();
                record.direct_family_builder_key.clear();
                record.direct_family_plan_key.clear();
                if (!record.owner_local_optimize_key.empty()) {
                    auto local_it = owner_local_optimize_records.find(
                        record.owner_local_optimize_key
                    );
                    if (local_it != owner_local_optimize_records.end()) {
                        local_it->second.direct_family_payload_key.clear();
                    }
                }
                ++owner_typed_bond_step_direct_plan_provider_calls;
                py::object provided = py::none();
                try {
                    provided =
                        record.direct_family_plan_provider(py::int_(record.bond));
                } catch (const py::error_already_set&) {
                    ++owner_typed_bond_step_direct_plan_provider_failures;
                    throw;
                } catch (const std::exception&) {
                    ++owner_typed_bond_step_direct_plan_provider_failures;
                    throw;
                }
                if (!provided.is_none()) {
                    if (py::isinstance<py::dict>(provided)) {
                        py::dict info = provided.cast<py::dict>();
                        if (info.contains(py::str("payload_key"))) {
                            py::object value = py::reinterpret_borrow<py::object>(
                                info[py::str("payload_key")]
                            );
                            if (!value.is_none()) {
                                record.direct_family_payload_key =
                                    py::cast<std::string>(value);
                            }
                        }
                        if (info.contains(py::str("builder_key"))) {
                            py::object value = py::reinterpret_borrow<py::object>(
                                info[py::str("builder_key")]
                            );
                            if (!value.is_none()) {
                                record.direct_family_builder_key =
                                    py::cast<std::string>(value);
                            }
                        }
                        if (info.contains(py::str("plan_key"))) {
                            py::object value = py::reinterpret_borrow<py::object>(
                                info[py::str("plan_key")]
                            );
                            if (!value.is_none()) {
                                record.direct_family_plan_key =
                                    py::cast<std::string>(value);
                            }
                        }
                    } else {
                        py::tuple pair =
                            tuple_from_sequence_object(provided).cast<py::tuple>();
                        if (py::len(pair) >= 2) {
                            record.direct_family_payload_key =
                                py::cast<std::string>(pair[0]);
                            record.direct_family_plan_key =
                                py::cast<std::string>(pair[1]);
                        }
                    }
                }
                if (!record.direct_family_payload_key.empty()) {
                    ++owner_typed_bond_step_direct_plan_provider_accepts;
                } else {
                    ++owner_typed_bond_step_direct_plan_provider_empty;
                }
                if (
                    !record.owner_local_optimize_key.empty() &&
                    !record.direct_family_payload_key.empty()
                ) {
                    auto local_it = owner_local_optimize_records.find(
                        record.owner_local_optimize_key
                    );
                    if (local_it != owner_local_optimize_records.end()) {
                        local_it->second.direct_family_payload_key =
                            record.direct_family_payload_key;
                    }
                }
            }
            if (
                !record.direct_family_payload_key.empty() &&
                !record.direct_family_plan_key.empty()
            ) {
                const double payload_start = wall_seconds();
                prepare_direct_family_payload_from_two_phase_dispatch_plan(
                    record.direct_family_payload_key,
                    record.direct_family_plan_key,
                    false,
                    true
                );
                payload_seconds = wall_seconds() - payload_start;
                payload_prepared = true;
                direct_family_payload_prepared = true;
                ++owner_bond_step_runner_payload_prepares;
                owner_bond_step_runner_payload_seconds += payload_seconds;
                owner_bond_step_runner_payload_last_seconds = payload_seconds;
            } else if (
                !record.direct_family_payload_key.empty() &&
                !record.direct_family_builder_key.empty()
            ) {
                const double payload_start = wall_seconds();
                prepare_direct_family_payload_from_builder(
                    record.direct_family_payload_key,
                    record.direct_family_builder_key,
                    false
                );
                payload_seconds = wall_seconds() - payload_start;
                payload_prepared = true;
                direct_family_payload_prepared = true;
                ++owner_bond_step_runner_payload_prepares;
                owner_bond_step_runner_payload_seconds += payload_seconds;
                owner_bond_step_runner_payload_last_seconds = payload_seconds;
            }
            if (!record.owner_local_optimize_key.empty()) {
                try {
                    result = run_owner_local_optimize_from_key(
                        record.owner_local_optimize_key
                    );
                    if (!result.is_none()) {
                        owner_local_used = true;
                    }
                } catch (const py::error_already_set&) {
                    PyErr_Clear();
                    result = py::none();
                } catch (const std::exception&) {
                    result = py::none();
                }
            }
            if (
                result.is_none() &&
                py::hasattr(record.bridge, "optimize_bond")
            ) {
                result = record.bridge.attr("optimize_bond")(
                    py::int_(record.bond),
                    py::str(record.step_direction)
                );
            }
            if (result.is_none()) {
                throw std::runtime_error(
                    "MovingEnvironment owner typed bond-step optimize path is absent"
                );
            }
            if (!owner_local_used && py::hasattr(record.bridge, "assign_bond")) {
                ++owner_bond_step_runner_assign_calls;
                record.bridge.attr("assign_bond")(
                    py::int_(record.bond),
                    result
                );
            } else if (owner_local_used) {
                ++owner_bond_step_runner_assign_skips;
            }
            if (
                !record.clear_side.empty() &&
                py::hasattr(record.bridge, "invalidate_bond")
            ) {
                record.bridge.attr("invalidate_bond")(
                    py::int_(record.bond),
                    py::str(record.clear_side)
                );
            }
            if (!owner_local_used && py::hasattr(record.bridge, "cache_guess")) {
                record.bridge.attr("cache_guess")(py::int_(record.bond));
            }
            if (
                record.should_move &&
                prepared_from_record &&
                !record.moving_environment.is_none()
            ) {
                try {
                    py::object consumed = record.moving_environment.attr(
                        "consume_cpp_bond_environment_step"
                    )(
                        py::str(record.step_direction),
                        py::int_(record.bond)
                    );
                    if (!consumed.is_none()) {
                        moved = true;
                        ++owner_typed_bond_step_environment_record_consumes;
                        try {
                            py::dict stats = record.moving_environment
                                .attr("moving_profile_stats")
                                .cast<py::dict>();
                            dict_increment(
                                stats,
                                "cpp_bond_step_transaction_record_consumes"
                            );
                        } catch (...) {
                            PyErr_Clear();
                        }
                    }
                } catch (...) {
                    PyErr_Clear();
                    moved = false;
                }
            }
            if (
                !moved &&
                record.should_move &&
                py::hasattr(record.bridge, "move_environment")
            ) {
                ++owner_typed_bond_step_python_move_calls;
                moved = py::cast<bool>(
                    record.bridge.attr("move_environment")(
                        py::str(record.step_direction),
                        py::int_(record.bond)
                    )
                );
            }
            if (
                !moved &&
                record.should_move &&
                py::hasattr(record.bridge, "fallback_environment")
            ) {
                record.bridge.attr("fallback_environment")(
                    py::str(record.step_direction),
                    py::int_(record.bond)
                );
                moved = true;
                fallback_used = true;
                ++owner_bond_step_runner_environment_fallbacks;
            }
            if (moved) {
                ++owner_bond_step_runner_environment_moves;
                if (
                    record.successor_direct_family_bond >= 0 &&
                    !record.successor_direct_family_step_key.empty()
                ) {
                    refresh_owner_typed_bond_step_direct_family_keys_from_provider_impl(
                        record.successor_direct_family_step_key,
                        record.successor_direct_family_bond,
                        record.successor_direct_family_key_provider,
                        true
                    );
                }
            }
            ++owner_bond_step_runner_accepted;
            const double elapsed = wall_seconds() - start;
            owner_bond_step_runner_seconds += elapsed;
            owner_bond_step_runner_last_seconds = elapsed;
            owner_bond_step_runner_last_error.clear();
            py::dict out;
            out["result"] = result;
            out["prepared"] = py::bool_(prepared);
            out["payload_prepared"] = py::bool_(payload_prepared);
            out["direct_family_payload_prepared"] =
                py::bool_(direct_family_payload_prepared);
            out["payload_seconds"] = py::float_(payload_seconds);
            out["moved"] = py::bool_(moved);
            out["fallback_used"] = py::bool_(fallback_used);
            out["seconds"] = py::float_(elapsed);
            out["backend"] = py::str("cpp_owner_typed_bond_step_runner");
            return out;
        } catch (const py::error_already_set& exc) {
            ++owner_bond_step_runner_failures;
            const double elapsed = wall_seconds() - start;
            owner_bond_step_runner_seconds += elapsed;
            owner_bond_step_runner_last_seconds = elapsed;
            owner_bond_step_runner_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++owner_bond_step_runner_failures;
            const double elapsed = wall_seconds() - start;
            owner_bond_step_runner_seconds += elapsed;
            owner_bond_step_runner_last_seconds = elapsed;
            owner_bond_step_runner_last_error = exc.what();
            throw;
        }
    }

    py::dict run_owner_half_sweep(
        const std::string& direction,
        py::sequence bonds,
        py::object make_step,
        py::object make_update,
        py::object after_step,
        const std::string& step_direction
    ) {
        ++owner_half_sweep_runner_calls;
        owner_half_sweep_runner_last_direction = direction;
        const double start = wall_seconds();
        py::list updates;
        py::object last_result = py::none();
        ssize_t last_bond = -1;
        long long n_bonds = 0;
        long long payload_prepares = 0;
        long long direct_family_payload_prepares = 0;
        long long environment_moves = 0;
        long long environment_fallbacks = 0;
        double payload_seconds = 0.0;
        try {
            if (make_step.is_none() || !PyCallable_Check(make_step.ptr())) {
                throw std::runtime_error(
                    "MovingEnvironment owner half-sweep make_step callback is absent"
                );
            }
            const ssize_t n = static_cast<ssize_t>(py::len(bonds));
            for (ssize_t idx = 0; idx < n; ++idx) {
                const ssize_t bond = py::cast<ssize_t>(bonds[idx]);
                const double local_start = wall_seconds();
                py::dict spec = make_step(py::int_(bond)).cast<py::dict>();
                py::object none = py::none();
                py::object prepare = spec.contains(py::str("prepare"))
                    ? py::reinterpret_borrow<py::object>(spec[py::str("prepare")])
                    : none;
                py::object prepare_payload = spec.contains(py::str("prepare_payload"))
                    ? py::reinterpret_borrow<py::object>(spec[py::str("prepare_payload")])
                    : none;
                py::object optimize = spec.contains(py::str("optimize"))
                    ? py::reinterpret_borrow<py::object>(spec[py::str("optimize")])
                    : none;
                py::object assign = spec.contains(py::str("assign"))
                    ? py::reinterpret_borrow<py::object>(spec[py::str("assign")])
                    : none;
                py::object invalidate = spec.contains(py::str("invalidate"))
                    ? py::reinterpret_borrow<py::object>(spec[py::str("invalidate")])
                    : none;
                py::object cache_guess = spec.contains(py::str("cache_guess"))
                    ? py::reinterpret_borrow<py::object>(spec[py::str("cache_guess")])
                    : none;
                py::object move_environment =
                    spec.contains(py::str("move_environment"))
                    ? py::reinterpret_borrow<py::object>(
                          spec[py::str("move_environment")]
                      )
                    : none;
                py::object fallback_environment =
                    spec.contains(py::str("fallback_environment"))
                    ? py::reinterpret_borrow<py::object>(
                          spec[py::str("fallback_environment")]
                      )
                    : none;
                std::string direct_family_payload_key;
                std::string direct_family_builder_key;
                if (spec.contains(py::str("direct_family_payload_key"))) {
                    py::object value = py::reinterpret_borrow<py::object>(
                        spec[py::str("direct_family_payload_key")]
                    );
                    if (!value.is_none()) {
                        direct_family_payload_key = py::cast<std::string>(value);
                    }
                }
                if (spec.contains(py::str("direct_family_builder_key"))) {
                    py::object value = py::reinterpret_borrow<py::object>(
                        spec[py::str("direct_family_builder_key")]
                    );
                    if (!value.is_none()) {
                        direct_family_builder_key = py::cast<std::string>(value);
                    }
                }
                std::string direct_family_plan_key;
                if (spec.contains(py::str("direct_family_plan_key"))) {
                    py::object value = py::reinterpret_borrow<py::object>(
                        spec[py::str("direct_family_plan_key")]
                    );
                    if (!value.is_none()) {
                        direct_family_plan_key = py::cast<std::string>(value);
                    }
                }
                std::string owner_local_optimize_key;
                if (spec.contains(py::str("owner_local_optimize_key"))) {
                    py::object value = py::reinterpret_borrow<py::object>(
                        spec[py::str("owner_local_optimize_key")]
                    );
                    if (!value.is_none()) {
                        owner_local_optimize_key = py::cast<std::string>(value);
                    }
                }
                py::dict step = run_owner_bond_step(
                    prepare,
                    prepare_payload,
                    optimize,
                    assign,
                    invalidate,
                    cache_guess,
                    move_environment,
                    fallback_environment,
                    direct_family_payload_key,
                    direct_family_builder_key,
                    direct_family_plan_key,
                    owner_local_optimize_key
                );
                last_result = py::reinterpret_borrow<py::object>(
                    step[py::str("result")]
                );
                last_bond = bond;
                ++n_bonds;
                if (py::cast<bool>(step[py::str("payload_prepared")])) {
                    ++payload_prepares;
                    payload_seconds += py::cast<double>(
                        step[py::str("payload_seconds")]
                    );
                }
                if (
                    step.contains(py::str("direct_family_payload_prepared")) &&
                    py::cast<bool>(
                        step[py::str("direct_family_payload_prepared")]
                    )
                ) {
                    ++direct_family_payload_prepares;
                }
                if (py::cast<bool>(step[py::str("moved")])) {
                    ++environment_moves;
                }
                if (py::cast<bool>(step[py::str("fallback_used")])) {
                    ++environment_fallbacks;
                }
                py::object update = py::none();
                if (!make_update.is_none() && PyCallable_Check(make_update.ptr())) {
                    const double local_seconds = wall_seconds() - local_start;
                    update = make_update(
                        py::int_(bond),
                        last_result,
                        py::float_(local_seconds)
                    );
                    if (!update.is_none()) {
                        updates.append(update);
                    }
                } else {
                    const double local_seconds = wall_seconds() - local_start;
                    try {
                        py::tuple result_tuple = last_result.cast<py::tuple>();
                        if (py::len(result_tuple) >= 5) {
                            py::dict generated_update;
                            generated_update["bond"] = py::int_(bond);
                            generated_update["energy"] = py::float_(
                                real_scalar(
                                    py::reinterpret_borrow<py::object>(
                                        result_tuple[0]
                                    )
                                )
                            );
                            generated_update["truncation"] = py::float_(
                                real_scalar(
                                    py::reinterpret_borrow<py::object>(
                                        result_tuple[3]
                                    )
                                )
                            );
                            generated_update["states_kept"] =
                                py::reinterpret_borrow<py::object>(
                                    result_tuple[4]
                                );
                            generated_update["seconds"] =
                                py::float_(local_seconds);
                            generated_update["matvec_profile"] = py::none();
                            update = generated_update;
                            updates.append(update);
                        }
                    } catch (...) {
                        PyErr_Clear();
                    }
                }
                if (!after_step.is_none() && PyCallable_Check(after_step.ptr())) {
                    after_step(py::int_(bond), last_result, update);
                }
            }
            owner_half_sweep_runner_bonds += n_bonds;
            ++owner_half_sweep_runner_accepted;
            const double elapsed = wall_seconds() - start;
            owner_half_sweep_runner_seconds += elapsed;
            owner_half_sweep_runner_last_seconds = elapsed;
            owner_half_sweep_runner_last_error.clear();
            py::dict out;
            out["updates"] = updates;
            if (n_bonds == 0) {
                out["last_bond"] = py::none();
            } else {
                out["last_bond"] = py::int_(last_bond);
            }
            out["last_result"] = last_result;
            out["seconds"] = py::float_(elapsed);
            out["bonds"] = py::int_(n_bonds);
            out["payload_prepares"] = py::int_(payload_prepares);
            out["direct_family_payload_prepares"] =
                py::int_(direct_family_payload_prepares);
            out["payload_seconds"] = py::float_(payload_seconds);
            out["environment_moves"] = py::int_(environment_moves);
            out["environment_fallbacks"] = py::int_(environment_fallbacks);
            out["step_direction"] = py::str(step_direction);
            out["backend"] = py::str("cpp_owner_half_sweep_runner");
            return out;
        } catch (const py::error_already_set& exc) {
            ++owner_half_sweep_runner_failures;
            const double elapsed = wall_seconds() - start;
            owner_half_sweep_runner_seconds += elapsed;
            owner_half_sweep_runner_last_seconds = elapsed;
            owner_half_sweep_runner_last_error = exc.what();
            throw;
        } catch (const std::exception& exc) {
            ++owner_half_sweep_runner_failures;
            const double elapsed = wall_seconds() - start;
            owner_half_sweep_runner_seconds += elapsed;
            owner_half_sweep_runner_last_seconds = elapsed;
            owner_half_sweep_runner_last_error = exc.what();
            throw;
        }
    }

