    static FamilyData data_from_environment(py::object env_obj) {
        py::sequence env = env_obj.cast<py::sequence>();
        if (static_cast<ssize_t>(py::len(env)) < 3) {
            throw std::runtime_error("family environment must contain E, W, and F");
        }
        py::sequence W = env[1].cast<py::sequence>();
        if (static_cast<ssize_t>(py::len(W)) < 2) {
            throw std::runtime_error(
                "family environment W must contain two site tensors"
            );
        }
        return FamilyData{
            env[0].attr("data").cast<py::dict>(),
            W[0].attr("data").cast<py::dict>(),
            W[1].attr("data").cast<py::dict>(),
            env[2].attr("data").cast<py::dict>(),
        };
    }

    static std::array<ssize_t, 4> parse_shape4(py::handle shape_obj) {
        py::sequence shape = py::reinterpret_borrow<py::object>(shape_obj)
                                 .cast<py::sequence>();
        if (static_cast<ssize_t>(py::len(shape)) != 4) {
            throw std::runtime_error("RawRoutePlan layout rebind expects rank-4 blocks");
        }
        return {
            py::cast<ssize_t>(shape[0]),
            py::cast<ssize_t>(shape[1]),
            py::cast<ssize_t>(shape[2]),
            py::cast<ssize_t>(shape[3]),
        };
    }

    static LayoutData parse_layout(py::object py_layout) {
        py::sequence layout = py_layout.cast<py::sequence>();
        LayoutData data{py::dict(), py::dict()};
        ssize_t offset = 0;
        for (ssize_t index = 0; index < static_cast<ssize_t>(py::len(layout)); ++index) {
            py::sequence item = layout[index].cast<py::sequence>();
            if (static_cast<ssize_t>(py::len(item)) < 2) {
                throw std::runtime_error("RawRoutePlan layout item must be (key, shape)");
            }
            py::object key = py::reinterpret_borrow<py::object>(item[0]);
            py::object shape_obj = py::reinterpret_borrow<py::object>(item[1]);
            auto shape = parse_shape4(shape_obj);
            ssize_t size = 1;
            py::tuple shape_tuple(4);
            for (ssize_t axis = 0; axis < 4; ++axis) {
                if (shape[static_cast<size_t>(axis)] < 0) {
                    throw std::runtime_error("RawRoutePlan layout dimensions must be non-negative");
                }
                size *= shape[static_cast<size_t>(axis)];
                shape_tuple[axis] = py::int_(shape[static_cast<size_t>(axis)]);
            }
            data.shapes[key] = shape_tuple;
            data.starts[key] = py::make_tuple(offset, size);
            offset += size;
        }
        return data;
    }

    static std::array<ssize_t, 8> layout_dims(
        const std::array<ssize_t, 4>& a_shape,
        const std::array<ssize_t, 4>& out_shape
    ) {
        return {
            out_shape[0],
            out_shape[1],
            out_shape[2],
            out_shape[3],
            a_shape[0],
            a_shape[2],
            a_shape[1],
            a_shape[3],
        };
    }

    static void rebind_entry_layout(
        const LayoutData& layout,
        const Entry& entry,
        std::array<ssize_t, 8>& dims,
        ssize_t& in_start,
        ssize_t& out_start
    ) {
        if (entry.a_key.is_none() || entry.out_key.is_none()) {
            throw std::runtime_error("RawRoutePlan entry has no layout keys");
        }
        if (!layout.shapes.contains(entry.a_key) || !layout.shapes.contains(entry.out_key)) {
            throw std::runtime_error("RawRoutePlan layout key is absent from current layout");
        }
        auto a_shape = parse_shape4(layout.shapes[entry.a_key]);
        auto out_shape = parse_shape4(layout.shapes[entry.out_key]);
        dims = layout_dims(a_shape, out_shape);
        py::sequence in_record = layout.starts[entry.a_key].cast<py::sequence>();
        py::sequence out_record = layout.starts[entry.out_key].cast<py::sequence>();
        in_start = py::cast<ssize_t>(in_record[0]);
        out_start = py::cast<ssize_t>(out_record[0]);
    }

    static std::string object_token(py::handle obj) {
        return py::str(obj).cast<std::string>();
    }

    static std::string tuple_token(py::object first, py::object second) {
        return py::str(py::make_tuple(first, second)).cast<std::string>();
    }

    static std::vector<py::object> key_items(py::handle key_obj) {
        py::tuple key = py::reinterpret_borrow<py::object>(key_obj).cast<py::tuple>();
        std::vector<py::object> items;
        items.reserve(static_cast<size_t>(py::len(key)));
        for (ssize_t index = 0; index < static_cast<ssize_t>(py::len(key)); ++index) {
            items.push_back(py::reinterpret_borrow<py::object>(key[index]));
        }
        return items;
    }

    static bool is_packed_boundary_tensor(py::handle obj) {
        if (!obj || obj.is_none()) {
            return false;
        }
        if (PyObject_HasAttrString(obj.ptr(), "_pyqed_packed_boundary_tensor") != 1) {
            return false;
        }
        try {
            return py::cast<bool>(
                py::reinterpret_borrow<py::object>(obj).attr(
                    "_pyqed_packed_boundary_tensor"
                )
            );
        } catch (const py::error_already_set&) {
            return false;
        } catch (const py::cast_error&) {
            return false;
        }
    }

    template <typename Callback>
    static void visit_tensor_blocks(py::object tensor, Callback&& callback) {
        if (is_packed_boundary_tensor(tensor)) {
            py::sequence keys = tensor.attr("keys").cast<py::sequence>();
            py::sequence blocks = tensor.attr("blocks").cast<py::sequence>();
            const ssize_t n = static_cast<ssize_t>(py::len(keys));
            if (static_cast<ssize_t>(py::len(blocks)) != n) {
                throw std::runtime_error(
                    "packed boundary tensor keys/blocks length mismatch"
                );
            }
            for (ssize_t index = 0; index < n; ++index) {
                callback(
                    py::reinterpret_borrow<py::object>(keys[index]),
                    py::reinterpret_borrow<py::object>(blocks[index])
                );
            }
            return;
        }
        py::dict data;
        if (py::isinstance<py::dict>(tensor)) {
            data = tensor.cast<py::dict>();
        } else {
            data = tensor.attr("data").cast<py::dict>();
        }
        for (auto item : data) {
            callback(
                py::reinterpret_borrow<py::object>(item.first),
                py::reinterpret_borrow<py::object>(item.second)
            );
        }
    }

    static size_t tensor_block_count(py::object tensor) {
        if (is_packed_boundary_tensor(tensor)) {
            return static_cast<size_t>(py::len(tensor.attr("keys")));
        }
        if (py::isinstance<py::dict>(tensor)) {
            return static_cast<size_t>(py::len(tensor));
        }
        return static_cast<size_t>(py::len(tensor.attr("data")));
    }

    static py::object tensor_block_by_key(py::object tensor, py::object wanted_key) {
        if (is_packed_boundary_tensor(tensor)) {
            py::sequence keys = tensor.attr("keys").cast<py::sequence>();
            py::sequence blocks = tensor.attr("blocks").cast<py::sequence>();
            const ssize_t n = static_cast<ssize_t>(py::len(keys));
            if (static_cast<ssize_t>(py::len(blocks)) != n) {
                throw std::runtime_error(
                    "packed boundary tensor keys/blocks length mismatch"
                );
            }
            for (ssize_t index = 0; index < n; ++index) {
                py::object key = py::reinterpret_borrow<py::object>(keys[index]);
                int eq = PyObject_RichCompareBool(
                    key.ptr(),
                    wanted_key.ptr(),
                    Py_EQ
                );
                if (eq < 0) {
                    throw py::error_already_set();
                }
                if (eq == 1) {
                    return py::reinterpret_borrow<py::object>(blocks[index]);
                }
            }
            throw py::key_error("packed boundary tensor block key not found");
        }
        py::dict data = py::isinstance<py::dict>(tensor)
            ? tensor.cast<py::dict>()
            : tensor.attr("data").cast<py::dict>();
        return py::reinterpret_borrow<py::object>(data[wanted_key]);
    }

    static std::unordered_map<std::string, std::vector<TensorBlock>> block_index(
        py::object tensor,
        ssize_t axis0,
        ssize_t axis1 = -1
    ) {
        std::unordered_map<std::string, std::vector<TensorBlock>> out;
        visit_tensor_blocks(tensor, [&](py::object key, py::object block_obj) {
            std::vector<py::object> items = key_items(key);
            if (
                axis0 < 0
                || axis0 >= static_cast<ssize_t>(items.size())
                || (
                    axis1 >= 0
                    && axis1 >= static_cast<ssize_t>(items.size())
                )
            ) {
                throw std::runtime_error("block key does not contain requested axes");
            }
            std::string token = axis1 < 0
                ? object_token(items[static_cast<size_t>(axis0)])
                : tuple_token(
                    items[static_cast<size_t>(axis0)],
                    items[static_cast<size_t>(axis1)]
                );
            py::array_t<cdouble, py::array::c_style | py::array::forcecast> data_block =
                py::cast<py::array_t<cdouble, py::array::c_style | py::array::forcecast>>(
                    block_obj
                );
            TensorBlock block{
                key,
                std::move(items),
                data_block,
                data_block.ptr(),
            };
            out[token].push_back(std::move(block));
        });
        return out;
    }

    static std::unordered_map<std::string, LayoutBlock> layout_blocks(
        py::object py_layout
    ) {
        py::sequence layout = py_layout.cast<py::sequence>();
        std::unordered_map<std::string, LayoutBlock> blocks;
        ssize_t start = 0;
        for (ssize_t index = 0; index < static_cast<ssize_t>(py::len(layout)); ++index) {
            py::sequence item = layout[index].cast<py::sequence>();
            if (static_cast<ssize_t>(py::len(item)) < 2) {
                throw std::runtime_error("layout item must be (key, shape)");
            }
            py::object key = py::reinterpret_borrow<py::object>(item[0]);
            std::array<ssize_t, 4> shape = parse_shape4(item[1]);
            ssize_t size = 1;
            for (ssize_t axis = 0; axis < 4; ++axis) {
                size *= shape[static_cast<size_t>(axis)];
            }
            blocks.emplace(
                object_token(key),
                LayoutBlock{shape, start, size}
            );
            start += size;
        }
        return blocks;
    }

    static CppRawPayloadBuilder build_named_family_payload(
        py::object py_family_environments,
        py::object py_a_data,
        py::object py_layout,
        bool use_stack_kernels = true
    ) {
        if (!use_stack_kernels) {
            throw std::runtime_error("named raw payload builder requires C++ stack kernels");
        }
        (void)py_a_data;
        py::dict family_environments = py_family_environments.cast<py::dict>();
        auto layout = layout_blocks(py_layout);
        py::sequence layout_seq = py_layout.cast<py::sequence>();
        std::vector<ActiveLayoutBlock> a_blocks;
        a_blocks.reserve(static_cast<size_t>(py::len(layout_seq)));
        for (ssize_t index = 0; index < static_cast<ssize_t>(py::len(layout_seq)); ++index) {
            py::sequence item = layout_seq[index].cast<py::sequence>();
            py::object key = py::reinterpret_borrow<py::object>(item[0]);
            auto items = key_items(key);
            if (items.size() != 4) {
                throw std::runtime_error("layout block keys must have rank 4");
            }
            auto layout_it = layout.find(object_token(key));
            if (layout_it == layout.end()) {
                continue;
            }
            a_blocks.push_back(
                ActiveLayoutBlock{
                    key,
                    std::move(items),
                    layout_it->second,
                }
            );
        }

        CppRawPayloadBuilder builder;
        for (auto family_item : family_environments) {
            FamilyData family = data_from_environment(
                py::reinterpret_borrow<py::object>(family_item.second)
            );
            auto e_by_ket_l = block_index(family.e_data, 2);
            auto w1_by_left_in = block_index(family.w1_data, 0, 3);
            auto w2_by_left_in = block_index(family.w2_data, 0, 3);
            auto f_by_mpo_ket_r = block_index(family.f_data, 0, 2);

            for (const auto& a_block : a_blocks) {
                const std::string a_token = object_token(a_block.key);
                auto a_layout_it = layout.find(a_token);
                if (a_layout_it == layout.end()) {
                    continue;
                }
                auto left_qn = a_block.items[0];
                auto right_qn = a_block.items[1];
                auto p1_in = a_block.items[2];
                auto p2_in = a_block.items[3];
                auto e_it = e_by_ket_l.find(object_token(left_qn));
                if (e_it == e_by_ket_l.end()) {
                    continue;
                }
                for (const auto& e_block : e_it->second) {
                    if (e_block.data.ndim() != 3) {
                        throw std::runtime_error("E blocks must be rank 3");
                    }
                    const auto& e_key = e_block.items;
                    auto w1_it = w1_by_left_in.find(tuple_token(e_key[0], p1_in));
                    if (w1_it == w1_by_left_in.end()) {
                        continue;
                    }
                    for (const auto& w1_block : w1_it->second) {
                        if (w1_block.data.ndim() != 4) {
                            throw std::runtime_error("left MPO blocks must be rank 4");
                        }
                        const auto& w1_key = w1_block.items;
                        py::array_t<cdouble> left_stack =
                            direct_left_stack(e_block.data, w1_block.data);
                        auto w2_it = w2_by_left_in.find(tuple_token(w1_key[1], p2_in));
                        if (w2_it == w2_by_left_in.end()) {
                            continue;
                        }
                        for (const auto& w2_block : w2_it->second) {
                            if (w2_block.data.ndim() != 4) {
                                throw std::runtime_error("right MPO blocks must be rank 4");
                            }
                            const auto& w2_key = w2_block.items;
                            auto f_it = f_by_mpo_ket_r.find(tuple_token(w2_key[1], right_qn));
                            if (f_it == f_by_mpo_ket_r.end()) {
                                continue;
                            }
                            for (const auto& f_block : f_it->second) {
                                if (f_block.data.ndim() != 3) {
                                    throw std::runtime_error("F blocks must be rank 3");
                                }
                                const auto& f_key = f_block.items;
                                py::object out_key = py::make_tuple(
                                    e_key[1],
                                    f_key[1],
                                    w1_key[2],
                                    w2_key[2]
                                );
                                auto out_it = layout.find(object_token(out_key));
                                if (out_it == layout.end()) {
                                    continue;
                                }
                                py::array_t<cdouble> right_stack =
                                    direct_right_stack(w2_block.data, f_block.data);
                                std::array<ssize_t, 8> dims = layout_dims(
                                    a_layout_it->second.shape,
                                    out_it->second.shape
                                );
                                const auto left = left_stack.unchecked<3>();
                                const auto right = right_stack.unchecked<3>();
                                if (
                                    left.shape(1) != dims[0] * dims[2]
                                    || left.shape(2) != dims[4] * dims[5]
                                    || right.shape(1) != dims[6] * dims[7]
                                    || right.shape(2) != dims[1] * dims[3]
                                    || left.shape(0) != right.shape(0)
                                ) {
                                    throw std::runtime_error(
                                        "named raw payload stack shapes do not match layout"
                                    );
                                }
                                builder.add_entry_unchecked(
                                    left_stack,
                                    right_stack,
                                    dims,
                                    a_layout_it->second.start,
                                    out_it->second.start,
                                    cdouble(1.0, 0.0)
                                );
                            }
                        }
                    }
                }
            }
        }
        return builder;
    }

    struct DirectComponentFields {
        py::object E;
        py::object W_left;
        py::object W_right;
        py::object F;
        std::string source;
    };

    struct DirectComponentItem {
        py::object component;
        std::string kind;
        cdouble coeff;
        std::shared_ptr<DirectComponentFields> fields = nullptr;
    };

    struct IdentityComponentKey {
        PyObject* e_ptr;
        PyObject* f_ptr;
        std::string source;

        bool operator==(const IdentityComponentKey& other) const {
            return e_ptr == other.e_ptr
                && f_ptr == other.f_ptr
                && source == other.source;
        }
    };

    struct IdentityComponentKeyHash {
        size_t operator()(const IdentityComponentKey& key) const {
            size_t value = std::hash<void*>{}(static_cast<void*>(key.e_ptr));
            value ^= std::hash<void*>{}(static_cast<void*>(key.f_ptr))
                + 0x9e3779b97f4a7c15ULL
                + (value << 6)
                + (value >> 2);
            value ^= std::hash<std::string>{}(key.source)
                + 0x9e3779b97f4a7c15ULL
                + (value << 6)
                + (value >> 2);
            return value;
        }
    };

