void CppMovingEnvironment::install_contextual_boundary_planner(
    const std::string& key,
    py::object shared_key_spec,
    ssize_t revision,
    py::object token,
    const std::string& side,
    ssize_t n_sites,
    ssize_t suffix_start
) {
    auto it = contextual_planner_records.find(key);
    if (it == contextual_planner_records.end()) {
        ContextualPlannerRecord record;
        record.shared_key_spec = shared_key_spec;
        record.token = token;
        record.side = side;
        record.revision = revision;
        record.n_sites = n_sites;
        record.suffix_start = suffix_start;
        contextual_planner_records.emplace(key, std::move(record));
    } else {
        ContextualPlannerRecord& record = it->second;
        if (
            record.shared_key_spec.ptr() != shared_key_spec.ptr() ||
            record.token.ptr() != token.ptr() ||
            record.side != side ||
            record.revision != revision ||
            record.n_sites != n_sites ||
            record.suffix_start != suffix_start
        ) {
            ++contextual_planner_replacements;
        }
        record.shared_key_spec = shared_key_spec;
        record.token = token;
        record.side = side;
        record.revision = revision;
        record.n_sites = n_sites;
        record.suffix_start = suffix_start;
    }
    ++contextual_planner_installs;
}

py::tuple CppMovingEnvironment::plan_contextual_boundary_wave(
    const std::string& key,
    py::sequence patterns,
    py::dict boundary_cache,
    py::set failed_boundaries
) {
    auto it = contextual_planner_records.find(key);
    if (it == contextual_planner_records.end()) {
        ++contextual_planner_failures;
        contextual_planner_last_error =
            "MovingEnvironment contextual planner record is absent";
        throw std::runtime_error(contextual_planner_last_error);
    }
    ContextualPlannerRecord& record = it->second;
    py::tuple result = contextual_prepare_boundary_build_wave(
        patterns,
        boundary_cache,
        record.shared_key_spec,
        record.revision,
        record.token,
        failed_boundaries,
        record.side,
        record.n_sites,
        record.suffix_start
    );
    ++contextual_planner_calls;
    if (py::len(result) >= 8) {
        py::sequence rows = py::reinterpret_borrow<py::sequence>(result[0]);
        contextual_planner_rows += static_cast<long long>(py::len(rows));
        contextual_planner_shared_hits += py::cast<long long>(result[1]);
        contextual_planner_cached += py::cast<long long>(result[2]);
        contextual_planner_deferred += py::cast<long long>(result[3]);
        contextual_planner_inherited_failures += py::cast<long long>(result[4]);
        contextual_planner_site_skips += py::cast<long long>(result[5]);
        contextual_planner_failed_skips += py::cast<long long>(result[6]);
        contextual_planner_closure += py::cast<long long>(result[7]);
    }
    contextual_planner_last_error.clear();
    return result;
}

