static py::object dict_get_required(py::dict data, const py::object& key) {
    PyObject* value = PyObject_GetItem(data.ptr(), key.ptr());
    if (value == nullptr) {
        throw py::error_already_set();
    }
    return py::reinterpret_steal<py::object>(value);
}

static py::object tensor_from_dict_like(
    py::object tensor_cls,
    py::dict data,
    py::object qns,
    py::object dirs
);

class CppAbelianTDVPSiteHeffPlan {
public:
    CppAbelianTDVPSiteHeffPlan() = default;

    static CppAbelianTDVPSiteHeffPlan from_tensors(
        py::object theta,
        py::object E,
        py::object W,
        py::object F
    ) {
        CppAbelianTDVPSiteHeffPlan plan;
        plan.build(theta, E, W, F);
        return plan;
    }

    py::dict apply_dict(
        py::object theta,
        py::object E,
        py::object W,
        py::object F
    ) const {
        py::dict theta_data = py::reinterpret_borrow<py::dict>(theta.attr("data"));
        py::dict e_data = py::reinterpret_borrow<py::dict>(E.attr("data"));
        py::dict w_data = py::reinterpret_borrow<py::dict>(W.attr("data"));
        py::dict f_data = py::reinterpret_borrow<py::dict>(F.attr("data"));
        py::dict out;
        for (const auto& route : routes_) {
            py::array_t<cdouble> block = tdvp_site_heff_contract_block(
                dict_get_required(e_data, route.e_key),
                dict_get_required(theta_data, route.theta_key),
                dict_get_required(w_data, route.w_key),
                dict_get_required(f_data, route.f_key)
            );
            add_block_to_output(out, route.out_key, block);
        }
        return out;
    }

    py::tuple apply(
        py::object theta,
        py::object E,
        py::object W,
        py::object F
    ) const {
        py::dict out = apply_dict(theta, E, W, F);
        py::tuple key_blocks = dict_items_to_key_block_tuple(out);
        return py::make_tuple(key_blocks[0], key_blocks[1], qns_, dirs_);
    }

    py::object apply_tensor(
        py::object tensor_cls,
        py::object theta,
        py::object E,
        py::object W,
        py::object F
    ) const {
        return tensor_from_dict_like(
            tensor_cls,
            apply_dict(theta, E, W, F),
            qns_,
            dirs_
        );
    }

    ssize_t route_count() const {
        return static_cast<ssize_t>(routes_.size());
    }

private:
    void build(py::object theta, py::object E, py::object W, py::object F) {
        py::dict theta_data = py::reinterpret_borrow<py::dict>(theta.attr("data"));
        py::dict e_data = py::reinterpret_borrow<py::dict>(E.attr("data"));
        py::dict w_data = py::reinterpret_borrow<py::dict>(W.attr("data"));
        py::dict f_data = py::reinterpret_borrow<py::dict>(F.attr("data"));
        py::dict theta_by_left;
        py::dict w_by_left_phys_in;
        py::dict f_by_mpo_right_ket;
        for (auto item : theta_data) {
            py::object key = py::reinterpret_borrow<py::object>(item.first);
            py::sequence seq = key.cast<py::sequence>();
            append_group(
                theta_by_left,
                py::reinterpret_borrow<py::object>(seq[0]),
                key
            );
        }
        for (auto item : w_data) {
            py::object key = py::reinterpret_borrow<py::object>(item.first);
            py::sequence seq = key.cast<py::sequence>();
            append_group(
                w_by_left_phys_in,
                py::make_tuple(
                    py::reinterpret_borrow<py::object>(seq[0]),
                    py::reinterpret_borrow<py::object>(seq[3])
                ),
                key
            );
        }
        for (auto item : f_data) {
            py::object key = py::reinterpret_borrow<py::object>(item.first);
            py::sequence seq = key.cast<py::sequence>();
            append_group(
                f_by_mpo_right_ket,
                py::make_tuple(
                    py::reinterpret_borrow<py::object>(seq[0]),
                    py::reinterpret_borrow<py::object>(seq[2])
                ),
                key
            );
        }

        for (auto item : e_data) {
            py::object e_key = py::reinterpret_borrow<py::object>(item.first);
            py::sequence e_seq = e_key.cast<py::sequence>();
            py::object theta_group_key = py::reinterpret_borrow<py::object>(e_seq[2]);
            if (!theta_by_left.contains(theta_group_key)) {
                continue;
            }
            py::sequence theta_group = py::reinterpret_borrow<py::sequence>(theta_by_left[theta_group_key]);
            for (ssize_t ti = 0; ti < static_cast<ssize_t>(py::len(theta_group)); ++ti) {
                py::object theta_key = py::reinterpret_borrow<py::object>(theta_group[ti]);
                py::sequence theta_seq = theta_key.cast<py::sequence>();
                py::object w_group_key = py::make_tuple(
                    py::reinterpret_borrow<py::object>(e_seq[0]),
                    py::reinterpret_borrow<py::object>(theta_seq[2])
                );
                if (!w_by_left_phys_in.contains(w_group_key)) {
                    continue;
                }
                py::sequence w_group = py::reinterpret_borrow<py::sequence>(w_by_left_phys_in[w_group_key]);
                for (ssize_t wi = 0; wi < static_cast<ssize_t>(py::len(w_group)); ++wi) {
                    py::object w_key = py::reinterpret_borrow<py::object>(w_group[wi]);
                    py::sequence w_seq = w_key.cast<py::sequence>();
                    py::object f_group_key = py::make_tuple(
                        py::reinterpret_borrow<py::object>(w_seq[1]),
                        py::reinterpret_borrow<py::object>(theta_seq[1])
                    );
                    if (!f_by_mpo_right_ket.contains(f_group_key)) {
                        continue;
                    }
                    py::sequence f_group = py::reinterpret_borrow<py::sequence>(f_by_mpo_right_ket[f_group_key]);
                    for (ssize_t fi = 0; fi < static_cast<ssize_t>(py::len(f_group)); ++fi) {
                        py::object f_key = py::reinterpret_borrow<py::object>(f_group[fi]);
                        py::sequence f_seq = f_key.cast<py::sequence>();
                        routes_.push_back(
                            AbelianTDVPSiteHeffRoute{
                                e_key,
                                theta_key,
                                w_key,
                                f_key,
                                py::make_tuple(
                                    py::reinterpret_borrow<py::object>(e_seq[1]),
                                    py::reinterpret_borrow<py::object>(f_seq[1]),
                                    py::reinterpret_borrow<py::object>(w_seq[2])
                                )
                            }
                        );
                    }
                }
            }
        }
        py::list dirs;
        dirs.append(get_axis_item(E.attr("dirs"), 1));
        dirs.append(get_axis_item(F.attr("dirs"), 1));
        dirs.append(get_axis_item(W.attr("dirs"), 2));
        dirs_ = tuple_from_sequence_object(dirs);
        py::list qns;
        qns.append(get_axis_item(E.attr("qns"), 1));
        qns.append(get_axis_item(F.attr("qns"), 1));
        qns.append(get_axis_item(W.attr("qns"), 2));
        qns_ = tuple_from_sequence_object(qns);
    }

    std::vector<AbelianTDVPSiteHeffRoute> routes_;
    py::object qns_ = py::none();
    py::object dirs_ = py::none();
};

class CppAbelianTDVPBondHeffPlan {
public:
    CppAbelianTDVPBondHeffPlan() = default;

    static CppAbelianTDVPBondHeffPlan from_tensors(
        py::object center,
        py::object E,
        py::object F
    ) {
        CppAbelianTDVPBondHeffPlan plan;
        plan.build(center, E, F);
        return plan;
    }

    py::dict apply_dict(py::object center, py::object E, py::object F) const {
        py::dict center_data = py::reinterpret_borrow<py::dict>(center.attr("data"));
        py::dict e_data = py::reinterpret_borrow<py::dict>(E.attr("data"));
        py::dict f_data = py::reinterpret_borrow<py::dict>(F.attr("data"));
        py::dict out;
        for (const auto& route : routes_) {
            py::array_t<cdouble> block = tdvp_bond_heff_contract_block(
                dict_get_required(e_data, route.e_key),
                dict_get_required(center_data, route.center_key),
                dict_get_required(f_data, route.f_key)
            );
            add_block2_to_output(out, route.out_key, block);
        }
        return out;
    }

    py::tuple apply(py::object center, py::object E, py::object F) const {
        py::dict out = apply_dict(center, E, F);
        py::tuple key_blocks = dict_items_to_key_block_tuple(out);
        return py::make_tuple(key_blocks[0], key_blocks[1], qns_, dirs_);
    }

    py::object apply_tensor(
        py::object tensor_cls,
        py::object center,
        py::object E,
        py::object F
    ) const {
        return tensor_from_dict_like(
            tensor_cls,
            apply_dict(center, E, F),
            qns_,
            dirs_
        );
    }

    ssize_t route_count() const {
        return static_cast<ssize_t>(routes_.size());
    }

private:
    void build(py::object center, py::object E, py::object F) {
        py::dict center_data = py::reinterpret_borrow<py::dict>(center.attr("data"));
        py::dict e_data = py::reinterpret_borrow<py::dict>(E.attr("data"));
        py::dict f_data = py::reinterpret_borrow<py::dict>(F.attr("data"));
        py::dict center_by_left;
        py::dict f_by_mpo_right_ket;
        for (auto item : center_data) {
            py::object key = py::reinterpret_borrow<py::object>(item.first);
            py::sequence seq = key.cast<py::sequence>();
            append_group(
                center_by_left,
                py::reinterpret_borrow<py::object>(seq[0]),
                key
            );
        }
        for (auto item : f_data) {
            py::object key = py::reinterpret_borrow<py::object>(item.first);
            py::sequence seq = key.cast<py::sequence>();
            append_group(
                f_by_mpo_right_ket,
                py::make_tuple(
                    py::reinterpret_borrow<py::object>(seq[0]),
                    py::reinterpret_borrow<py::object>(seq[2])
                ),
                key
            );
        }

        for (auto item : e_data) {
            py::object e_key = py::reinterpret_borrow<py::object>(item.first);
            py::sequence e_seq = e_key.cast<py::sequence>();
            py::object center_group_key = py::reinterpret_borrow<py::object>(e_seq[2]);
            if (!center_by_left.contains(center_group_key)) {
                continue;
            }
            py::sequence center_group = py::reinterpret_borrow<py::sequence>(center_by_left[center_group_key]);
            for (ssize_t ci = 0; ci < static_cast<ssize_t>(py::len(center_group)); ++ci) {
                py::object center_key = py::reinterpret_borrow<py::object>(center_group[ci]);
                py::sequence center_seq = center_key.cast<py::sequence>();
                py::object f_group_key = py::make_tuple(
                    py::reinterpret_borrow<py::object>(e_seq[0]),
                    py::reinterpret_borrow<py::object>(center_seq[1])
                );
                if (!f_by_mpo_right_ket.contains(f_group_key)) {
                    continue;
                }
                py::sequence f_group = py::reinterpret_borrow<py::sequence>(f_by_mpo_right_ket[f_group_key]);
                for (ssize_t fi = 0; fi < static_cast<ssize_t>(py::len(f_group)); ++fi) {
                    py::object f_key = py::reinterpret_borrow<py::object>(f_group[fi]);
                    py::sequence f_seq = f_key.cast<py::sequence>();
                    routes_.push_back(
                        AbelianTDVPBondHeffRoute{
                            e_key,
                            center_key,
                            f_key,
                            py::make_tuple(
                                py::reinterpret_borrow<py::object>(e_seq[1]),
                                py::reinterpret_borrow<py::object>(f_seq[1])
                            )
                        }
                    );
                }
            }
        }
        py::list dirs;
        dirs.append(get_axis_item(E.attr("dirs"), 1));
        dirs.append(get_axis_item(F.attr("dirs"), 1));
        dirs_ = tuple_from_sequence_object(dirs);
        py::list qns;
        qns.append(get_axis_item(E.attr("qns"), 1));
        qns.append(get_axis_item(F.attr("qns"), 1));
        qns_ = tuple_from_sequence_object(qns);
    }

    std::vector<AbelianTDVPBondHeffRoute> routes_;
    py::object qns_ = py::none();
    py::object dirs_ = py::none();
};

class CppAbelianEnvironmentAdvancePlan {
public:
    CppAbelianEnvironmentAdvancePlan() = default;

    static CppAbelianEnvironmentAdvancePlan from_left(
        py::object W,
        py::object A,
        py::object E,
        py::object B
    ) {
        CppAbelianEnvironmentAdvancePlan plan;
        plan.left_ = true;
        plan.build_left(W, A, E, B);
        return plan;
    }

    static CppAbelianEnvironmentAdvancePlan from_right(
        py::object W,
        py::object A,
        py::object F,
        py::object B
    ) {
        CppAbelianEnvironmentAdvancePlan plan;
        plan.left_ = false;
        plan.build_right(W, A, F, B);
        return plan;
    }

    py::tuple advance(
        py::object W,
        py::object A,
        py::object env,
        py::object B
    ) const {
        py::dict env_data = py::reinterpret_borrow<py::dict>(env.attr("data"));
        py::dict a_data = py::reinterpret_borrow<py::dict>(A.attr("data"));
        py::dict w_data = py::reinterpret_borrow<py::dict>(W.attr("data"));
        py::dict b_data = py::reinterpret_borrow<py::dict>(B.attr("data"));
        py::dict out;
        for (const auto& route : routes_) {
            py::object env_block = dict_get_required(env_data, route.env_key);
            py::object a_block = dict_get_required(a_data, route.a_key);
            py::object w_block = dict_get_required(w_data, route.w_key);
            py::object b_block = dict_get_required(b_data, route.b_key);
            py::array_t<cdouble> block;
            if (left_) {
                block = left_environment_contract_block(
                    env_block,
                    a_block,
                    w_block,
                    b_block
                );
            } else {
                block = right_environment_contract_block(
                    a_block,
                    env_block,
                    w_block,
                    b_block
                );
            }
            add_block_to_output(out, route.out_key, block);
        }
        py::tuple key_blocks = dict_items_to_key_block_tuple(out);
        return py::make_tuple(key_blocks[0], key_blocks[1], qns_, dirs_);
    }

    ssize_t route_count() const {
        return static_cast<ssize_t>(routes_.size());
    }

    std::string direction() const {
        return left_ ? "left" : "right";
    }

private:
    void build_left(py::object W, py::object A, py::object E, py::object B) {
        py::dict e_data = py::reinterpret_borrow<py::dict>(E.attr("data"));
        py::dict a_data = py::reinterpret_borrow<py::dict>(A.attr("data"));
        py::dict w_data = py::reinterpret_borrow<py::dict>(W.attr("data"));
        py::dict b_data = py::reinterpret_borrow<py::dict>(B.attr("data"));
        py::dict a_by_left;
        py::dict w_by_left_phys;
        py::dict b_by_left_phys;
        for (auto item : a_data) {
            py::object key = py::reinterpret_borrow<py::object>(item.first);
            py::sequence seq = key.cast<py::sequence>();
            append_group(
                a_by_left,
                py::reinterpret_borrow<py::object>(seq[0]),
                key
            );
        }
        for (auto item : w_data) {
            py::object key = py::reinterpret_borrow<py::object>(item.first);
            py::sequence seq = key.cast<py::sequence>();
            append_group(
                w_by_left_phys,
                py::make_tuple(
                    py::reinterpret_borrow<py::object>(seq[0]),
                    py::reinterpret_borrow<py::object>(seq[2])
                ),
                key
            );
        }
        for (auto item : b_data) {
            py::object key = py::reinterpret_borrow<py::object>(item.first);
            py::sequence seq = key.cast<py::sequence>();
            append_group(
                b_by_left_phys,
                py::make_tuple(
                    py::reinterpret_borrow<py::object>(seq[0]),
                    py::reinterpret_borrow<py::object>(seq[2])
                ),
                key
            );
        }
        for (auto item : e_data) {
            py::object e_key = py::reinterpret_borrow<py::object>(item.first);
            py::sequence e_seq = e_key.cast<py::sequence>();
            py::object a_group_key = py::reinterpret_borrow<py::object>(e_seq[1]);
            if (!a_by_left.contains(a_group_key)) {
                continue;
            }
            py::sequence a_group = py::reinterpret_borrow<py::sequence>(a_by_left[a_group_key]);
            for (ssize_t ai = 0; ai < static_cast<ssize_t>(py::len(a_group)); ++ai) {
                py::object a_key = py::reinterpret_borrow<py::object>(a_group[ai]);
                py::sequence a_seq = a_key.cast<py::sequence>();
                py::object w_group_key = py::make_tuple(
                    py::reinterpret_borrow<py::object>(e_seq[0]),
                    py::reinterpret_borrow<py::object>(a_seq[2])
                );
                if (!w_by_left_phys.contains(w_group_key)) {
                    continue;
                }
                py::sequence w_group = py::reinterpret_borrow<py::sequence>(w_by_left_phys[w_group_key]);
                for (ssize_t wi = 0; wi < static_cast<ssize_t>(py::len(w_group)); ++wi) {
                    py::object w_key = py::reinterpret_borrow<py::object>(w_group[wi]);
                    py::sequence w_seq = w_key.cast<py::sequence>();
                    py::object b_group_key = py::make_tuple(
                        py::reinterpret_borrow<py::object>(e_seq[2]),
                        py::reinterpret_borrow<py::object>(w_seq[3])
                    );
                    if (!b_by_left_phys.contains(b_group_key)) {
                        continue;
                    }
                    py::sequence b_group = py::reinterpret_borrow<py::sequence>(b_by_left_phys[b_group_key]);
                    for (ssize_t bi = 0; bi < static_cast<ssize_t>(py::len(b_group)); ++bi) {
                        py::object b_key = py::reinterpret_borrow<py::object>(b_group[bi]);
                        py::sequence b_seq = b_key.cast<py::sequence>();
                        routes_.push_back(
                            AbelianEnvironmentAdvanceRoute{
                                e_key,
                                a_key,
                                w_key,
                                b_key,
                                py::make_tuple(
                                    py::reinterpret_borrow<py::object>(w_seq[1]),
                                    py::reinterpret_borrow<py::object>(a_seq[1]),
                                    py::reinterpret_borrow<py::object>(b_seq[1])
                                )
                            }
                        );
                    }
                }
            }
        }
        py::list dirs;
        dirs.append(get_axis_item(W.attr("dirs"), 1));
        dirs.append(neg_axis_item(A.attr("dirs"), 1));
        dirs.append(get_axis_item(B.attr("dirs"), 1));
        dirs_ = tuple_from_sequence_object(dirs);
        py::list qns;
        qns.append(get_axis_item(W.attr("qns"), 1));
        qns.append(get_axis_item(A.attr("qns"), 1));
        qns.append(get_axis_item(B.attr("qns"), 1));
        qns_ = tuple_from_sequence_object(qns);
    }

    void build_right(py::object W, py::object A, py::object F, py::object B) {
        py::dict f_data = py::reinterpret_borrow<py::dict>(F.attr("data"));
        py::dict a_data = py::reinterpret_borrow<py::dict>(A.attr("data"));
        py::dict w_data = py::reinterpret_borrow<py::dict>(W.attr("data"));
        py::dict b_data = py::reinterpret_borrow<py::dict>(B.attr("data"));
        py::dict a_by_right;
        py::dict w_by_right_phys;
        py::dict b_by_right_phys;
        for (auto item : a_data) {
            py::object key = py::reinterpret_borrow<py::object>(item.first);
            py::sequence seq = key.cast<py::sequence>();
            append_group(
                a_by_right,
                py::reinterpret_borrow<py::object>(seq[1]),
                key
            );
        }
        for (auto item : w_data) {
            py::object key = py::reinterpret_borrow<py::object>(item.first);
            py::sequence seq = key.cast<py::sequence>();
            append_group(
                w_by_right_phys,
                py::make_tuple(
                    py::reinterpret_borrow<py::object>(seq[1]),
                    py::reinterpret_borrow<py::object>(seq[2])
                ),
                key
            );
        }
        for (auto item : b_data) {
            py::object key = py::reinterpret_borrow<py::object>(item.first);
            py::sequence seq = key.cast<py::sequence>();
            append_group(
                b_by_right_phys,
                py::make_tuple(
                    py::reinterpret_borrow<py::object>(seq[1]),
                    py::reinterpret_borrow<py::object>(seq[2])
                ),
                key
            );
        }
        for (auto item : f_data) {
            py::object f_key = py::reinterpret_borrow<py::object>(item.first);
            py::sequence f_seq = f_key.cast<py::sequence>();
            py::object a_group_key = py::reinterpret_borrow<py::object>(f_seq[1]);
            if (!a_by_right.contains(a_group_key)) {
                continue;
            }
            py::sequence a_group = py::reinterpret_borrow<py::sequence>(a_by_right[a_group_key]);
            for (ssize_t ai = 0; ai < static_cast<ssize_t>(py::len(a_group)); ++ai) {
                py::object a_key = py::reinterpret_borrow<py::object>(a_group[ai]);
                py::sequence a_seq = a_key.cast<py::sequence>();
                py::object w_group_key = py::make_tuple(
                    py::reinterpret_borrow<py::object>(f_seq[0]),
                    py::reinterpret_borrow<py::object>(a_seq[2])
                );
                if (!w_by_right_phys.contains(w_group_key)) {
                    continue;
                }
                py::sequence w_group = py::reinterpret_borrow<py::sequence>(w_by_right_phys[w_group_key]);
                for (ssize_t wi = 0; wi < static_cast<ssize_t>(py::len(w_group)); ++wi) {
                    py::object w_key = py::reinterpret_borrow<py::object>(w_group[wi]);
                    py::sequence w_seq = w_key.cast<py::sequence>();
                    py::object b_group_key = py::make_tuple(
                        py::reinterpret_borrow<py::object>(f_seq[2]),
                        py::reinterpret_borrow<py::object>(w_seq[3])
                    );
                    if (!b_by_right_phys.contains(b_group_key)) {
                        continue;
                    }
                    py::sequence b_group = py::reinterpret_borrow<py::sequence>(b_by_right_phys[b_group_key]);
                    for (ssize_t bi = 0; bi < static_cast<ssize_t>(py::len(b_group)); ++bi) {
                        py::object b_key = py::reinterpret_borrow<py::object>(b_group[bi]);
                        py::sequence b_seq = b_key.cast<py::sequence>();
                        routes_.push_back(
                            AbelianEnvironmentAdvanceRoute{
                                f_key,
                                a_key,
                                w_key,
                                b_key,
                                py::make_tuple(
                                    py::reinterpret_borrow<py::object>(w_seq[0]),
                                    py::reinterpret_borrow<py::object>(a_seq[0]),
                                    py::reinterpret_borrow<py::object>(b_seq[0])
                                )
                            }
                        );
                    }
                }
            }
        }
        py::list dirs;
        dirs.append(get_axis_item(W.attr("dirs"), 0));
        dirs.append(neg_axis_item(A.attr("dirs"), 0));
        dirs.append(get_axis_item(B.attr("dirs"), 0));
        dirs_ = tuple_from_sequence_object(dirs);
        py::list qns;
        qns.append(get_axis_item(W.attr("qns"), 0));
        qns.append(get_axis_item(A.attr("qns"), 0));
        qns.append(get_axis_item(B.attr("qns"), 0));
        qns_ = tuple_from_sequence_object(qns);
    }

    bool left_ = true;
    std::vector<AbelianEnvironmentAdvanceRoute> routes_;
    py::object qns_ = py::none();
    py::object dirs_ = py::none();
};

py::tuple CppMovingEnvironment::environment_advance(
    const std::string& key,
    const std::string& direction,
    py::object W,
    py::object A,
    py::object env,
    py::object B,
    const std::string& signature
) {
    const bool left = direction == "left";
    if (!left && direction != "right") {
        ++environment_plan_failures;
        environment_plan_last_error = "environment advance direction must be left or right";
        throw std::runtime_error(environment_plan_last_error);
    }
    try {
        auto it = environment_plan_records.find(key);
        if (
            it == environment_plan_records.end()
            || it->second.left != left
            || it->second.signature != signature
        ) {
            if (it != environment_plan_records.end()) {
                ++environment_plan_replacements;
                environment_plan_records.erase(it);
            }
            const double build_start = wall_seconds();
            CppAbelianEnvironmentAdvancePlan plan_value =
                left
                    ? CppAbelianEnvironmentAdvancePlan::from_left(W, A, env, B)
                    : CppAbelianEnvironmentAdvancePlan::from_right(W, A, env, B);
            EnvironmentPlanRecord record;
            record.owner = py::cast(std::move(plan_value));
            record.signature = signature;
            record.left = left;
            CppAbelianEnvironmentAdvancePlan* plan =
                record.owner.cast<CppAbelianEnvironmentAdvancePlan*>();
            record.routes = plan == nullptr ? 0 : plan->route_count();
            environment_plan_last_routes = record.routes;
            environment_plan_records.emplace(key, std::move(record));
            ++environment_plan_builds;
            environment_plan_build_seconds += wall_seconds() - build_start;
            it = environment_plan_records.find(key);
        } else {
            ++environment_plan_cache_hits;
        }
        CppAbelianEnvironmentAdvancePlan* plan =
            it->second.owner.cast<CppAbelianEnvironmentAdvancePlan*>();
        if (plan == nullptr) {
            throw std::runtime_error("MovingEnvironment environment plan record is empty");
        }
        const double advance_start = wall_seconds();
        py::tuple result = plan->advance(W, A, env, B);
        environment_plan_advance_seconds += wall_seconds() - advance_start;
        try {
            py::sequence keys = py::reinterpret_borrow<py::sequence>(result[0]);
            environment_plan_last_blocks = static_cast<ssize_t>(py::len(keys));
        } catch (...) {
            environment_plan_last_blocks = 0;
        }
        ++environment_plan_advance_calls;
        return result;
    } catch (const std::exception& exc) {
        ++environment_plan_failures;
        environment_plan_last_error = exc.what();
        throw;
    }
}

static py::object environment_tensor_from_payload(
    py::object tensor_cls,
    py::tuple payload
) {
    py::sequence seq = payload.cast<py::sequence>();
    py::sequence keys = py::reinterpret_borrow<py::object>(seq[0])
                            .cast<py::sequence>();
    py::sequence blocks = py::reinterpret_borrow<py::object>(seq[1])
                              .cast<py::sequence>();
    py::object qns = py::reinterpret_borrow<py::object>(seq[2]);
    py::object dirs = py::reinterpret_borrow<py::object>(seq[3]);
    py::dict data;
    const ssize_t n = static_cast<ssize_t>(py::len(keys));
    for (ssize_t idx = 0; idx < n; ++idx) {
        data[tuple_from_sequence_object(
            py::reinterpret_borrow<py::object>(keys[idx])
        )] = py::reinterpret_borrow<py::object>(blocks[idx]);
    }
    return tensor_cls(
        data,
        qns,
        dirs,
        py::arg("copy") = false
    );
}

static py::object tensor_from_dict_like(
    py::object tensor_cls,
    py::dict data,
    py::object qns,
    py::object dirs
) {
    return tensor_cls(
        data,
        qns,
        dirs,
        py::arg("copy") = false
    );
}

static py::object tensor_from_payload_like(
    py::object tensor_cls,
    py::tuple payload
) {
    py::sequence seq = payload.cast<py::sequence>();
    py::sequence keys = py::reinterpret_borrow<py::object>(seq[0])
                            .cast<py::sequence>();
    py::sequence blocks = py::reinterpret_borrow<py::object>(seq[1])
                              .cast<py::sequence>();
    py::object qns = py::reinterpret_borrow<py::object>(seq[2]);
    py::object dirs = py::reinterpret_borrow<py::object>(seq[3]);
    py::dict data;
    const ssize_t n = static_cast<ssize_t>(py::len(keys));
    for (ssize_t idx = 0; idx < n; ++idx) {
        data[tuple_from_sequence_object(
            py::reinterpret_borrow<py::object>(keys[idx])
        )] = py::reinterpret_borrow<py::object>(blocks[idx]);
    }
    return tensor_from_dict_like(tensor_cls, data, qns, dirs);
}

static py::object tensor_class_of(py::object tensor) {
    return py::reinterpret_borrow<py::object>(tensor.attr("__class__"));
}

static std::string normalized_method_key(const std::string& method) {
    std::string key;
    key.reserve(method.size());
    for (unsigned char c : method) {
        key.push_back(c == '_' ? '-' : static_cast<char>(std::tolower(c)));
    }
    return key;
}

static bool py_objects_equal(py::handle lhs, py::handle rhs) {
    int result = PyObject_RichCompareBool(lhs.ptr(), rhs.ptr(), Py_EQ);
    if (result < 0) {
        throw py::error_already_set();
    }
    return result == 1;
}

static cdouble block_tensor_dot_native(py::object bra, py::object ket) {
    py::dict bra_data = py::reinterpret_borrow<py::dict>(bra.attr("data"));
    py::dict ket_data = py::reinterpret_borrow<py::dict>(ket.attr("data"));
    cdouble total = 0.0;
    for (auto item : bra_data) {
        py::object key = py::reinterpret_borrow<py::object>(item.first);
        if (!ket_data.contains(key)) {
            continue;
        }
        auto a = ensure_cdouble_array(py::reinterpret_borrow<py::object>(item.second));
        auto b = ensure_cdouble_array(py::reinterpret_borrow<py::object>(ket_data[key]));
        if (a.ndim() != b.ndim()) {
            throw std::runtime_error("block tensor dot rank mismatch");
        }
        ssize_t size = 1;
        for (ssize_t axis = 0; axis < a.ndim(); ++axis) {
            if (a.shape(axis) != b.shape(axis)) {
                throw std::runtime_error("block tensor dot shape mismatch");
            }
            size *= a.shape(axis);
        }
        py::buffer_info ai = a.request();
        py::buffer_info bi = b.request();
        const cdouble* ap = static_cast<const cdouble*>(ai.ptr);
        const cdouble* bp = static_cast<const cdouble*>(bi.ptr);
        for (ssize_t idx = 0; idx < size; ++idx) {
            total += std::conj(ap[idx]) * bp[idx];
        }
    }
    return total;
}

static double block_tensor_norm_native(py::object tensor) {
    py::dict data = py::reinterpret_borrow<py::dict>(tensor.attr("data"));
    double n2 = 0.0;
    for (auto item : data) {
        auto block = ensure_cdouble_array(py::reinterpret_borrow<py::object>(item.second));
        ssize_t size = 1;
        for (ssize_t axis = 0; axis < block.ndim(); ++axis) {
            size *= block.shape(axis);
        }
        py::buffer_info bi = block.request();
        const cdouble* bp = static_cast<const cdouble*>(bi.ptr);
        for (ssize_t idx = 0; idx < size; ++idx) {
            n2 += std::norm(bp[idx]);
        }
    }
    return std::sqrt(std::max(0.0, n2));
}

static py::array_t<cdouble> scale_array_like(py::object block_obj, cdouble coeff) {
    auto block = ensure_cdouble_array(block_obj);
    std::vector<ssize_t> shape;
    ssize_t size = 1;
    for (ssize_t axis = 0; axis < block.ndim(); ++axis) {
        shape.push_back(block.shape(axis));
        size *= block.shape(axis);
    }
    py::array_t<cdouble> out(shape);
    py::buffer_info bi = block.request();
    py::buffer_info oi = out.request();
    const cdouble* bp = static_cast<const cdouble*>(bi.ptr);
    cdouble* op = static_cast<cdouble*>(oi.ptr);
    for (ssize_t idx = 0; idx < size; ++idx) {
        op[idx] = coeff * bp[idx];
    }
    return out;
}

static void add_scaled_array_inplace(
    py::object dst_obj,
    py::object src_obj,
    cdouble coeff,
    const char* context
) {
    auto dst = ensure_cdouble_array(dst_obj);
    auto src = ensure_cdouble_array(src_obj);
    if (dst.ndim() != src.ndim()) {
        throw std::runtime_error(std::string(context) + " rank mismatch");
    }
    ssize_t size = 1;
    for (ssize_t axis = 0; axis < dst.ndim(); ++axis) {
        if (dst.shape(axis) != src.shape(axis)) {
            throw std::runtime_error(std::string(context) + " shape mismatch");
        }
        size *= dst.shape(axis);
    }
    py::buffer_info di = dst.request();
    py::buffer_info si = src.request();
    cdouble* dp = static_cast<cdouble*>(di.ptr);
    const cdouble* sp = static_cast<const cdouble*>(si.ptr);
    for (ssize_t idx = 0; idx < size; ++idx) {
        dp[idx] += coeff * sp[idx];
    }
}

static py::object block_tensor_scaled_native(
    py::object tensor,
    cdouble coeff,
    py::object tensor_cls = py::none()
) {
    if (tensor_cls.is_none()) {
        tensor_cls = tensor_class_of(tensor);
    }
    py::dict data = py::reinterpret_borrow<py::dict>(tensor.attr("data"));
    py::dict out;
    for (auto item : data) {
        out[py::reinterpret_borrow<py::object>(item.first)] =
            scale_array_like(py::reinterpret_borrow<py::object>(item.second), coeff);
    }
    return tensor_from_dict_like(
        tensor_cls,
        out,
        py::reinterpret_borrow<py::object>(tensor.attr("qns")),
        py::reinterpret_borrow<py::object>(tensor.attr("dirs"))
    );
}

static py::object block_tensor_add_scaled_native(
    py::object lhs,
    py::object rhs,
    cdouble rhs_coeff,
    py::object tensor_cls = py::none()
) {
    if (tensor_cls.is_none()) {
        tensor_cls = tensor_class_of(lhs);
    }
    py::dict lhs_data = py::reinterpret_borrow<py::dict>(lhs.attr("data"));
    py::dict rhs_data = py::reinterpret_borrow<py::dict>(rhs.attr("data"));
    py::dict out;
    for (auto item : lhs_data) {
        out[py::reinterpret_borrow<py::object>(item.first)] =
            scale_array_like(py::reinterpret_borrow<py::object>(item.second), 1.0);
    }
    for (auto item : rhs_data) {
        py::object key = py::reinterpret_borrow<py::object>(item.first);
        if (!out.contains(key)) {
            out[key] = scale_array_like(
                py::reinterpret_borrow<py::object>(item.second),
                rhs_coeff
            );
            continue;
        }
        add_scaled_array_inplace(
            py::reinterpret_borrow<py::object>(out[key]),
            py::reinterpret_borrow<py::object>(item.second),
            rhs_coeff,
            "block tensor add"
        );
    }
    return tensor_from_dict_like(
        tensor_cls,
        out,
        py::reinterpret_borrow<py::object>(lhs.attr("qns")),
        py::reinterpret_borrow<py::object>(lhs.attr("dirs"))
    );
}

static py::object block_tensor_add_scaled_inplace(
    py::object lhs,
    py::object rhs,
    cdouble rhs_coeff
) {
    if (std::abs(rhs_coeff) <= 0.0) {
        return lhs;
    }
    py::dict lhs_data = py::reinterpret_borrow<py::dict>(lhs.attr("data"));
    py::dict rhs_data = py::reinterpret_borrow<py::dict>(rhs.attr("data"));
    for (auto item : rhs_data) {
        py::object key = py::reinterpret_borrow<py::object>(item.first);
        if (!lhs_data.contains(key)) {
            lhs_data[key] = scale_array_like(
                py::reinterpret_borrow<py::object>(item.second),
                rhs_coeff
            );
            continue;
        }
        add_scaled_array_inplace(
            py::reinterpret_borrow<py::object>(lhs_data[key]),
            py::reinterpret_borrow<py::object>(item.second),
            rhs_coeff,
            "block tensor inplace add"
        );
    }
    return lhs;
}

static py::object block_tensor_linear_combination_native(
    const std::vector<cdouble>& coeffs,
    const std::vector<py::object>& basis,
    py::object tensor_cls = py::none()
) {
    if (basis.empty()) {
        throw std::runtime_error("block tensor linear combination needs a non-empty basis");
    }
    if (tensor_cls.is_none()) {
        tensor_cls = tensor_class_of(basis.front());
    }
    py::dict out;
    for (size_t bi = 0; bi < basis.size(); ++bi) {
        const cdouble coeff = coeffs[bi];
        if (std::abs(coeff) <= 0.0) {
            continue;
        }
        py::dict data = py::reinterpret_borrow<py::dict>(basis[bi].attr("data"));
        for (auto item : data) {
            py::object key = py::reinterpret_borrow<py::object>(item.first);
            if (!out.contains(key)) {
                out[key] = scale_array_like(
                    py::reinterpret_borrow<py::object>(item.second),
                    coeff
                );
                continue;
            }
            add_scaled_array_inplace(
                py::reinterpret_borrow<py::object>(out[key]),
                py::reinterpret_borrow<py::object>(item.second),
                coeff,
                "block tensor linear combination"
            );
        }
    }
    if (py::len(out) == 0) {
        return block_tensor_scaled_native(basis.front(), 0.0, tensor_cls);
    }
    return tensor_from_dict_like(
        tensor_cls,
        out,
        py::reinterpret_borrow<py::object>(basis.front().attr("qns")),
        py::reinterpret_borrow<py::object>(basis.front().attr("dirs"))
    );
}

static py::object block_left_qr_native(py::object theta, py::object tensor_cls) {
    py::dict theta_data = py::reinterpret_borrow<py::dict>(theta.attr("data"));
    py::dict by_right;
    for (auto item : theta_data) {
        py::object key = py::reinterpret_borrow<py::object>(item.first);
        py::sequence seq = key.cast<py::sequence>();
        py::object q_right = py::reinterpret_borrow<py::object>(seq[1]);
        if (!by_right.contains(q_right)) {
            by_right[q_right] = py::list();
        }
        by_right[q_right].attr("append")(key);
    }

    py::dict data_q;
    py::dict data_center;
    py::list new_right_qns;
    for (auto group_item : by_right) {
        py::object q_right = py::reinterpret_borrow<py::object>(group_item.first);
        py::sequence keys = py::reinterpret_borrow<py::sequence>(group_item.second);
        ssize_t cols = -1;
        ssize_t rows_total = 0;
        struct Entry { py::object key; py::array_t<cdouble> block; ssize_t left_dim; ssize_t phys_dim; };
        std::vector<Entry> entries;
        for (ssize_t idx = 0; idx < static_cast<ssize_t>(py::len(keys)); ++idx) {
            py::object key = py::reinterpret_borrow<py::object>(keys[idx]);
            auto block = ensure_cdouble_array(py::reinterpret_borrow<py::object>(theta_data[key]));
            if (block.ndim() != 3) {
                throw std::runtime_error("block left QR expects rank-3 site blocks");
            }
            const ssize_t left_dim = block.shape(0);
            const ssize_t right_dim = block.shape(1);
            const ssize_t phys_dim = block.shape(2);
            if (cols < 0) {
                cols = right_dim;
            } else if (cols != right_dim) {
                throw std::runtime_error("Inconsistent right-sector degeneracy in block QR");
            }
            rows_total += left_dim * phys_dim;
            entries.push_back(Entry{key, block, left_dim, phys_dim});
        }
        if (cols <= 0) {
            continue;
        }
        py::array_t<cdouble> mat({rows_total, cols});
        auto mv = mat.mutable_unchecked<2>();
        ssize_t offset = 0;
        for (const auto& entry : entries) {
            auto bv = entry.block.unchecked<3>();
            for (ssize_t l = 0; l < entry.left_dim; ++l) {
                for (ssize_t p = 0; p < entry.phys_dim; ++p) {
                    const ssize_t row = offset + l * entry.phys_dim + p;
                    for (ssize_t r = 0; r < cols; ++r) {
                        mv(row, r) = bv(l, r, p);
                    }
                }
            }
            offset += entry.left_dim * entry.phys_dim;
        }
        py::tuple qr = lapack_qr(mat);
        auto q_mat = qr[0].cast<py::array_t<cdouble>>();
        auto r_mat = qr[1].cast<py::array_t<cdouble>>();
        const ssize_t chi = q_mat.shape(1);
        if (chi == 0) {
            continue;
        }
        new_right_qns.append(q_right);
        data_center[py::make_tuple(q_right, q_right)] = r_mat;
        auto qv = q_mat.unchecked<2>();
        offset = 0;
        for (const auto& entry : entries) {
            py::sequence key_seq = entry.key.cast<py::sequence>();
            py::object out_key = py::make_tuple(
                py::reinterpret_borrow<py::object>(key_seq[0]),
                q_right,
                py::reinterpret_borrow<py::object>(key_seq[2])
            );
            py::array_t<cdouble> q_block({entry.left_dim, chi, entry.phys_dim});
            auto qb = q_block.mutable_unchecked<3>();
            for (ssize_t l = 0; l < entry.left_dim; ++l) {
                for (ssize_t c = 0; c < chi; ++c) {
                    for (ssize_t p = 0; p < entry.phys_dim; ++p) {
                        qb(l, c, p) = qv(offset + l * entry.phys_dim + p, c);
                    }
                }
            }
            data_q[out_key] = q_block;
            offset += entry.left_dim * entry.phys_dim;
        }
    }
    py::list q_qns;
    q_qns.append(get_axis_item(theta.attr("qns"), 0));
    q_qns.append(tuple_from_sequence_object(new_right_qns));
    q_qns.append(get_axis_item(theta.attr("qns"), 2));
    py::list center_qns;
    center_qns.append(tuple_from_sequence_object(new_right_qns));
    center_qns.append(get_axis_item(theta.attr("qns"), 1));
    py::list center_dirs;
    center_dirs.append(py::int_(-1));
    center_dirs.append(py::int_(1));
    return py::make_tuple(
        tensor_from_dict_like(tensor_cls, data_q, tuple_from_sequence_object(q_qns), theta.attr("dirs")),
        tensor_from_dict_like(tensor_cls, data_center, tuple_from_sequence_object(center_qns), tuple_from_sequence_object(center_dirs))
    );
}

static py::object block_right_rq_native(py::object theta, py::object tensor_cls) {
    py::dict theta_data = py::reinterpret_borrow<py::dict>(theta.attr("data"));
    py::dict by_left;
    for (auto item : theta_data) {
        py::object key = py::reinterpret_borrow<py::object>(item.first);
        py::sequence seq = key.cast<py::sequence>();
        py::object q_left = py::reinterpret_borrow<py::object>(seq[0]);
        if (!by_left.contains(q_left)) {
            by_left[q_left] = py::list();
        }
        by_left[q_left].attr("append")(key);
    }

    py::dict data_q;
    py::dict data_center;
    py::list new_left_qns;
    for (auto group_item : by_left) {
        py::object q_left = py::reinterpret_borrow<py::object>(group_item.first);
        py::sequence keys = py::reinterpret_borrow<py::sequence>(group_item.second);
        ssize_t left_dim = -1;
        ssize_t cols_total = 0;
        struct Entry { py::object key; py::array_t<cdouble> block; ssize_t right_dim; ssize_t phys_dim; };
        std::vector<Entry> entries;
        for (ssize_t idx = 0; idx < static_cast<ssize_t>(py::len(keys)); ++idx) {
            py::object key = py::reinterpret_borrow<py::object>(keys[idx]);
            auto block = ensure_cdouble_array(py::reinterpret_borrow<py::object>(theta_data[key]));
            if (block.ndim() != 3) {
                throw std::runtime_error("block right RQ expects rank-3 site blocks");
            }
            const ssize_t block_left_dim = block.shape(0);
            const ssize_t right_dim = block.shape(1);
            const ssize_t phys_dim = block.shape(2);
            if (left_dim < 0) {
                left_dim = block_left_dim;
            } else if (left_dim != block_left_dim) {
                throw std::runtime_error("Inconsistent left-sector degeneracy in block RQ");
            }
            cols_total += right_dim * phys_dim;
            entries.push_back(Entry{key, block, right_dim, phys_dim});
        }
        if (left_dim <= 0 || cols_total <= 0) {
            continue;
        }
        py::array_t<cdouble> mat_t({cols_total, left_dim});
        auto mv = mat_t.mutable_unchecked<2>();
        ssize_t offset = 0;
        for (const auto& entry : entries) {
            auto bv = entry.block.unchecked<3>();
            for (ssize_t r = 0; r < entry.right_dim; ++r) {
                for (ssize_t p = 0; p < entry.phys_dim; ++p) {
                    const ssize_t row = offset + r * entry.phys_dim + p;
                    for (ssize_t l = 0; l < left_dim; ++l) {
                        mv(row, l) = bv(l, r, p);
                    }
                }
            }
            offset += entry.right_dim * entry.phys_dim;
        }
        py::tuple qr = lapack_qr(mat_t);
        auto q_t = qr[0].cast<py::array_t<cdouble>>();
        auto r_t = qr[1].cast<py::array_t<cdouble>>();
        const ssize_t chi = q_t.shape(1);
        if (chi == 0) {
            continue;
        }
        new_left_qns.append(q_left);
        py::array_t<cdouble> center({left_dim, chi});
        auto cv = center.mutable_unchecked<2>();
        auto rv = r_t.unchecked<2>();
        for (ssize_t l = 0; l < left_dim; ++l) {
            for (ssize_t c = 0; c < chi; ++c) {
                cv(l, c) = rv(c, l);
            }
        }
        data_center[py::make_tuple(q_left, q_left)] = center;
        auto qv = q_t.unchecked<2>();
        offset = 0;
        for (const auto& entry : entries) {
            py::sequence key_seq = entry.key.cast<py::sequence>();
            py::object out_key = py::make_tuple(
                q_left,
                py::reinterpret_borrow<py::object>(key_seq[1]),
                py::reinterpret_borrow<py::object>(key_seq[2])
            );
            py::array_t<cdouble> q_block({chi, entry.right_dim, entry.phys_dim});
            auto qb = q_block.mutable_unchecked<3>();
            for (ssize_t c = 0; c < chi; ++c) {
                for (ssize_t r = 0; r < entry.right_dim; ++r) {
                    for (ssize_t p = 0; p < entry.phys_dim; ++p) {
                        qb(c, r, p) = qv(offset + r * entry.phys_dim + p, c);
                    }
                }
            }
            data_q[out_key] = q_block;
            offset += entry.right_dim * entry.phys_dim;
        }
    }
    py::list center_qns;
    center_qns.append(get_axis_item(theta.attr("qns"), 0));
    center_qns.append(tuple_from_sequence_object(new_left_qns));
    py::list center_dirs;
    center_dirs.append(py::int_(-1));
    center_dirs.append(py::int_(1));
    py::list q_qns;
    q_qns.append(tuple_from_sequence_object(new_left_qns));
    q_qns.append(get_axis_item(theta.attr("qns"), 1));
    q_qns.append(get_axis_item(theta.attr("qns"), 2));
    return py::make_tuple(
        tensor_from_dict_like(tensor_cls, data_center, tuple_from_sequence_object(center_qns), tuple_from_sequence_object(center_dirs)),
        tensor_from_dict_like(tensor_cls, data_q, tuple_from_sequence_object(q_qns), theta.attr("dirs"))
    );
}

static py::object block_absorb_center_left_native(
    py::object center,
    py::object right_site,
    py::object tensor_cls
) {
    py::dict center_data = py::reinterpret_borrow<py::dict>(center.attr("data"));
    py::dict right_data = py::reinterpret_borrow<py::dict>(right_site.attr("data"));
    py::dict out;
    for (auto c_item : center_data) {
        py::object c_key = py::reinterpret_borrow<py::object>(c_item.first);
        py::sequence c_seq = c_key.cast<py::sequence>();
        py::object c_right = py::reinterpret_borrow<py::object>(c_seq[1]);
        auto c_block = ensure_cdouble_array(py::reinterpret_borrow<py::object>(c_item.second));
        auto cv = c_block.unchecked<2>();
        for (auto r_item : right_data) {
            py::object r_key = py::reinterpret_borrow<py::object>(r_item.first);
            py::sequence r_seq = r_key.cast<py::sequence>();
            if (!py_objects_equal(c_right, py::reinterpret_borrow<py::object>(r_seq[0]))) {
                continue;
            }
            auto r_block = ensure_cdouble_array(py::reinterpret_borrow<py::object>(r_item.second));
            auto rv = r_block.unchecked<3>();
            if (c_block.shape(1) != r_block.shape(0)) {
                throw std::runtime_error("absorb center left shape mismatch");
            }
            const ssize_t nl = c_block.shape(0);
            const ssize_t nk = c_block.shape(1);
            const ssize_t nr = r_block.shape(1);
            const ssize_t np = r_block.shape(2);
            py::array_t<cdouble> block({nl, nr, np});
            auto bv = block.mutable_unchecked<3>();
            for (ssize_t l = 0; l < nl; ++l) {
                for (ssize_t r = 0; r < nr; ++r) {
                    for (ssize_t p = 0; p < np; ++p) {
                        cdouble total = 0.0;
                        for (ssize_t k = 0; k < nk; ++k) {
                            total += cv(l, k) * rv(k, r, p);
                        }
                        bv(l, r, p) = total;
                    }
                }
            }
            py::object out_key = py::make_tuple(
                py::reinterpret_borrow<py::object>(c_seq[0]),
                py::reinterpret_borrow<py::object>(r_seq[1]),
                py::reinterpret_borrow<py::object>(r_seq[2])
            );
            add_block_to_output(out, out_key, block);
        }
    }
    py::list qns;
    qns.append(get_axis_item(center.attr("qns"), 0));
    qns.append(get_axis_item(right_site.attr("qns"), 1));
    qns.append(get_axis_item(right_site.attr("qns"), 2));
    py::list dirs;
    dirs.append(get_axis_item(center.attr("dirs"), 0));
    dirs.append(get_axis_item(right_site.attr("dirs"), 1));
    dirs.append(get_axis_item(right_site.attr("dirs"), 2));
    return tensor_from_dict_like(tensor_cls, out, tuple_from_sequence_object(qns), tuple_from_sequence_object(dirs));
}

static py::object block_absorb_center_right_native(
    py::object left_site,
    py::object center,
    py::object tensor_cls
) {
    py::dict left_data = py::reinterpret_borrow<py::dict>(left_site.attr("data"));
    py::dict center_data = py::reinterpret_borrow<py::dict>(center.attr("data"));
    py::dict out;
    for (auto l_item : left_data) {
        py::object l_key = py::reinterpret_borrow<py::object>(l_item.first);
        py::sequence l_seq = l_key.cast<py::sequence>();
        py::object l_right = py::reinterpret_borrow<py::object>(l_seq[1]);
        auto l_block = ensure_cdouble_array(py::reinterpret_borrow<py::object>(l_item.second));
        auto lv = l_block.unchecked<3>();
        for (auto c_item : center_data) {
            py::object c_key = py::reinterpret_borrow<py::object>(c_item.first);
            py::sequence c_seq = c_key.cast<py::sequence>();
            if (!py_objects_equal(l_right, py::reinterpret_borrow<py::object>(c_seq[0]))) {
                continue;
            }
            auto c_block = ensure_cdouble_array(py::reinterpret_borrow<py::object>(c_item.second));
            auto cv = c_block.unchecked<2>();
            if (l_block.shape(1) != c_block.shape(0)) {
                throw std::runtime_error("absorb center right shape mismatch");
            }
            const ssize_t nl = l_block.shape(0);
            const ssize_t nk = l_block.shape(1);
            const ssize_t np = l_block.shape(2);
            const ssize_t nr = c_block.shape(1);
            py::array_t<cdouble> block({nl, nr, np});
            auto bv = block.mutable_unchecked<3>();
            for (ssize_t l = 0; l < nl; ++l) {
                for (ssize_t r = 0; r < nr; ++r) {
                    for (ssize_t p = 0; p < np; ++p) {
                        cdouble total = 0.0;
                        for (ssize_t k = 0; k < nk; ++k) {
                            total += lv(l, k, p) * cv(k, r);
                        }
                        bv(l, r, p) = total;
                    }
                }
            }
            py::object out_key = py::make_tuple(
                py::reinterpret_borrow<py::object>(l_seq[0]),
                py::reinterpret_borrow<py::object>(c_seq[1]),
                py::reinterpret_borrow<py::object>(l_seq[2])
            );
            add_block_to_output(out, out_key, block);
        }
    }
    py::list qns;
    qns.append(get_axis_item(left_site.attr("qns"), 0));
    qns.append(get_axis_item(center.attr("qns"), 1));
    qns.append(get_axis_item(left_site.attr("qns"), 2));
    py::list dirs;
    dirs.append(get_axis_item(left_site.attr("dirs"), 0));
    dirs.append(get_axis_item(center.attr("dirs"), 1));
    dirs.append(get_axis_item(left_site.attr("dirs"), 2));
    return tensor_from_dict_like(tensor_cls, out, tuple_from_sequence_object(qns), tuple_from_sequence_object(dirs));
}

static std::vector<cdouble> lanczos_coefficients_native(
    const std::vector<double>& alpha,
    const std::vector<double>& beta,
    ssize_t actual_dim,
    double norm,
    double dt
) {
    std::vector<cdouble> coeffs(static_cast<size_t>(actual_dim), 0.0);
    if (actual_dim == 1) {
        coeffs[0] = norm * std::exp(cdouble(0.0, -dt * alpha[0]));
        return coeffs;
    }
    py::array_t<cdouble> h({actual_dim, actual_dim});
    auto hv = h.mutable_unchecked<2>();
    for (ssize_t i = 0; i < actual_dim; ++i) {
        for (ssize_t j = 0; j < actual_dim; ++j) {
            hv(i, j) = 0.0;
        }
        hv(i, i) = alpha[static_cast<size_t>(i)];
    }
    for (ssize_t i = 0; i < actual_dim - 1; ++i) {
        hv(i, i + 1) = beta[static_cast<size_t>(i)];
        hv(i + 1, i) = beta[static_cast<size_t>(i)];
    }
    HermitianEigenResult eig = lapack_hermitian_eigh_descending(h);
    for (ssize_t col = 0; col < actual_dim; ++col) {
        const cdouble phase = std::exp(cdouble(0.0, -dt * eig.values_desc[static_cast<size_t>(col)]));
        const cdouble first = std::conj(eig.vector(0, col)) * norm;
        for (ssize_t row = 0; row < actual_dim; ++row) {
            coeffs[static_cast<size_t>(row)] += eig.vector(row, col) * phase * first;
        }
    }
    return coeffs;
}

static py::object block_krylov_lanczos_native(
    py::object vec,
    const std::function<py::object(py::object)>& apply_heff,
    double dt,
    int krylov_dim,
    double tol,
    py::object tensor_cls
) {
    const double norm = block_tensor_norm_native(vec);
    if (norm <= tol) {
        return block_tensor_scaled_native(vec, 1.0, tensor_cls);
    }
    const int mmax = std::max(1, krylov_dim);
    std::vector<py::object> basis;
    basis.reserve(static_cast<size_t>(mmax));
    basis.push_back(block_tensor_scaled_native(vec, 1.0 / norm, tensor_cls));
    std::vector<double> alpha(static_cast<size_t>(mmax), 0.0);
    std::vector<double> beta(static_cast<size_t>(std::max(0, mmax - 1)), 0.0);
    py::object q_prev = py::none();
    double beta_prev = 0.0;
    ssize_t actual_dim = 1;
    for (int j = 0; j < mmax; ++j) {
        py::object q = basis[static_cast<size_t>(j)];
        py::object trial = apply_heff(q);
        if (!q_prev.is_none()) {
            block_tensor_add_scaled_inplace(trial, q_prev, -beta_prev);
        }
        const cdouble alpha_j = block_tensor_dot_native(q, trial);
        alpha[static_cast<size_t>(j)] = std::real(alpha_j);
        block_tensor_add_scaled_inplace(trial, q, -alpha_j);
        const double beta_j = block_tensor_norm_native(trial);
        actual_dim = static_cast<ssize_t>(j + 1);
        if (beta_j <= tol || j + 1 == mmax) {
            break;
        }
        beta[static_cast<size_t>(j)] = beta_j;
        q_prev = q;
        beta_prev = beta_j;
        basis.push_back(block_tensor_scaled_native(trial, 1.0 / beta_j, tensor_cls));
    }
    std::vector<cdouble> coeffs = lanczos_coefficients_native(
        alpha,
        beta,
        actual_dim,
        norm,
        dt
    );
    basis.resize(static_cast<size_t>(actual_dim));
    coeffs.resize(static_cast<size_t>(actual_dim));
    return block_tensor_linear_combination_native(coeffs, basis, tensor_cls);
}

static py::object evolve_site_lanczos_native(
    py::object theta,
    py::object left,
    py::object W,
    py::object right,
    double dt,
    int krylov_dim,
    double tol,
    py::object tensor_cls
) {
    CppAbelianTDVPSiteHeffPlan plan =
        CppAbelianTDVPSiteHeffPlan::from_tensors(theta, left, W, right);
    auto apply = [&](py::object local) -> py::object {
        return plan.apply_tensor(
            tensor_cls,
            local,
            left,
            W,
            right
        );
    };
    return block_krylov_lanczos_native(theta, apply, dt, krylov_dim, tol, tensor_cls);
}

static py::object evolve_bond_lanczos_native(
    py::object center,
    py::object left,
    py::object right,
    double dt,
    int krylov_dim,
    double tol,
    py::object tensor_cls
) {
    CppAbelianTDVPBondHeffPlan plan =
        CppAbelianTDVPBondHeffPlan::from_tensors(center, left, right);
    auto apply = [&](py::object local) -> py::object {
        return plan.apply_tensor(
            tensor_cls,
            local,
            left,
            right
        );
    };
    return block_krylov_lanczos_native(center, apply, -dt, krylov_dim, tol, tensor_cls);
}

py::tuple CppMovingEnvironment::one_site_tdvp_sweep(
    py::sequence factors,
    py::sequence mpo,
    py::object left_boundary,
    py::object right_boundary,
    double dt,
    py::object environment_tensor_cls,
    py::dict callbacks,
    int krylov_dim,
    double krylov_tol,
    const std::string& krylov_method,
    const std::string& env_plan_prefix
) {
    ++one_site_tdvp_sweep_calls;
    const double sweep_start = wall_seconds();
    long long site_evolutions = 0;
    long long bond_evolutions = 0;
    long long left_qr_calls = 0;
    long long right_rq_calls = 0;
    long long env_advances = 0;
    try {
        const ssize_t nsites = static_cast<ssize_t>(py::len(factors));
        if (nsites <= 0) {
            throw std::runtime_error("MovingEnvironment one-site TDVP sweep requires at least one site");
        }
        if (static_cast<ssize_t>(py::len(mpo)) != nsites) {
            throw std::runtime_error("MovingEnvironment one-site TDVP sweep MPS/MPO length mismatch");
        }
        one_site_tdvp_sweep_last_nsites = nsites;

        const std::string krylov_key = normalized_method_key(krylov_method);
        const bool native_lanczos = (
            krylov_key == "lanczos"
            || krylov_key == "hermitian"
            || krylov_key == "hermitian-lanczos"
        );
        auto optional_callback = [&](const char* name) -> py::object {
            py::str key(name);
            if (!callbacks.contains(key)) {
                return py::none();
            }
            return py::reinterpret_borrow<py::object>(callbacks[key]);
        };
        py::object evolve_site = optional_callback("evolve_site");
        py::object evolve_bond = optional_callback("evolve_bond");
        py::object left_qr = optional_callback("left_qr");
        py::object right_rq = optional_callback("right_rq");
        py::object absorb_center_left = optional_callback("absorb_center_left");
        py::object absorb_center_right = optional_callback("absorb_center_right");
        if (
            !native_lanczos
            && (
                evolve_site.is_none()
                || evolve_bond.is_none()
                || left_qr.is_none()
                || right_rq.is_none()
                || absorb_center_left.is_none()
                || absorb_center_right.is_none()
            )
        ) {
            throw std::runtime_error(
                "MovingEnvironment native one-site TDVP currently supports Lanczos; "
                "non-Lanczos methods require Python callbacks"
            );
        }

        std::vector<py::object> sites;
        std::vector<py::object> operators;
        sites.reserve(static_cast<size_t>(nsites));
        operators.reserve(static_cast<size_t>(nsites));
        for (ssize_t i = 0; i < nsites; ++i) {
            sites.push_back(py::reinterpret_borrow<py::object>(factors[i]));
            operators.push_back(py::reinterpret_borrow<py::object>(mpo[i]));
        }
        py::object site_tensor_cls = tensor_class_of(sites.front());

        if (nsites == 1) {
            if (native_lanczos) {
                sites[0] = evolve_site_lanczos_native(
                    sites[0],
                    left_boundary,
                    operators[0],
                    right_boundary,
                    dt,
                    krylov_dim,
                    krylov_tol,
                    site_tensor_cls
                );
            } else {
                sites[0] = evolve_site(
                    sites[0],
                    left_boundary,
                    operators[0],
                    right_boundary,
                    dt
                );
            }
            ++site_evolutions;
            py::list out_sites;
            out_sites.append(sites[0]);
            py::dict info;
            info["cpp_one_site_engine"] = true;
            info["cpp_one_site_engine_native_kernels"] = native_lanczos;
            info["cpp_one_site_engine_sites"] = py::int_(nsites);
            info["cpp_one_site_engine_site_evolutions"] = py::int_(site_evolutions);
            info["cpp_one_site_engine_bond_evolutions"] = py::int_(bond_evolutions);
            info["cpp_one_site_engine_left_qr_calls"] = py::int_(left_qr_calls);
            info["cpp_one_site_engine_right_rq_calls"] = py::int_(right_rq_calls);
            info["cpp_one_site_engine_environment_advances"] = py::int_(env_advances);
            one_site_tdvp_sweep_site_evolutions += site_evolutions;
            one_site_tdvp_sweep_seconds += wall_seconds() - sweep_start;
            one_site_tdvp_sweep_last_error.clear();
            return py::make_tuple(out_sites, info);
        }

        const double half_dt = 0.5 * dt;
        std::vector<py::object> right_envs(
            static_cast<size_t>(nsites + 1),
            py::none()
        );
        std::vector<py::object> left_envs(
            static_cast<size_t>(nsites),
            py::none()
        );
        right_envs[static_cast<size_t>(nsites)] = right_boundary;
        left_envs[0] = left_boundary;

        for (ssize_t i = nsites - 1; i >= 0; --i) {
            const std::string key =
                env_plan_prefix + ":right-build:" + std::to_string(i);
            py::tuple payload = environment_advance_auto(
                key,
                "right",
                operators[static_cast<size_t>(i)],
                sites[static_cast<size_t>(i)],
                right_envs[static_cast<size_t>(i + 1)],
                sites[static_cast<size_t>(i)]
            );
            right_envs[static_cast<size_t>(i)] =
                environment_tensor_from_payload(environment_tensor_cls, payload);
            ++env_advances;
        }

        py::object left = left_envs[0];
        for (ssize_t i = 0; i < nsites - 1; ++i) {
            if (native_lanczos) {
                sites[static_cast<size_t>(i)] = evolve_site_lanczos_native(
                    sites[static_cast<size_t>(i)],
                    left,
                    operators[static_cast<size_t>(i)],
                    right_envs[static_cast<size_t>(i + 1)],
                    half_dt,
                    krylov_dim,
                    krylov_tol,
                    site_tensor_cls
                );
            } else {
                sites[static_cast<size_t>(i)] = evolve_site(
                    sites[static_cast<size_t>(i)],
                    left,
                    operators[static_cast<size_t>(i)],
                    right_envs[static_cast<size_t>(i + 1)],
                    half_dt
                );
            }
            ++site_evolutions;

            py::sequence qr_result = (
                native_lanczos
                    ? block_left_qr_native(sites[static_cast<size_t>(i)], site_tensor_cls)
                    : left_qr(sites[static_cast<size_t>(i)])
            ).cast<py::sequence>();
            py::object q = py::reinterpret_borrow<py::object>(qr_result[0]);
            py::object center = py::reinterpret_borrow<py::object>(qr_result[1]);
            ++left_qr_calls;
            sites[static_cast<size_t>(i)] = q;

            const std::string env_key =
                env_plan_prefix + ":left-sweep:" + std::to_string(i);
            py::tuple env_payload = environment_advance_auto(
                env_key,
                "left",
                operators[static_cast<size_t>(i)],
                q,
                left,
                q
            );
            left = environment_tensor_from_payload(environment_tensor_cls, env_payload);
            left_envs[static_cast<size_t>(i + 1)] = left;
            ++env_advances;

            if (native_lanczos) {
                center = evolve_bond_lanczos_native(
                    center,
                    left,
                    right_envs[static_cast<size_t>(i + 1)],
                    half_dt,
                    krylov_dim,
                    krylov_tol,
                    site_tensor_cls
                );
            } else {
                center = evolve_bond(
                    center,
                    left,
                    right_envs[static_cast<size_t>(i + 1)],
                    half_dt
                );
            }
            ++bond_evolutions;
            sites[static_cast<size_t>(i + 1)] = (
                native_lanczos
                    ? block_absorb_center_left_native(
                        center,
                        sites[static_cast<size_t>(i + 1)],
                        site_tensor_cls
                    )
                    : absorb_center_left(
                        center,
                        sites[static_cast<size_t>(i + 1)]
                    )
            );
        }

        if (native_lanczos) {
            sites[static_cast<size_t>(nsites - 1)] = evolve_site_lanczos_native(
                sites[static_cast<size_t>(nsites - 1)],
                left_envs[static_cast<size_t>(nsites - 1)],
                operators[static_cast<size_t>(nsites - 1)],
                right_boundary,
                half_dt,
                krylov_dim,
                krylov_tol,
                site_tensor_cls
            );
        } else {
            sites[static_cast<size_t>(nsites - 1)] = evolve_site(
                sites[static_cast<size_t>(nsites - 1)],
                left_envs[static_cast<size_t>(nsites - 1)],
                operators[static_cast<size_t>(nsites - 1)],
                right_boundary,
                half_dt
            );
        }
        ++site_evolutions;

        py::object right = right_boundary;
        for (ssize_t i = nsites - 1; i > 0; --i) {
            if (native_lanczos) {
                sites[static_cast<size_t>(i)] = evolve_site_lanczos_native(
                    sites[static_cast<size_t>(i)],
                    left_envs[static_cast<size_t>(i)],
                    operators[static_cast<size_t>(i)],
                    right,
                    half_dt,
                    krylov_dim,
                    krylov_tol,
                    site_tensor_cls
                );
            } else {
                sites[static_cast<size_t>(i)] = evolve_site(
                    sites[static_cast<size_t>(i)],
                    left_envs[static_cast<size_t>(i)],
                    operators[static_cast<size_t>(i)],
                    right,
                    half_dt
                );
            }
            ++site_evolutions;

            py::sequence rq_result = (
                native_lanczos
                    ? block_right_rq_native(sites[static_cast<size_t>(i)], site_tensor_cls)
                    : right_rq(sites[static_cast<size_t>(i)])
            ).cast<py::sequence>();
            py::object center = py::reinterpret_borrow<py::object>(rq_result[0]);
            py::object q = py::reinterpret_borrow<py::object>(rq_result[1]);
            ++right_rq_calls;
            sites[static_cast<size_t>(i)] = q;

            const std::string env_key =
                env_plan_prefix + ":right-sweep:" + std::to_string(i);
            py::tuple env_payload = environment_advance_auto(
                env_key,
                "right",
                operators[static_cast<size_t>(i)],
                q,
                right,
                q
            );
            right = environment_tensor_from_payload(environment_tensor_cls, env_payload);
            ++env_advances;

            if (native_lanczos) {
                center = evolve_bond_lanczos_native(
                    center,
                    left_envs[static_cast<size_t>(i)],
                    right,
                    half_dt,
                    krylov_dim,
                    krylov_tol,
                    site_tensor_cls
                );
            } else {
                center = evolve_bond(
                    center,
                    left_envs[static_cast<size_t>(i)],
                    right,
                    half_dt
                );
            }
            ++bond_evolutions;
            sites[static_cast<size_t>(i - 1)] = (
                native_lanczos
                    ? block_absorb_center_right_native(
                        sites[static_cast<size_t>(i - 1)],
                        center,
                        site_tensor_cls
                    )
                    : absorb_center_right(
                        sites[static_cast<size_t>(i - 1)],
                        center
                    )
            );
        }

        if (native_lanczos) {
            sites[0] = evolve_site_lanczos_native(
                sites[0],
                left_boundary,
                operators[0],
                right,
                half_dt,
                krylov_dim,
                krylov_tol,
                site_tensor_cls
            );
        } else {
            sites[0] = evolve_site(
                sites[0],
                left_boundary,
                operators[0],
                right,
                half_dt
            );
        }
        ++site_evolutions;

        py::list out_sites;
        for (const auto& site : sites) {
            out_sites.append(site);
        }
        py::dict info;
        info["cpp_one_site_engine"] = true;
        info["cpp_one_site_engine_native_kernels"] = native_lanczos;
        info["cpp_one_site_engine_sites"] = py::int_(nsites);
        info["cpp_one_site_engine_site_evolutions"] = py::int_(site_evolutions);
        info["cpp_one_site_engine_bond_evolutions"] = py::int_(bond_evolutions);
        info["cpp_one_site_engine_left_qr_calls"] = py::int_(left_qr_calls);
        info["cpp_one_site_engine_right_rq_calls"] = py::int_(right_rq_calls);
        info["cpp_one_site_engine_environment_advances"] = py::int_(env_advances);

        one_site_tdvp_sweep_site_evolutions += site_evolutions;
        one_site_tdvp_sweep_bond_evolutions += bond_evolutions;
        one_site_tdvp_sweep_left_qr_calls += left_qr_calls;
        one_site_tdvp_sweep_right_rq_calls += right_rq_calls;
        one_site_tdvp_sweep_environment_advances += env_advances;
        one_site_tdvp_sweep_seconds += wall_seconds() - sweep_start;
        one_site_tdvp_sweep_last_error.clear();
        return py::make_tuple(out_sites, info);
    } catch (const py::error_already_set& exc) {
        ++one_site_tdvp_sweep_failures;
        one_site_tdvp_sweep_seconds += wall_seconds() - sweep_start;
        one_site_tdvp_sweep_last_error = exc.what();
        throw;
    } catch (const std::exception& exc) {
        ++one_site_tdvp_sweep_failures;
        one_site_tdvp_sweep_seconds += wall_seconds() - sweep_start;
        one_site_tdvp_sweep_last_error = exc.what();
        throw;
    }
}

py::tuple CppMovingEnvironment::sweep_environment_step(
    const std::string& direction,
    py::object tensor_cls,
    py::sequence update_rows,
    py::sequence pop_rows
) {
    const bool left = direction == "left";
    if (!left && direction != "right") {
        ++sweep_environment_step_failures;
        sweep_environment_step_last_error =
            "MovingEnvironment sweep environment step direction must be left or right";
        throw std::runtime_error(sweep_environment_step_last_error);
    }
    ++sweep_environment_step_calls;
    long long updates = 0;
    long long pops = 0;
    long long syncs = 0;
    try {
        const ssize_t n_updates = static_cast<ssize_t>(py::len(update_rows));
        for (ssize_t idx = 0; idx < n_updates; ++idx) {
            py::sequence row = py::reinterpret_borrow<py::sequence>(
                update_rows[idx]
            );
            std::string stack_key = py::cast<std::string>(row[0]);
            std::string plan_key = py::cast<std::string>(row[1]);
            std::string signature = py::cast<std::string>(row[2]);
            py::object W = py::reinterpret_borrow<py::object>(row[3]);
            py::object A = py::reinterpret_borrow<py::object>(row[4]);
            py::object B = py::reinterpret_borrow<py::object>(row[5]);
            py::object stack_obj = py::reinterpret_borrow<py::object>(row[6]);
            py::sequence stack = stack_obj.cast<py::sequence>();
            const ssize_t depth = static_cast<ssize_t>(py::len(stack));
            if (depth <= 0) {
                throw std::runtime_error(
                    "MovingEnvironment sweep environment update stack is empty"
                );
            }
            py::tuple synced = environment_stack_apply(
                stack_key,
                "sync",
                stack_obj,
                py::none()
            );
            if (py::cast<bool>(synced[0])) {
                ++syncs;
            }
            py::object env = py::reinterpret_borrow<py::object>(
                stack[depth - 1]
            );
            py::tuple payload = environment_advance(
                plan_key,
                direction,
                W,
                A,
                env,
                B,
                signature
            );
            py::object next_env = environment_tensor_from_payload(
                tensor_cls,
                payload
            );
            stack_obj.attr("append")(next_env);
            environment_stack_apply(
                stack_key,
                "push",
                py::none(),
                next_env
            );
            ++updates;
        }

        const ssize_t n_pops = static_cast<ssize_t>(py::len(pop_rows));
        for (ssize_t idx = 0; idx < n_pops; ++idx) {
            py::sequence row = py::reinterpret_borrow<py::sequence>(
                pop_rows[idx]
            );
            std::string stack_key = py::cast<std::string>(row[0]);
            py::object stack_obj = py::reinterpret_borrow<py::object>(row[1]);
            py::tuple popped = environment_stack_apply(
                stack_key,
                "pop",
                stack_obj,
                py::none()
            );
            if (py::cast<bool>(popped[0])) {
                ++syncs;
            }
            stack_obj.attr("pop")();
            ++pops;
        }
        sweep_environment_step_updates += updates;
        sweep_environment_step_pops += pops;
        sweep_environment_step_syncs += syncs;
        sweep_environment_step_last_error.clear();
        return py::make_tuple(
            py::int_(updates),
            py::int_(pops),
            py::int_(syncs),
            py::int_(0)
        );
    } catch (const py::error_already_set& exc) {
        ++sweep_environment_step_failures;
        sweep_environment_step_last_error = exc.what();
        throw;
    } catch (const std::exception& exc) {
        ++sweep_environment_step_failures;
        sweep_environment_step_last_error = exc.what();
        throw;
    }
}

py::tuple CppMovingEnvironment::sweep_environment_step_auto(
    const std::string& direction,
    py::object tensor_cls,
    py::sequence update_rows,
    py::sequence pop_rows
) {
    const bool left = direction == "left";
    if (!left && direction != "right") {
        ++sweep_environment_step_failures;
        sweep_environment_step_last_error =
            "MovingEnvironment sweep environment step direction must be left or right";
        throw std::runtime_error(sweep_environment_step_last_error);
    }
    ++sweep_environment_step_auto_calls;
    ++sweep_environment_step_calls;
    long long updates = 0;
    long long pops = 0;
    long long syncs = 0;
    try {
        const ssize_t n_updates = static_cast<ssize_t>(py::len(update_rows));
        for (ssize_t idx = 0; idx < n_updates; ++idx) {
            py::sequence row = py::reinterpret_borrow<py::sequence>(
                update_rows[idx]
            );
            std::string stack_key = py::cast<std::string>(row[0]);
            py::object W = py::reinterpret_borrow<py::object>(row[1]);
            py::object A = py::reinterpret_borrow<py::object>(row[2]);
            py::object B = py::reinterpret_borrow<py::object>(row[3]);
            py::object stack_obj = py::reinterpret_borrow<py::object>(row[4]);
            py::sequence stack = stack_obj.cast<py::sequence>();
            const ssize_t depth = static_cast<ssize_t>(py::len(stack));
            if (depth <= 0) {
                throw std::runtime_error(
                    "MovingEnvironment sweep environment update stack is empty"
                );
            }
            py::tuple synced = environment_stack_apply(
                stack_key,
                "sync",
                stack_obj,
                py::none()
            );
            if (py::cast<bool>(synced[0])) {
                ++syncs;
            }
            py::object env = py::reinterpret_borrow<py::object>(
                stack[depth - 1]
            );
            py::tuple payload = environment_advance_auto(
                stack_key,
                direction,
                W,
                A,
                env,
                B
            );
            py::object next_env = environment_tensor_from_payload(
                tensor_cls,
                payload
            );
            stack_obj.attr("append")(next_env);
            environment_stack_apply(
                stack_key,
                "push",
                py::none(),
                next_env
            );
            ++updates;
        }

        const ssize_t n_pops = static_cast<ssize_t>(py::len(pop_rows));
        for (ssize_t idx = 0; idx < n_pops; ++idx) {
            py::sequence row = py::reinterpret_borrow<py::sequence>(
                pop_rows[idx]
            );
            std::string stack_key = py::cast<std::string>(row[0]);
            py::object stack_obj = py::reinterpret_borrow<py::object>(row[1]);
            py::tuple popped = environment_stack_apply(
                stack_key,
                "pop",
                stack_obj,
                py::none()
            );
            if (py::cast<bool>(popped[0])) {
                ++syncs;
            }
            stack_obj.attr("pop")();
            ++pops;
        }
        sweep_environment_step_updates += updates;
        sweep_environment_step_pops += pops;
        sweep_environment_step_syncs += syncs;
        sweep_environment_step_last_error.clear();
        return py::make_tuple(
            py::int_(updates),
            py::int_(pops),
            py::int_(syncs),
            py::int_(0)
        );
    } catch (const py::error_already_set& exc) {
        ++sweep_environment_step_failures;
        sweep_environment_step_last_error = exc.what();
        throw;
    } catch (const std::exception& exc) {
        ++sweep_environment_step_failures;
        sweep_environment_step_last_error = exc.what();
        throw;
    }
}

py::tuple CppMovingEnvironment::bond_step_update_and_environment_auto(
    py::object bond_hint,
    py::array_t<cdouble, py::array::c_style | py::array::forcecast> py_v0,
    double tol,
    int max_iter,
    int restart_dim,
    bool accept_unconverged,
    py::object layout,
    py::object qns,
    py::object dirs,
    const std::string& split_direction,
    py::object tensor_cls,
    py::object m_max_obj,
    py::object sector_decoder,
    const std::string& environment_direction,
    py::sequence update_rows,
    py::sequence pop_rows
) {
    ++bond_step_transaction_calls;
    try {
        py::tuple local_update = grouped_davidson_split_flat_two_site_update_auto(
            bond_hint,
            py_v0,
            tol,
            max_iter,
            restart_dim,
            accept_unconverged,
            layout,
            qns,
            dirs,
            split_direction,
            tensor_cls,
            m_max_obj,
            sector_decoder
        );
        py::dict result = py::reinterpret_borrow<py::dict>(local_update[0]);
        const bool accepted = (
            result.contains(py::str("accepted"))
            && py::cast<bool>(result[py::str("accepted")])
            && !local_update[1].is_none()
            && !local_update[2].is_none()
        );
        if (!accepted) {
            return py::make_tuple(
                local_update[0],
                local_update[1],
                local_update[2],
                local_update[3],
                local_update[4],
                local_update[5],
                local_update[6],
                local_update[7],
                py::int_(0),
                py::int_(0),
                py::int_(0),
                py::int_(0)
            );
        }
        py::object left_site = py::reinterpret_borrow<py::object>(local_update[1]);
        py::object right_site = py::reinterpret_borrow<py::object>(local_update[2]);
        py::list resolved_update_rows;
        const ssize_t n_updates = static_cast<ssize_t>(py::len(update_rows));
        for (ssize_t idx = 0; idx < n_updates; ++idx) {
            py::sequence row = py::reinterpret_borrow<py::sequence>(
                update_rows[idx]
            );
            std::string stack_key = py::cast<std::string>(row[0]);
            py::object W = py::reinterpret_borrow<py::object>(row[1]);
            std::string site = py::cast<std::string>(row[2]);
            py::object stack_obj = py::reinterpret_borrow<py::object>(row[3]);
            py::object site_tensor;
            if (site == "left") {
                site_tensor = left_site;
            } else if (site == "right") {
                site_tensor = right_site;
            } else {
                throw std::runtime_error(
                    "MovingEnvironment bond-step update row site must be left or right"
                );
            }
            resolved_update_rows.append(
                py::make_tuple(
                    stack_key,
                    W,
                    site_tensor,
                    site_tensor,
                    stack_obj
                )
            );
        }
        py::tuple env_result = sweep_environment_step_auto(
            environment_direction,
            tensor_cls,
            resolved_update_rows,
            pop_rows
        );
        ++bond_step_transaction_accepted;
        bond_step_transaction_environment_updates += py::cast<long long>(env_result[0]);
        bond_step_transaction_last_error.clear();
        return py::make_tuple(
            local_update[0],
            local_update[1],
            local_update[2],
            local_update[3],
            local_update[4],
            local_update[5],
            local_update[6],
            local_update[7],
            env_result[0],
            env_result[1],
            env_result[2],
            env_result[3]
        );
    } catch (const py::error_already_set& exc) {
        ++bond_step_transaction_failures;
        bond_step_transaction_last_error = exc.what();
        throw;
    } catch (const std::exception& exc) {
        ++bond_step_transaction_failures;
        bond_step_transaction_last_error = exc.what();
        throw;
    }
}

static py::tuple packed_left_boundary_advance_payload_grouped(
    py::object W,
    py::object A_conj,
    py::object E,
    py::object B,
    py::dict a_by_left,
    py::dict w_by_left_phys,
    py::dict b_by_left_phys
) {
    py::sequence e_keys = py::reinterpret_borrow<py::sequence>(E.attr("keys"));
    py::sequence e_blocks = py::reinterpret_borrow<py::sequence>(E.attr("blocks"));
    py::dict out;
    for (ssize_t ei = 0; ei < static_cast<ssize_t>(py::len(e_keys)); ++ei) {
        py::object e_key = py::reinterpret_borrow<py::object>(e_keys[ei]);
        py::sequence e_seq = e_key.cast<py::sequence>();
        py::object a_group_key = py::reinterpret_borrow<py::object>(e_seq[1]);
        if (!a_by_left.contains(a_group_key)) {
            continue;
        }
        py::sequence a_group = py::reinterpret_borrow<py::sequence>(a_by_left[a_group_key]);
        for (ssize_t ai = 0; ai < static_cast<ssize_t>(py::len(a_group)); ++ai) {
            py::sequence a_item = py::reinterpret_borrow<py::sequence>(a_group[ai]);
            py::object a_key = py::reinterpret_borrow<py::object>(a_item[0]);
            py::sequence a_seq = a_key.cast<py::sequence>();
            py::object w_group_key = py::make_tuple(
                py::reinterpret_borrow<py::object>(e_seq[0]),
                py::reinterpret_borrow<py::object>(a_seq[2])
            );
            if (!w_by_left_phys.contains(w_group_key)) {
                continue;
            }
            py::sequence w_group = py::reinterpret_borrow<py::sequence>(w_by_left_phys[w_group_key]);
            for (ssize_t wi = 0; wi < static_cast<ssize_t>(py::len(w_group)); ++wi) {
                py::sequence w_item = py::reinterpret_borrow<py::sequence>(w_group[wi]);
                py::object w_key = py::reinterpret_borrow<py::object>(w_item[0]);
                py::sequence w_seq = w_key.cast<py::sequence>();
                py::object b_group_key = py::make_tuple(
                    py::reinterpret_borrow<py::object>(e_seq[2]),
                    py::reinterpret_borrow<py::object>(w_seq[3])
                );
                if (!b_by_left_phys.contains(b_group_key)) {
                    continue;
                }
                py::sequence b_group = py::reinterpret_borrow<py::sequence>(b_by_left_phys[b_group_key]);
                for (ssize_t bi = 0; bi < static_cast<ssize_t>(py::len(b_group)); ++bi) {
                    py::sequence b_item = py::reinterpret_borrow<py::sequence>(b_group[bi]);
                    py::object b_key = py::reinterpret_borrow<py::object>(b_item[0]);
                    py::sequence b_seq = b_key.cast<py::sequence>();
                    py::object out_key = py::make_tuple(
                        py::reinterpret_borrow<py::object>(w_seq[1]),
                        py::reinterpret_borrow<py::object>(a_seq[1]),
                        py::reinterpret_borrow<py::object>(b_seq[1])
                    );
                    py::array_t<cdouble> block = left_boundary_contract_block(
                        py::reinterpret_borrow<py::object>(e_blocks[ei]),
                        py::reinterpret_borrow<py::object>(a_item[1]),
                        py::reinterpret_borrow<py::object>(w_item[1]),
                        py::reinterpret_borrow<py::object>(b_item[1])
                    );
                    add_block_to_output(out, out_key, block);
                }
            }
        }
    }
    py::tuple key_blocks = dict_items_to_key_block_tuple(out);
    py::object w_dirs = W.attr("dirs");
    py::object a_dirs = A_conj.attr("dirs");
    py::object b_dirs = B.attr("dirs");
    py::list dirs;
    dirs.append(get_axis_item(w_dirs, 1));
    dirs.append(get_axis_item(a_dirs, 1));
    dirs.append(get_axis_item(b_dirs, 1));
    py::list qns;
    qns.append(get_axis_item(W.attr("qns"), 1));
    qns.append(get_axis_item(A_conj.attr("qns"), 1));
    qns.append(get_axis_item(B.attr("qns"), 1));
    return py::make_tuple(key_blocks[0], key_blocks[1], qns, dirs);
}

